INSERT INTO statutes(statute_id,name,short_name,issuer,effective_date,status,summary) VALUES ('stat_civil_lease','Relevant provisions of the Civil Code of the People''s Republic of China concerning lease contracts','Civil Code—Leasing','National People’s Congress','2021-01-01','Currently in force','Compile the general rules on lease terms, handover, repairs, deposits, and liability for breach of contract.');
INSERT INTO statutes(statute_id,name,short_name,issuer,effective_date,status,summary) VALUES ('stat_access_env','Relevant materials on the Law of the People''s Republic of China on the Development of an Accessible Environment','Law on the Construction of an Accessible Environment','Standing Committee of the National People''s Congress','2023-09-01','Currently in force','Compile the basic regulations concerning the construction, maintenance and management, and information exchange of accessible facilities.');
INSERT INTO statutes(statute_id,name,short_name,issuer,effective_date,status,summary) VALUES ('stat_privacy_rent','Materials on the Personal Information Protection Law of the People''s Republic of China in the context of rental housing','Personal Information Protection Law','Standing Committee of the National People''s Congress','2021-11-01','Currently in force','Explain the minimum-necessary principle when verifying the identity documents, student status, and contact information required for renting a property.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_lease_delivery','stat_civil_lease','Rental handover and terms',1,'Delivery status','The lessor shall deliver the premises as agreed; the condition of the facilities, the measured door width, and the ancillary equipment should preferably be recorded in writing in the handover checklist.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_lease_repair','stat_civil_lease','Repair obligations',2,'Repair responsibility','When the leased property needs repairs, both parties should determine the notification process, deadlines, costs, and alternative arrangements in accordance with the law and the contract.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_lease_fee','stat_civil_lease','Fees and Deposit',3,'Fee Details','Rent, deposit, agency service fee, cleaning fee, and other charges should be expressly agreed upon; oral promises should not replace written terms.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_access_maintain','stat_access_env','Facilities maintenance',1,'Maintenance of accessible facilities','Ramps, elevators, accessible passageways, and other facilities should remain in normal use and must not be occupied long-term by vehicles or miscellaneous items.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_access_info','stat_access_env','Information Provision',2,'Accessibility information','When providing information on entrances, slopes, door widths, and elevator operation, property managers should make it as accurate, timely, and easy to verify as possible.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_privacy_min','stat_privacy_rent','Minimum Necessary',1,'Minimal Processing of Personal Information','When verifying rental eligibility, the scope of information, processing purpose, and retention period should be limited; sensitive materials unrelated to the transaction should not be requested in advance.');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_e9d9aef4','(2023) E 0106 Civil First Instance No. 3454','Luogui Apartments Deposit Return Contract Dispute Case','court_wh_wuchang','Contract Dispute','Housing lease contract dispute','2023-11-04','Tenant Shen, Landlord Tang','Luogui Apartment deposit refund dispute: The landlord withheld the deposit on the grounds of deep cleaning, with the disputed amount being approximately 11006 yuan.','Tenant Shen moved into Luogui Apartment and later claimed that the landlord withheld the deposit on the grounds of deep cleaning; during the handover at Luogui Apartment, the tenant promptly sent written notice after discovering the issue, whereupon the parties disputed the timing of the notice and the scope of the costs.','The court, with respect to Luogui Apartment, examined the transfer records and handover photographs. These materials can establish the course of the transaction; in conjunction with the sequence in which the parties performed, it can be determined that signs of normal use cannot automatically be deemed damage, and oral statements unsupported by other evidence shall not serve as the primary basis.','Confirmation in the Luogui Apartment case: Signs of normal use cannot automatically be deemed damage; the issues involving door width, repairs, and service fees should all be determined based on specific written evidence.','Regarding the dispute concerning the Luogui Apartments, the court ordered the return of the portion of the deposit corresponding to unproven losses; the amount supported by documentation was determined to be 8705 yuan, with the remaining claims addressed separately.','Rejected','Wuhan, Rental, Deposit Refund, Door Width');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_ed439bcd','(2025) E01 Civil First-Instance No. 16429','Luogui Jiayuan Repair Liability Contract Dispute Case','court_wh_intermediate','Contract Dispute','Housing lease contract dispute','2025-06-28','Tenant Lin, Landlord Luo','Luogui Jiayuan Repair Liability Dispute: Following water seepage in the bathroom, the parties disagreed over the repair deadline; the disputed amount was approximately 1929 yuan.','After the tenancy at Luogui Jiayuan was established, a dispute arose because the parties disagreed over the repair deadline following water seepage in the bathroom. The property handover checklist did not record the disputed item, and the tenant and landlord subsequently each submitted evidence regarding the written attachments and actual losses.','In hearing the dispute over repair liability at Luogui Jiayuan, the collegial panel first verified the repair request work orders and on-site inspection reports, then compared the contract appendices with the notice records. Based on the evidence currently available, the landlord should bear corresponding liability for failing to make timely repairs after becoming aware of the issue, and liability should be allocated according to the actual impact.','The key point of the judgment is that a landlord bears corresponding liability if, after becoming aware of an issue, they fail to make repairs promptly; in the Luogui Jiayuan lease, the deposit, accessibility facilities, and repair deadline cannot be left to oral statements alone.','The Luogui Jiayuan repair liability matter was ultimately resolved on the basis that the responsible party would bear the repair costs and compensate for reasonable losses. After calculation, the supported amount was 1653 yuan; the portion exceeding the scope of the evidence was not supported.','Rejected','Wuhan, rental, repair responsibility, service fee');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_b0756797','(2024) E0102 Civil First-Instance No. 21389','Luogui Lixiang Door-Width Description Contract Dispute Case','court_wh_jiangan','Contract Dispute','Housing lease contract dispute','2024-08-27','Tenant Zhou, Landlord Xu','Luogui Lixiang Door-Width Description Dispute: The agent verbally promised a certain entrance door width, but measurements at handover did not match; the disputed amount is approximately 7877 yuan.','Regarding the Luogui Lixiang property, both parties acknowledge that the agent orally promised a certain entrance-door width, but the measurement at handover did not match; because the disputed item was not recorded in the property handover form, the parties were unable to agree on how the deposit, repair, or service costs should be allocated.','The chat records and door-width measurement photographs in the Luogui Lixiang case file corroborate each other and are consistent with the time records. On this basis, the court held that key residential conditions forming the basis for entering into the contract should be truthfully disclosed and strictly scrutinized the parties’ promises that were not written into the contract.','The court held in the Luo Gui Li Xiang case that key living conditions, when they form the basis for entering into the contract, must be truthfully disclosed, and that key costs and living conditions should be documented through contract appendices, handover forms, or notification records.','The court ruled regarding Luogui Lixiang: refund the service fee and adjust the liability for breach of contract; the established losses shall be counted toward liability in the amount of 981 yuan, and the parties shall continue performing the remainder of the contract.','Support','Wuhan, rental, door width details, repairs');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_8a905691','(2024) E 0111 Civil First-Instance No. 18621','Luogui Community elevator shutdown contract dispute case','court_wh_hongshan','Contract Dispute','Housing lease contract dispute','2024-09-21','Tenant Gu, landlord Han','Luogui Community elevator shutdown dispute: The prolonged shutdown of the elevator in a high-rise residential building affected normal use, with the disputed amount approximately 14778 yuan.','This case arose from the elevator shutdown issue after the handover of Luogui Community. The tenant submitted materials alleging that the prolonged shutdown of the elevator in the high-rise residential building affected normal use, while the landlord explained its handling by stating that “the tenant promptly sent written notice after discovering the problem.”','Regarding the elevator outage at Luogui Community, the court relied primarily on property management notices and maintenance records, while considering the condition at handover and subsequent remedial measures; rent may be reduced at the court’s discretion when the outage continues long enough to affect habitability.','Luogui Community case confirmation: Rent may be reduced at discretion when the continued shutdown reaches a level that affects habitability; the issues involving door width, repairs, and service fees should all be determined based on the specific written evidence.','Regarding the dispute concerning the Luogui community, the court ordered a partial reduction of rent for the affected period; the amount supported by documentation was determined to be 1993 yuan, with the remaining claims addressed separately.','Support','Wuhan, rental, elevator outage, repairs');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_0f2beb37','(2024) E 0106 Civil First Instance No. 26319','Luogui Xinyuan Passageway Obstruction Contract Dispute Case','court_wh_wuchang','Contract Dispute','Housing lease contract dispute','2024-04-23','Tenant Chen and landlord Wu','Dispute over the obstruction of a passageway at Luogui Xinyuan: The public ramp was repeatedly occupied by electric bicycles and miscellaneous items, involving a disputed amount of approximately 16582 yuan.','After moving into Luo Gui Xinyuan, tenant Chen claimed that the shared ramp was repeatedly occupied by electric bicycles and miscellaneous items. During the handover at Luo Gui Xinyuan, the landlord submitted repair quotations and proof of payment, leading the parties to disagree over the timing of notice and the scope of the costs.','The court, with respect to Luogui Xinyuan, examined the on-site video and property-management complaint records. These materials can establish the course of the transaction; in conjunction with the sequence in which the parties performed, it can be determined that the management party should take reasonable cleaning measures after receiving a report, and oral statements unsupported by other evidence shall not serve as the primary basis.','The key holding is that after receiving a report, the management party should take reasonable cleaning measures; in the Luogui Xinyuan lease, the deposit, accessibility facilities, and repair deadline cannot be based solely on oral statements.','The matter concerning the obstruction of the passageway at Luogui Xinyuan was ultimately resolved by requiring “cleanup within a specified period and improved inspections.” After calculation, the supported amount was 10851 yuan; any portion beyond the scope of the evidence was not supported.','Mediation','Wuhan, rental, passageway obstruction, door width');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_179ad4e7','(2025) E01 Civil First Instance No. 29540','Luogui Huating Intermediary Service Fee Contract Dispute Case','court_wh_intermediate','Contract Dispute','Housing lease contract dispute','2025-04-11','Tenant Tang, Landlord Jiang','Luogui Huating intermediary service fee dispute: After the signing failed, the intermediary charged the full service fee; the disputed amount was approximately 2295 yuan.','After the tenancy relationship at Luogui Huating was established, an issue arose in which “the intermediary charged the full service fee after the signing failed.” Upon discovering the issue, the tenant promptly sent written notice. The tenant and landlord subsequently submitted evidence concerning the written attachments and their respective actual losses.','When hearing the dispute over the intermediary service fee for Luogui Huating, the judicial panel first verified the service agreement and viewing records, then compared them with the contract appendices and notice records. Based on the evidence currently available, when the service has not been fully performed, the fee should be determined in light of the actual workload, and liability should be apportioned according to the actual impact.','In the Luogui Huating case, the court clarified that when services have not been fully performed, the fee should be determined based on the actual workload, and that key fees and living conditions should be documented in contract appendices, handover forms, or notice records.','The court ruled as follows regarding Luogui Huating: refund service fees that were not actually incurred; include the established loss of 1578 yuan in the liability; the parties shall continue performing the remainder of the contract in accordance with its terms.','Support','Wuhan, rental, agency service fee, door width');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_bc48685b','(2023) Hubei-0102 Civil Initial 11614','Luogui Neighborhood early lease termination contract dispute case','court_wh_jiangan','Contract Dispute','Housing lease contract dispute','2023-10-21','Tenant Luo, Landlord Ye','Luogui Neighborhood early lease termination dispute: The tenant sought early termination because of changes in living conditions, with the disputed amount approximately 4657 yuan.','Regarding the Luogui Block property, both parties acknowledge that the tenant requested early termination because the living conditions had changed; because the disputed item was not recorded in the property handover form, the parties were unable to agree on how the deposit, repair, or service costs should be allocated.','The contract attachments, correspondence emails, and timeline records in the Luogui Neighborhood case file corroborate one another. On that basis, the court held that liquidated damages may be adjusted in accordance with the law when they are excessively high and the losses are limited, and it strictly scrutinized promises not included in the contract made by either party.','Luogui Neighborhood case confirmation: Liquidated damages may be adjusted in accordance with the law when they are excessively high and the losses are limited; the issues involving door width, repairs, and service fees should all be determined based on the specific written evidence.','Regarding the dispute concerning the Luogui neighborhood, the court ordered appropriate liability based on the actual losses; the amount supported by documentation was determined to be 1154 yuan, with the remaining claims addressed separately.','Mediation','Wuhan, Early Lease Termination, Deposit');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_fc9d219b','(2024) Hubei 0111 Civil First Instance No. 4353','Luogui Linli Identity-Materials Contract Dispute Case','court_wh_hongshan','Contract Dispute','Housing lease contract dispute','2024-09-13','Tenant Xu, Landlord Shen','Luogui Linli identity-materials dispute: Before signing the contract, the intermediary requested excessive photographs of identity documents, involving a disputed amount of approximately 28994 yuan.','This case arose from the identification-materials issue after the handover of Luogui Neighborhood. The tenant submitted materials alleging that the agent requested too many photos of identification documents before the contract was signed, while the landlord explained its handling by stating that “the parties had previously coordinated through the property management office but failed to reach an agreement.”','Regarding the identity-document issue at Luogui Linli, the court relied primarily on information-collection pages and chat records, while considering the condition at handover and subsequent remedial measures; rental verification should follow the principles of a clearly defined purpose and minimum necessity.','The key holding is that lease verification should follow the principles of purpose specification and data minimization; in the Luogui Neighborhood lease, the deposit, accessibility facilities, and repair deadlines cannot rely solely on oral statements.','The Luogui Linli identity-materials matter was ultimately handled by “deleting irrelevant materials and ceasing further processing.” Upon calculation, the supported amount was 14331 yuan; the portion exceeding the scope of the evidence was not supported.','Support','Wuhan, rental, identity documents, accessibility');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_02564ec5','(2025) E0106 Civil First-Instance No. 5461','Luogui Xiaoyuan Written Attachment Contract Dispute Case','court_wh_wuchang','Contract Dispute','Housing lease contract dispute','2025-10-03','Tenant Han, landlord Lin','Luogui Xiaoyuan Written Attachment Dispute: The parties disputed oral promises concerning ramp repairs and cleaning fees, with the disputed amount approximately 18410 yuan.','After moving into Luo Gui Xiaoyuan, tenant Han claimed that a dispute had arisen over the parties’ oral agreement regarding ramp repairs and cleaning fees. During the handover at Luo Gui Xiaoyuan, the disputed issue was not recorded on the property handover form, and the parties consequently disagreed over the notification timing and the scope of the costs.','The court, with respect to Luogui Courtyard, examined the contract draft and recording summary. These materials can establish the course of the transaction; in conjunction with the sequence in which the parties performed, it can be determined that key matters capable of being included in an attachment should be based primarily on written agreement, and oral statements unsupported by other evidence shall not serve as the primary basis.','In the Luogui Xiaoyuan case, the court clarified that key matters capable of being included in an appendix should be governed primarily by written agreements, and that key fees and living conditions should be documented in contract appendices, handover forms, or notice records.','The court ruled as follows regarding Luogui Xiaoyuan: determine liability in accordance with the valid written terms; include the established loss of 1884 yuan in the liability; the parties shall continue performing the remainder of the contract in accordance with its terms.','Support','Wuhan, lease, written attachment, accessibility');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_88cb9f69','(2024) E 01 Civil First Instance No. 21737','Luogui Residential Community Noise-Related Rent Reduction Contract Dispute Case','court_wh_intermediate','Contract Dispute','Housing lease contract dispute','2024-03-08','Tenant Wu, Landlord Zhou','Luogui Residential Community noise-related rent reduction dispute: Long-term construction noise exceeded the reasonable tolerance level for ordinary living, with the disputed amount being approximately 28271 yuan.','After the lease relationship was established at Luogui Residential Community, a problem arose in which “long-term construction noise exceeded the reasonable tolerance level for ordinary living.” After discovering the problem, the tenant promptly sent written notice, and the tenant and lessor subsequently each submitted evidence regarding the written attachments and actual losses.','When hearing the dispute over a rent reduction for noise at Luogui Residential Area, the judicial panel first verified the construction notices and continuous audio recordings, then compared them with the contract appendices and notice records. Based on the evidence currently available, when the landlord knew of a significant impact but failed to disclose it, the landlord should bear liability, which should be apportioned according to the actual impact.','The Luogui Residential Community case confirmed that when a lessor knew of a material impact but failed to disclose it, the lessor should bear liability; the issues concerning doorway width, repairs, and service fees must all be determined based on specific written evidence.','Regarding the dispute concerning the Luogui residential area, the court ordered a discretionary reduction or waiver of rent during the affected period; the amount supported by documentation was determined to be 22753 yuan, with the remaining claims addressed separately.','Rejected','Wuhan, lease, noise-related rent reduction, security deposit');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_d9fad70d','(2023) E 0102 Civil First-Instance No. 8455','Luogui Dormitory Deposit Refund Contract Dispute Case','court_wh_jiangan','Contract Dispute','Housing lease contract dispute','2023-10-25','Tenant Jiang, Landlord Gu','Luogui Dormitory Deposit Return Dispute: The landlord withheld the deposit on the grounds of deep cleaning, with the disputed amount approximately 24835 yuan.','Regarding the Luogui Dormitory property, both parties acknowledge that the landlord withheld the deposit on the grounds of deep cleaning; because the tenant promptly sent written notice after discovering the issue, the parties were unable to agree on how the deposit, repair, or service costs should be allocated.','The transfer records, handover photos, and time records in the Luogui Dormitory case file corroborate one another. On this basis, the court held that normal signs of use cannot automatically be deemed damage and strictly scrutinized the parties’ promises that were not written into the contract.','The key point of the judgment is that signs of normal use cannot automatically be deemed damage; in the Luogui dormitory rental, the deposit, accessibility facilities, and repair deadline cannot be based solely on oral statements.','The Luogui Dormitory deposit refund matter was ultimately resolved on the basis that the portion of the deposit corresponding to unproven losses would be refunded. After calculation, the supported amount was 5042 yuan; the portion exceeding the scope of the evidence was not supported.','Mediation','Wuhan, Rental, Deposit Refund, Service Fee');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_6f06de5b','(2025) Hubei 0111 Civil First-Instance No. 28303','Luogui Yating Repair Responsibility Contract Dispute Case','court_wh_hongshan','Contract Dispute','Housing lease contract dispute','2025-02-18','Tenant Ye, Landlord Chen','Luogui Yating maintenance liability dispute: After water seepage in the bathroom, the two parties disagreed over the repair deadline; the disputed amount is approximately 10733 yuan.','This case arose from the repair-responsibility issue after the handover of Luogui Yating. The tenant submitted materials alleging that, after water seepage in the bathroom, the parties disagreed over the repair deadline, while the landlord explained its handling by stating that “the tenant promptly sent written notice after discovering the problem.”','Regarding the repair liability issue at Luogui Yating, the court relied primarily on repair requests and on-site inspection reports, while considering the condition at handover and subsequent remedial measures; a landlord who, after becoming aware of the issue, fails to make timely repairs should bear the corresponding liability.','The court held in the Luo Gui Yating case that a landlord who, after becoming aware of an issue, fails to make timely repairs should bear the corresponding liability, and that key costs and living conditions should be documented through contract appendices, handover forms, or notification records.','The court ruled regarding Luogui Yating: bear the repair costs and compensate for reasonable losses; the established losses shall be counted toward liability in the amount of 8857 yuan, and the parties shall continue performing the remainder of the contract.','Partial support','Wuhan, rental, repair responsibility, door width');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_1f884956','(2023) E 0106 Civil First Instance No. 4235','Luogui Chunxiao Door-Width Disclosure Contract Dispute Case','court_wh_wuchang','Contract Dispute','Housing lease contract dispute','2023-08-01','Tenant Shen, Landlord Tang','Luogui Chunxiao door-width disclosure dispute: The agent verbally promised a certain entrance-door width, but the measurement at handover did not match; the disputed amount was approximately 3356 yuan.','After moving into Luogui Chunxiao, Tenant Shen claimed that the intermediary had orally promised a certain entrance-door width, but the measurement at handover did not match. During the handover at Luogui Chunxiao, the landlord submitted repair quotations and proof of payment, and the parties consequently disagreed over the timing of notice and the scope of the costs.','Regarding Luogui Chunxiao, the court examined chat records and photographs measuring the doorway width. These materials establish the course of the transaction. In light of the sequence in which the parties performed, it may be found that key residential conditions forming the basis of the contract should have been truthfully disclosed; oral statements not supported by other evidence are not treated as the primary basis.','The Luogui Chunxiao case confirmed that key residential conditions forming the basis for entering into a contract should be truthfully disclosed; issues involving the door width, repairs, and service fees should all be determined based on specific written evidence.','Regarding the dispute concerning Luogui Chunxiao, the court ordered a refund of the service fee and an adjustment of liability for breach of contract; the amount supported by documentation was determined to be 2606 yuan, with the remaining claims addressed separately.','Support','Wuhan, rental, door width details, repairs');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_e46e4876','(2025) E01 Civil First Instance No. 5962','Luogui Heyuan Elevator Outage Contract Dispute Case','court_wh_intermediate','Contract Dispute','Housing lease contract dispute','2025-02-24','Tenant Lin, Landlord Luo','Luogui Heyuan elevator outage dispute: A high-rise residential elevator was out of service for an extended period, affecting normal use; the disputed amount was approximately 13199 yuan.','After the lease relationship for Luogui Heyuan was established, the issue arose that “the elevator in the high-rise residential building had been out of service for an extended period, affecting normal use.” The lessor submitted repair quotations and proof of payment, after which the lessee and lessor each presented evidence regarding the written attachments and actual losses.','When hearing the dispute over the elevator shutdown at Luogui Heyuan, the judicial panel first verified the property-management notices and maintenance records, then compared them with the contract appendices and notice records. Based on the evidence currently available, when a continuous shutdown reaches a level that affects habitability, a rent reduction may be granted at the court’s discretion, and liability should be apportioned according to the actual impact.','The key point of the ruling is that rent may be reduced at the court’s discretion when a prolonged service suspension reaches a level that affects habitability; in the Luogui Heye lease, the deposit, accessibility facilities, and repair deadlines cannot rely solely on oral statements.','The dispute over the Luogui Heyuan elevator outage was ultimately resolved by “reducing part of the rent based on the period affected.” After calculation, the supported amount was 8800 yuan; the portion exceeding the scope of the evidence was not supported.','Rejected','Wuhan, rental, elevator outage, accessibility');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_f35609d7','(2025) E0102 Civil First Instance No. 3437','Luogui Qingting Corridor Occupancy Contract Dispute Case','court_wh_jiangan','Contract Dispute','Housing lease contract dispute','2025-10-04','Tenant Zhou, Landlord Xu','Luogui Qingting accessway occupancy dispute: The public ramp has been repeatedly occupied by electric scooters and miscellaneous items, with the disputed amount approximately RMB 33789.','Regarding the Luogui Qingting property, both parties acknowledge that the public ramp was repeatedly occupied by electric bicycles and miscellaneous items; because the parties had previously tried to coordinate through the property management company but failed to reach an agreement, they were unable to agree on how the deposit, repair, or service costs should be allocated.','The on-site video and property complaint records in the Luogui Qingting case file corroborate the time records. On that basis, the court held that the management party should have taken reasonable cleanup measures after receiving the report and closely scrutinized promises made by both parties that were not included in the contract.','In the Luogui Qingting case, the court clarified that after receiving a report, the management party should take reasonable cleaning measures, and that key fees and living conditions should be documented in contract appendices, handover forms, or notice records.','The court ruled regarding Luogui Qingting: clean up within the prescribed period and improve inspections; the established losses shall be counted toward liability in the amount of 28574 yuan, and the parties shall continue performing the remainder of the contract.','Partial support','Wuhan, rental, passageway obstruction, deposit');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_ed348413','(2025) E 0111 Civil First-Instance No. 14900','Donghu Apartment Brokerage Service Fee Contract Dispute Case','court_wh_hongshan','Contract Dispute','Housing lease contract dispute','2025-12-20','Tenant Gu, landlord Han','Donghu Apartment Brokerage Service Fee Dispute: After no contract was concluded, the broker charged the entire service fee, with the disputed amount approximately 9978 yuan.','This case arose from a brokerage service fee issue after the handover of Donghu Apartment. The tenant submitted materials stating that the broker charged the full service fee after the contract was not concluded, while the landlord explained the handling process by stating that “the parties had previously coordinated through the property management company but failed to reach an agreement.”','For the dispute over an agency service fee at Donghu Apartment, the court treated the service agreement and property-viewing records as the primary evidence, considered the delivery status and subsequent remedial measures, and held that when the service was not fully performed, the fee should be determined in light of the actual workload.','Donghu Apartment Case Confirmation: When services have not been fully performed, the fee should be determined in light of the actual workload; issues involving the door width, repair fees, and service fees should all be determined based on the specific written evidence.','Regarding the Donghu Apartment dispute, the court ordered a refund of service fees that were not actually incurred; the amount supported by documentation was determined to be 5062 yuan, and the remaining claims were handled separately.','Mediation','Wuhan, rental, agency service fee, deposit');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_454711e4','(2023) E 0106 Civil First-Instance No. 20733','Donghu Jiayuan early-termination-of-lease contract dispute case','court_wh_wuchang','Contract Dispute','Housing lease contract dispute','2023-06-11','Tenant Chen and landlord Wu','Donghu Jiayuan early-termination-of-lease dispute: The tenant requested early termination due to changes in living conditions, involving a disputed amount of approximately 2120 yuan.','After moving into Donghu Jiayuan, Tenant Chen claimed that the tenant requested early termination due to changes in living conditions. During the handover at Donghu Jiayuan, the intermediary was unable to provide complete records of the service process, and the parties consequently disagreed over the timing of notice and the scope of the costs.','In the matter concerning Donghu Jiayuan, the court examined the contract attachments and correspondence emails. These materials establish how the transaction proceeded. In conjunction with the order in which the parties performed, it may be determined that liquidated damages may be adjusted in accordance with the law when they are excessively high and the loss is limited, while oral assertions unsupported by other evidence should not serve as the primary basis.','The key point of the ruling is that when liquidated damages are excessively high and the losses are limited, they may be adjusted in accordance with the law; in the Donghu Jiayuan lease, the deposit, accessibility facilities, and repair deadlines cannot rely solely on oral statements.','The Donghu Jiayuan early-termination-of-lease matter was ultimately handled on the basis of “assuming appropriate liability for actual losses.” After calculation, the supported amount was 721 yuan; the portion beyond the scope of the evidence was not supported.','Partial support','Wuhan, Early Lease Termination, Door Width');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_2189524b','(2024) Hubei 01 Civil First Instance No. 10388','Donghu Lixiang Identity Materials Contract Dispute Case','court_wh_intermediate','Contract Dispute','Housing lease contract dispute','2024-08-18','Tenant Tang, Landlord Jiang','Donghu Lixiang identity materials dispute: The agent requested too many photos of identity documents before signing, and the disputed amount was approximately 8054 yuan.','After the tenancy at Donghu Lixiang was established, an issue arose in which the agent had requested too many photos of identity documents before signing. The landlord submitted repair quotations and payment receipts, after which the tenant and landlord each provided evidence regarding the written attachments and actual losses.','When hearing the dispute over identity documents at Donghu Lixiang, the collegiate panel first verified the information-collection page and chat records, then compared the contract attachments with the notice records. Based on the evidence available, lease verification should follow the principles of a clear purpose and minimum necessity, and liability should be apportioned according to the actual impact.','In the Donghu Lixiang case, the court clarified that rental verification should follow the principles of specified purpose and minimum necessity; key costs and living conditions should be documented through contract appendices, handover forms, or notice records.','The court ruled as follows regarding Donghu Lixiang: delete irrelevant materials and cease further processing; established losses shall be included in the liability at 2348 yuan, and the parties shall continue performing the contract with respect to the remainder.','Mediation','Wuhan, rental, identity documents, door width');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_6958e8e0','(2023) E 0102 Civil First-Instance No. 19907','Donghu Community Written Attachment Contract Dispute Case','court_wh_jiangan','Contract Dispute','Housing lease contract dispute','2023-02-15','Tenant Luo, Landlord Ye','Donghu Community Written Attachment Dispute: The parties disputed their oral agreement regarding ramp repairs and cleaning fees, involving approximately 5814 yuan.','Regarding the Donghu Community property, both parties confirmed that a dispute had arisen over oral commitments by both parties concerning ramp repairs and cleaning fees. Because the agent failed to provide complete records of the service process, the parties were unable to reach agreement on how the deposit, repair costs, or service fees should be allocated.','The contract draft and recording summary in the Donghu Community case file corroborate each other with the time records. On this basis, the court held that key matters capable of being included in the attachments should be governed primarily by written agreements, and that promises not included in the contract should be examined strictly.','The Donghu Community case confirmed that key matters capable of being included in the attachments should be governed primarily by written agreements; the door width, repair costs, and service fees at issue should all be determined by reference to specific written evidence.','Regarding the Donghu Community dispute, the court ordered liability to be determined in accordance with the valid written terms; the amount supported by documentation was determined to be 4112 yuan, and the remaining claims were handled separately.','Mediation','Wuhan, lease, written attachment, service fee');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_b534217f','(2024) E 0111 Civil First-Instance No. 20030','Donghu Xinyuan Noise-Related Rent Reduction Contract Dispute Case','court_wh_hongshan','Contract Dispute','Housing lease contract dispute','2024-06-05','Tenant Xu, Landlord Shen','Donghu Xinyuan noise-related rent reduction dispute: Prolonged construction noise exceeded the reasonable tolerance for normal living, with the disputed amount approximately 24522 yuan.','This case arose from a rent reduction due to noise issue after the handover of Donghu Xinyuan. The tenant submitted materials stating that prolonged construction noise exceeded a reasonable level of tolerance for daily living, while the landlord explained the handling process by stating that “the landlord submitted repair quotations and proof of payment.”','For the rent-reduction dispute over noise at Donghu Xinyuan, the court treated the construction notice and continuous audio recordings as the primary evidence, considered the delivery status and subsequent remedial measures, and held that the landlord should bear liability when the landlord knew of the material impact but failed to disclose it.','The key holding is that a landlord should be held liable when the landlord knows of matters with a significant impact but fails to disclose them; in a Donghu Xinyuan rental, the deposit, accessibility facilities, and repair deadlines cannot be based solely on oral statements.','The Donghu Xinyuan noise-related rent reduction matter was ultimately handled by “discretionary reduction or waiver of rent for the affected period.” Upon calculation, the supported amount is 3825 yuan; the portion exceeding the scope of the evidence is not supported.','Rejected','Wuhan, lease, noise-related rent reduction, door width');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_190c8c6a','(2024) E 0106 Civil First-Instance No. 14852','Donghu Huating Deposit Refund Contract Dispute Case','court_wh_wuchang','Contract Dispute','Housing lease contract dispute','2024-07-08','Tenant Han, landlord Lin','Donghu Huating deposit refund dispute: The landlord withheld the deposit on the grounds of deep cleaning, with the disputed amount being approximately 29560 yuan.','After moving into Donghu Huating, tenant Han claimed that the landlord withheld the deposit on the grounds that deep cleaning was required. During the handover at Donghu Huating, the landlord submitted repair quotations and proof of payment, leading the parties to disagree over the timing of notice and the scope of the costs.','Regarding Donghu Huating, the court reviewed transfer records and handover photographs. These materials establish the course of the transaction. In light of the sequence in which the parties performed their obligations, traces of normal use cannot automatically be deemed damage. Oral assertions unsupported by other evidence shall not serve as the primary basis.','In the Donghu Huating case, the court clarified that normal signs of use cannot automatically be deemed damage; key costs and living conditions should be documented through contract appendices, handover forms, or notice records.','The court ruled regarding Donghu Huating: return the portion of the deposit for which losses were not proven; include the established losses of 3386 yuan in the liability; and have the parties continue performing the contract with respect to the remainder.','Support','Wuhan, Rental, Deposit Refund, Repairs');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_84e4ada9','(2023) E 01 Civil First-Instance No. 28854','Donghu Block Repair Responsibility Contract Dispute Case','court_wh_intermediate','Contract Dispute','Housing lease contract dispute','2023-06-01','Tenant Wu, Landlord Zhou','Donghu Block Repair Responsibility Dispute: After water seeped through the bathroom, the parties disagreed over the repair deadline, involving approximately 30264 yuan.','After the tenancy in Donghu Block was established, an issue arose involving “a disagreement between the parties over the repair deadline after water seeped through the bathroom.” The intermediary was unable to provide complete records of the service process, after which the tenant and landlord each presented evidence regarding the written attachments and actual losses.','When hearing the dispute over repair responsibilities at Donghu Jiequ, the collegiate panel first verified the repair requests and on-site inspection report, then compared the contract attachments with the notice records. Based on the evidence available, when the landlord, after becoming aware of the issue, failed to carry out repairs promptly, the landlord should bear corresponding liability, which should be apportioned according to the actual impact.','The Donghu Block case confirmed that a landlord who, after becoming aware of the issue, fails to make repairs promptly should bear corresponding liability; the door width, repair costs, and service fees at issue should all be determined by reference to specific written evidence.','Regarding the Donghu Neighborhood dispute, the court ordered payment of repair costs and compensation for reasonable losses; the amount supported by documentation was determined to be 23658 yuan, and the remaining claims were handled separately.','Partial support','Wuhan, rental, repair responsibility, service fee');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_db3e6db7','(2023) E 0102 Civil First-Instance No. 1161','Donghu Linli Door-Width Disclosure Contract Dispute Case','court_wh_jiangan','Contract Dispute','Housing lease contract dispute','2023-11-15','Tenant Jiang, Landlord Gu','Donghu Linli door-width disclosure dispute: the intermediary orally promised a certain entrance door width, but the measurement at delivery did not match; the disputed amount was approximately 29483 yuan.','Regarding the Donghu Linli property, both parties confirmed that the agent had orally promised that the entrance door would be wide enough, but measurements at handover did not match that promise. Because the agent failed to provide complete records of the service process, the parties were unable to reach agreement on how the deposit, repair costs, or service fees should be allocated.','The chat records and photos measuring the door width in the Donghu Linli case file corroborate each other with the time records. On this basis, the court held that key living conditions constituting the basis for entering into the contract should be truthfully disclosed, and that promises not included in the contract should be scrutinized strictly.','The key holding is that essential residential conditions forming the basis of a contract must be truthfully disclosed; in Donghu Neighborhood rentals, the deposit, accessibility facilities, and repair deadlines cannot be left solely to oral representations.','The Donghu Linli door-width disclosure matter was ultimately handled by “refunding the service fee and adjusting liability for breach of contract.” After calculation, the supported amount was 17495 yuan; the portion exceeding the scope of the evidence was not supported.','Rejected','Wuhan, rental, door width explanation, deposit');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_7362107e','(2023) E 0111 Civil First-Instance No. 24115','Donghu Xiaoyuan Elevator Shutdown Contract Dispute Case','court_wh_hongshan','Contract Dispute','Housing lease contract dispute','2023-02-17','Tenant Ye, Landlord Chen','Donghu Xiaoyuan elevator shutdown dispute: The prolonged shutdown of the elevator in the high-rise residential building affected normal use, with the disputed amount approximately 32716 yuan.','This case arose from an elevator outage issue after the handover of Donghu Xiaoyuan. The tenant submitted materials stating that the prolonged elevator outage in the high-rise residential building affected normal use, while the landlord explained the handling process by stating that “the tenant promptly sent written notice after discovering the problem.”','For the elevator outage at Donghu Courtyard, the court treated the property management notice and maintenance records as the primary evidence, considered the delivery status and subsequent remedial measures, and held that rent may be reduced at the court''s discretion when the continued outage reaches a level that affects habitability.','In the Donghu Xiaoyuan case, the court clarified that when a continuous service outage reaches a level affecting habitability, rent may be reduced at the court’s discretion; key costs and living conditions should be documented through contract appendices, handover forms, or notice records.','The court ruled regarding Donghu Xiaoyuan: reduce part of the rent for the period affected; include the established losses of 30342 yuan in the liability; and have the parties continue performing the contract with respect to the remainder.','Rejected','Wuhan, rental, elevator outage, door width');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_268be53b','(2025) E 0106 Civil First Instance No. 15457','Donghu Residential Community Accessway Occupancy Contract Dispute Case','court_wh_wuchang','Contract Dispute','Housing lease contract dispute','2025-04-15','Tenant Shen, Landlord Tang','Donghu Residential Community Accessway Occupancy Dispute: The public ramp was repeatedly occupied by electric bicycles and miscellaneous items, with the disputed amount approximately 13289 yuan.','After moving into Donghu Residential Community, Tenant Shen claimed that the public ramp was repeatedly occupied by electric bicycles and miscellaneous items. During the handover of Donghu Residential Community, the parties attempted to coordinate through the property management office but failed to reach an agreement, and consequently disagreed over the timing of the notice and the scope of the costs.','Regarding Donghu Residential Area, the court reviewed on-site video footage and property-management complaint records. These materials establish the course of the transaction. In light of the sequence in which the parties performed their obligations, the management party should be found to have been required to take reasonable cleanup measures after receiving the report. Oral assertions unsupported by other evidence shall not serve as the primary basis.','Donghu Residential Community Case Confirmation: Upon receiving a report, the management party should take reasonable cleanup measures; issues involving the door width, repair fees, and service fees should all be determined based on the specific written evidence.','Regarding the Donghu Residential Area dispute, the court ordered cleanup within a specified time limit and improvements to inspections; the amount supported by documentation was determined to be 6039 yuan, and the remaining claims were handled separately.','Support','Wuhan, rental, passageway obstruction, repairs');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_1d4bd7bf','(2024) E 01 Civil First Instance No. 16828','Donghu Dormitory Agency Service Fee Contract Dispute Case','court_wh_intermediate','Contract Dispute','Housing lease contract dispute','2024-09-24','Tenant Lin, Landlord Luo','Donghu Dormitory agency service fee dispute: After the lease signing fell through, the agency charged the entire service fee, with the disputed amount approximately 10187 yuan.','After the tenancy relationship at Donghu Dormitory was established, an issue arose in which the agency charged the entire service fee after the lease signing fell through. The parties previously attempted to resolve the matter through property management coordination but failed to reach an agreement; the tenant and landlord subsequently each presented evidence regarding the written attachments and actual losses.','When hearing the dispute over brokerage service fees for Donghu Dormitory, the collegiate panel first verified the service agreement and property-viewing records, then compared the contract attachments with the notice records. Based on the evidence available, when the service has not been fully performed, the fee should be determined in light of the actual workload, and liability should be apportioned according to the actual impact.','The key point of the ruling is that when services have not been fully performed, the fees should be determined based on the actual amount of work completed; in the Donghu Dormitory lease, the deposit, accessibility facilities, and repair deadlines cannot rely solely on oral statements.','The Donghu Dormitory intermediary service fee matter was ultimately handled on the basis of “refunding service fees that were not actually incurred.” After calculation, the supported amount was 2026 yuan; the portion beyond the scope of the evidence was not supported.','Mediation','Wuhan, rental, agency service fee, service fee');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_5c44e861','(2025) E0102 Civil First Instance No. 8521','Donghu Yating Early Lease Termination Contract Dispute Case','court_wh_jiangan','Contract Dispute','Housing lease contract dispute','2025-08-11','Tenant Zhou, Landlord Xu','Donghu Yating early lease termination dispute: The tenant requested early termination due to changes in living conditions, and the disputed amount was approximately 29644 yuan.','Regarding the Donghu Yating property, both parties confirmed that the tenant had requested early termination due to changes in the living conditions. Because the agent failed to provide complete records of the service process, the parties were unable to reach agreement on how the deposit, repair costs, or service fees should be allocated.','The contracts, attachments, correspondence emails, and time records in the Donghu Yating case file corroborate one another. On that basis, the court held that liquidated damages may be adjusted in accordance with the law when they are excessively high and the losses are limited, and that promises made by either party but not written into the contract should be scrutinized strictly.','In the Donghu Yating case, the court held that liquidated damages may be adjusted in accordance with the law when they are excessively high and the losses are limited; key fees and living conditions should be documented through contract appendices, handover forms, or notice records.','The court ruled as follows regarding Donghu Yating: assume appropriate liability based on the actual losses; established losses shall be included in the liability at 27806 yuan, and the parties shall continue performing the contract with respect to the remainder.','Support','Wuhan, Early Lease Termination, Accessibility');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_050fc7be','(2025) E 0111 Civil First-Instance No. 2472','Donghu Chunxiao Identity Materials Contract Dispute Case','court_wh_hongshan','Contract Dispute','Housing lease contract dispute','2025-04-13','Tenant Gu, landlord Han','Donghu Chunxiao identity document dispute: Before signing the contract, the intermediary requested photos of too many identity documents; the disputed amount was approximately 16,796 yuan.','This case arose from an identity-document issue after the handover of Donghu Chunxiao. The tenant submitted materials stating that the broker requested too many document photos before signing the contract, while the landlord explained the handling process by stating that “the parties had previously coordinated through the property management company but failed to reach an agreement.”','For the identity-document issue at Donghu Chunxiao, the court treated the information-collection page and chat records as the primary evidence, considered the delivery status and subsequent remedial measures, and held that rental verification should follow the principles of specified purpose and minimum necessity.','The Donghu Chunxiao case confirms that lease verification should follow the principles of a clearly defined purpose and minimum necessity, and that matters involving door width, repairs, and service fees should all be determined based on specific written evidence.','Regarding the Donghu Chunxiao dispute, the court ordered the deletion of irrelevant materials and an end to further processing; the amount supported by documentation was determined to be 9184 yuan, and the remaining claims were handled separately.','Partial support','Wuhan, rental, identity documents, deposit');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_b7444741','(2025) E0106 Civil First-Instance No. 3652','Donghu Heyuan Written Attachment Contract Dispute Case','court_wh_wuchang','Contract Dispute','Housing lease contract dispute','2025-06-08','Tenant Chen and landlord Wu','Donghu Heyuan written attachment dispute: The parties dispute oral commitments concerning ramp repairs and cleaning fees, involving a disputed amount of approximately 14213 yuan.','After moving into Donghu Heyuan, Tenant Chen claimed that the parties disputed their oral agreement regarding ramp repairs and cleaning fees. During the handover at Donghu Heyuan, the intermediary was unable to provide complete records of the service process, and the parties consequently disagreed over the timing of notice and the scope of the costs.','In the matter concerning Donghu Heyuan, the court examined the draft contract and recording summary. These materials establish how the transaction proceeded. In conjunction with the order in which the parties performed, it may be determined that key matters capable of being included in an attachment should primarily be based on written agreement, while oral assertions unsupported by other evidence should not serve as the primary basis.','The key holding is that key matters that can be included in an appendix should primarily be governed by written agreements; in the Donghu Heyuan lease, the deposit, accessibility facilities, and repair deadline cannot be based solely on oral statements.','The matter concerning the written attachments for Donghu Heyuan shall ultimately be handled according to “responsibility shall be determined based on valid written terms.” Upon calculation, the supported amount is 2038 yuan; portions exceeding the scope of the evidence will not be supported.','Mediation','Wuhan, lease, written attachment, repairs');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_e092dbcb','(2023) E 01 Civil First-Instance No. 28320','Donghu Qingting Noise-Related Rent Reduction Contract Dispute Case','court_wh_intermediate','Contract Dispute','Housing lease contract dispute','2023-09-09','Tenant Tang, Landlord Jiang','Donghu Qingting Noise-Related Rent Reduction Dispute: Prolonged construction noise exceeded the reasonable tolerance for normal living, with the disputed amount approximately 18080 yuan.','After the tenancy at Donghu Qingting was established, an issue arose involving “long-term construction noise exceeding a reasonable level of tolerance for daily life.” The intermediary was unable to provide complete records of the service process, after which the tenant and landlord each presented evidence regarding the written attachments and actual losses.','When hearing the dispute over a rent reduction for noise at Donghu Qingting, the collegiate panel first verified the construction notices and continuous audio recordings, then compared the contract attachments with the notice records. Based on the evidence available, when the landlord knew of a significant impact but still failed to disclose it, the landlord should bear liability, which should be apportioned according to the actual impact.','In the Donghu Qingting case, the court clarified that a lessor who knows of a significant impact but fails to disclose it must bear responsibility; key costs and living conditions should be documented through contract appendices, handover forms, or notice records.','The court ruled regarding Donghu Qingting: reduce the rent at its discretion for the affected period; include the established losses of 17069 yuan in the liability; and have the parties continue performing the contract with respect to the remainder.','Partial support','Wuhan, lease, noise-related rent reduction, door width');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_430b8afb','(2023) E 0102 Civil First-Instance No. 8431','Nanwang Apartment Deposit Return Contract Dispute Case','court_wh_jiangan','Contract Dispute','Housing lease contract dispute','2023-06-11','Tenant Luo, Landlord Ye','Nanwang Apartment deposit return dispute: The landlord withheld the deposit on the grounds of deep cleaning, with the disputed amount approximately 35253 yuan.','Regarding the property at Nanwang Apartment, both parties confirmed that the landlord had withheld the deposit on the grounds of deep cleaning; because the intermediary failed to provide complete records of the service process, they were unable to reach agreement on how the deposit, repair, or service costs should be borne.','The transfer records, handover photographs, and time records in the Nanwang Apartment case file corroborate one another. On that basis, the court held that ordinary signs of use cannot automatically be deemed damage and strictly examined promises between the parties that were not included in the contract.','Nanwang Apartment case confirmation: Ordinary signs of use cannot automatically be deemed damage; matters involving door width, repairs, and service fees must all be determined based on the specific written evidence.','Regarding the Nanwang apartment dispute, the court ordered the return of the portion of the deposit corresponding to unproven losses; the amount supported by documentation was determined to be 4047 yuan, and the remaining claims were handled separately.','Partial support','Wuhan, lease, deposit return, security deposit');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_fb2c75cb','(2023) E 0111 Civil First-Instance No. 19073','Nanwang Jiayuan repair responsibility contract dispute case','court_wh_hongshan','Contract Dispute','Housing lease contract dispute','2023-11-03','Tenant Xu, Landlord Shen','Nanwang Jiayuan repair responsibility dispute: After water seepage in the bathroom, the parties disagreed over the repair period, with the disputed amount approximately 11417 yuan.','This case arose from a repair-responsibility issue after the handover of Nanwang Jiayuan. The tenant submitted materials stating that the parties disagreed over the repair deadline after water seepage occurred in the bathroom, while the landlord explained its handling by saying that “the agency was unable to provide complete records of the service process.”','For the repair liability issue at Nanwang Jiayuan, the court primarily relied on the repair requests and on-site inspection report, considered the handover condition and subsequent remedial measures, and held that the landlord bears corresponding liability when, after becoming aware of the issue, it failed to make timely repairs.','The key point of the judgment is that a landlord bears corresponding liability if, after becoming aware of an issue, they fail to make repairs promptly; in the Nanwang Jiayuan lease, the deposit, accessibility facilities, and repair deadline cannot be left to oral statements alone.','The Nanwang Jiayuan repair responsibility matter was ultimately resolved on the basis that the responsible party would “bear the repair costs and compensate for reasonable losses.” Upon calculation, the supported amount was 7424 yuan; the portion exceeding the scope of the evidence was not supported.','Mediation','Wuhan, rental, repair responsibility, deposit');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_944fdcec','(2025) E 0106 Civil First Instance No. 12264','Nanwang Lane Entrance Width Description Contract Dispute Case','court_wh_wuchang','Contract Dispute','Housing lease contract dispute','2025-01-15','Tenant Han, landlord Lin','Nanwang Lane Entrance Width Description Dispute: The agent verbally promised a certain entrance gate width, but the measured width at handover did not match; the disputed amount is approximately 35,633 yuan.','After moving into Nanwang Lixiang, tenant Han claimed that the agent had orally promised a certain entrance-door width, but the measurement at handover did not match. During the handover of Nanwang Lixiang, the agent was unable to provide complete records of the service process, and the parties consequently disagreed over the timing of the notice and the scope of the fees.','In the matter concerning Nanwang Lixiang, the court examined chat records and photographs measuring the doorway width. These materials establish how the transaction proceeded. In conjunction with the order in which the parties performed, it may be determined that key residential conditions should be truthfully disclosed when they constitute the basis for entering into the contract, while oral assertions unsupported by other evidence should not serve as the primary basis.','In the Nanwang Lixiang case, the court clarified that key residential conditions forming the basis for entering into a contract must be truthfully disclosed, and that key fees and residential conditions should be documented through contract appendices, handover forms, or notification records.','The court ruled regarding Nanwang Lixiang: refund the service fee and adjust the liability for breach of contract; the verified losses are assessed at 11652 yuan and assigned as liability, while the parties shall continue performing the remainder of the contract.','Support','Wuhan, rental, door width details, accessibility');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_7d9dd83a','(2023) E 01 Civil First-Instance No. 26447','Nanwang Community Elevator Outage Contract Dispute Case','court_wh_intermediate','Contract Dispute','Housing lease contract dispute','2023-10-02','Tenant Wu, Landlord Zhou','Nanwang Community elevator shutdown dispute: The prolonged shutdown of elevators in a high-rise residential building affected normal use, with the disputed amount approximately 20436 yuan.','After the tenancy at Nanwang Community was established, the issue of “the prolonged shutdown of elevators in a high-rise residential building affecting normal use” arose. The property handover checklist did not record the disputed item, and the tenant and landlord subsequently each submitted evidence regarding the written attachments and actual losses.','When hearing the dispute over an elevator shutdown at Nanwang Community, the collegiate panel first verified the property-management notices and maintenance records, then compared the contract attachments with the notice records. Based on the evidence available, when a prolonged shutdown has reached a level that affects habitability, a rent reduction may be granted as appropriate, and liability should be apportioned according to the actual impact.','Nanwang Community Case Confirmation: When a prolonged elevator outage reaches a level that affects habitability, rent may be reduced at discretion; the issues involving door width, repairs, and service fees should all be assessed based on the specific written evidence.','Regarding the Nanwang community dispute, the court ordered a partial rent reduction for the affected period; the amount supported by documentation was determined to be 11682 yuan, and the remaining claims were handled separately.','Rejected','Wuhan, rental, elevator outage, accessibility');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_276bdc67','(2025) E0102 Civil First Instance No. 22724','Nanwang Xinyuan Passageway-Occupancy Contract Dispute Case','court_wh_jiangan','Contract Dispute','Housing lease contract dispute','2025-10-23','Tenant Jiang, Landlord Gu','Nanwang Xinyuan passageway-occupancy dispute: the public ramp was repeatedly occupied by electric bicycles and miscellaneous items, involving a disputed amount of approximately 10104 yuan.','Regarding the Nanwang Xinyuan property, the parties confirm that the common ramp was repeatedly obstructed by electric bicycles and miscellaneous items; because the disputed items were not recorded on the property handover checklist, they were unable to reach agreement on how the deposit, repair costs, or service fees should be allocated.','The on-site video and property complaint records in the Nanwang Xinyuan case file corroborate the recorded timeline. On this basis, the court found that the management party should have taken reasonable cleaning measures after receiving the report, and subjected promises not included in the contract between the parties to strict scrutiny.','The key holding is that after receiving a report, the management party should take reasonable cleanup measures; in the Nanwang Xinyuan lease, the deposit, accessibility facilities, and repair deadlines cannot rely solely on oral statements.','The Nanwang Xinyuan passageway-occupancy matter was ultimately handled by requiring “clearance within a specified period and improved inspections.” After calculation, the supported amount was 8076 yuan; the portion exceeding the scope of the evidence was not awarded.','Support','Wuhan, rental, passageway obstruction, repairs');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_fe234ded','(2025) E 0111 Civil First-Instance No. 1719','Nanwang Huating Brokerage Service Fee Contract Dispute Case','court_wh_hongshan','Contract Dispute','Housing lease contract dispute','2025-10-28','Tenant Ye, Landlord Chen','Nanwang Huating brokerage service fee dispute: after the contract was not concluded, the broker charged the full service fee; the disputed amount was approximately 1843 yuan.','This case arose from an agency service-fee issue after the handover of Nanwang Huating. The tenant submitted materials stating that the agency had charged the full service fee after the lease was not signed, while the landlord explained its handling by saying that “the agency was unable to provide complete records of the service process.”','For the agency service fee issue at Nanwang Huating, the court primarily relied on the service agreement and property-viewing records, considered the handover condition and subsequent remedial measures, and held that when the service was not fully performed, the fee should be determined in light of the actual amount of work completed.','In the Nanwang Huating case, the court held that when services have not been fully performed, fees should be determined based on the actual workload; key fees and living conditions should be documented through contract appendices, handover forms, or notice records.','The court ruled as follows regarding Nanwang Huating: refund service fees that were not actually incurred; established losses shall be included in the liability at 638 yuan, and the parties shall continue performing the contract with respect to the remainder.','Support','Wuhan, rental, agency service fee, service fee');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_e40fe852','(2023) E 0106 Civil First Instance No. 9269','Nanwang Neighborhood Early Lease Termination Contract Dispute Case','court_wh_wuchang','Contract Dispute','Housing lease contract dispute','2023-10-18','Tenant Shen, Landlord Tang','Nanwang Neighborhood early lease termination dispute: The tenant sought early termination because living conditions had changed, with the disputed amount approximately 18684 yuan.','After moving into Nanwang Neighborhood, Tenant Shen claimed that the tenant requested early termination due to changed living conditions. During the handover of Nanwang Neighborhood, the landlord submitted a repair quotation and proof of payment, and the parties consequently disagreed over the timing of the notice and the scope of the costs.','In the matter concerning Nanwang Jiequ, the court examined the contract attachments and correspondence emails. These materials establish how the transaction proceeded. In conjunction with the order in which the parties performed, it may be determined that liquidated damages may be adjusted in accordance with the law when they are excessively high and the loss is limited, while oral assertions unsupported by other evidence should not serve as the primary basis.','The Nanwang Neighborhood case confirmed that when liquidated damages are excessively high and losses are limited, they may be adjusted in accordance with the law; the issues involving door width, repairs, and service fees must all be determined based on the specific written evidence.','Regarding the Nanwang neighborhood dispute, the court ordered appropriate liability to be assumed based on the actual losses; the amount supported by documentation was determined to be 18562 yuan, and the remaining claims were handled separately.','Rejected','Wuhan, Early Lease Termination, Deposit');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_17efd3e1','(2024) E01 Civil First Instance Case No. 26119','Nanwang Linli Identity-Document Contract Dispute Case','court_wh_intermediate','Contract Dispute','Housing lease contract dispute','2024-03-17','Tenant Lin, Landlord Luo','Nanwang Linli identity-document dispute: The agent requested too many photos of identity documents before signing, involving a disputed amount of approximately 26019 yuan.','After the rental relationship at Nanwang Linli was established, an issue arose involving the agent requesting too many photos of identity documents before signing. The landlord submitted repair quotations and payment receipts, after which the tenant and landlord each submitted evidence regarding the written attachments and actual losses.','When hearing the dispute over identity documents at Nanwang Linli, the collegiate panel first verified the information-collection page and chat records, then compared the contract attachments with the notice records. Based on the evidence available, lease verification should follow the principles of a clear purpose and minimum necessity, and liability should be apportioned according to the actual impact.','The key point of the judgment is that rental verification should follow the principles of a clearly defined purpose and minimum necessity; in the Nanwang neighborhood rental, the deposit, accessibility facilities, and repair deadline cannot be based solely on oral statements.','The Nanwang Linli identity-document matter was ultimately handled by “deleting unrelated materials and ceasing further processing.” After calculation, the supported amount was 17961 yuan; the portion exceeding the scope of the evidence was not supported.','Rejected','Wuhan, rental, identity documents, repairs');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_7947dab6','(2024) E 0102 Civil First-Instance No. 8527','Contract dispute case concerning the written attachment to the Nanwang Xiaoyuan agreement','court_wh_jiangan','Contract Dispute','Housing lease contract dispute','2024-10-02','Tenant Zhou, Landlord Xu','Nanwang Xiaoyuan written attachment dispute: the parties disagreed over oral promises concerning ramp repairs and cleaning fees, involving approximately 8664 yuan.','Regarding the Nanwang Xiaoyuan property, the parties confirm that a dispute arose over oral promises concerning ramp repairs and cleaning fees; because the tenant promptly sent written notice after discovering the issue, they were unable to reach agreement on how the deposit, repair costs, or service fees should be allocated.','The draft contract, recording summary, and timeline records in the Nanwang Xiaoyuan case file corroborate one another. On this basis, the court held that key matters that could have been included in the attachment should primarily be governed by written agreements, and that promises not included in the contract should be examined strictly.','In the Nanwang Xiaoyuan case, the court held that key matters capable of being included in an appendix should primarily be governed by written agreements; key fees and living conditions should be documented through contract appendices, handover forms, or notice records.','The court ruled as follows regarding Nanwang Xiaoyuan: determine liability in accordance with the valid written provisions; established losses shall be included in the liability at 2252 yuan, and the parties shall continue performing the contract with respect to the remainder.','Support','Wuhan, lease, written attachment, repairs');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_89352bb1','(2025) E0111 Civil First-Instance No. 12718','Nanwang Residential Community Noise-Related Rent Reduction Contract Dispute Case','court_wh_hongshan','Contract Dispute','Housing lease contract dispute','2025-11-27','Tenant Gu, landlord Han','Nanwang Residential Community noise-related rent reduction dispute: Long-term construction noise exceeded reasonable levels of tolerance for ordinary living, with the disputed amount approximately 21474 yuan.','This case arose from a rent-reduction issue due to noise after the handover of Nanwang Residential Community. The tenant submitted materials stating that prolonged construction noise exceeded reasonable residential tolerance, while the landlord explained its handling by saying that “the parties had coordinated through the property management company but failed to reach an agreement.”','For the noise-related rent reduction issue at Nanwang Zhuqu, the court primarily relied on the construction notice and continuous audio recordings, considered the handover condition and subsequent remedial measures, and held that the landlord is liable when, despite knowing of the material impact, it failed to disclose it.','Nanwang Residential Community case confirmation: When a landlord knows of a significant adverse impact but fails to disclose it, the landlord should bear responsibility; matters involving door width, repairs, and service fees must all be determined based on the specific written evidence.','Regarding the Nanwang residential area dispute, the court ordered a discretionary reduction or waiver of rent for the affected period; the amount supported by documentation was determined to be 9872 yuan, and the remaining claims were handled separately.','Partial support','Wuhan, lease, noise-related rent reduction, door width');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_d3fe480c','(2023) E 0106 Civil First-Instance No. 11231','Contract dispute case concerning the refund of the Nanwang Dormitory deposit','court_wh_wuchang','Contract Dispute','Housing lease contract dispute','2023-11-22','Tenant Chen and landlord Wu','Nanwang Dormitory deposit refund dispute: the landlord withheld approximately 19177 yuan of the deposit on the grounds of deep cleaning.','After moving into Nanwang Dormitory, tenant Chen claimed that the landlord withheld the deposit on the grounds of deep cleaning. During the handover at Nanwang Dormitory, the property handover form did not record the disputed item, and the parties consequently disputed the timing of the notice and the scope of the costs.','In the matter concerning Nanwang Sushe, the court examined transfer records and handover photographs. These materials establish how the transaction proceeded. In conjunction with the order in which the parties performed, it may be determined that signs of normal use cannot automatically be deemed damage, while oral assertions unsupported by other evidence should not serve as the primary basis.','The key point of the judgment is that signs of normal use cannot automatically be deemed damage; in the Nanwang dormitory rental, the deposit, accessibility facilities, and repair deadline cannot be based solely on oral statements.','The final resolution of the Nanwang Dormitory deposit refund matter was to “return the portion of the deposit for which no loss was proven.” Upon calculation, the supported amount was 16840 yuan; the portion exceeding the evidentiary scope was not supported.','Support','Wuhan, Rental, Deposit Refund, Accessibility');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_9090bc4c','(2025) E01 Civil First-Instance No. 18907','Nanwang Yating Dispute over Contractual Repair Responsibilities','court_wh_intermediate','Contract Dispute','Housing lease contract dispute','2025-03-28','Tenant Tang, Landlord Jiang','Nanwang Yating repair responsibility dispute: After water seeped through the bathroom, the parties disagreed over the repair timeline, with the disputed amount being approximately 35,605 yuan.','After the rental relationship at Nanwang Yating was established, a dispute arose over the repair timeline after water seeped through the bathroom. The landlord submitted repair quotations and proof of payment, and the tenant and landlord subsequently each submitted evidence regarding the written attachments and actual losses.','In hearing the dispute over repair liability at Nanwang Yating, the judicial panel first verified the repair request orders and on-site inspection reports, then compared them with the contract appendices and notice records. Based on the evidence currently available, the landlord should bear corresponding liability for failing to make timely repairs after becoming aware of the issue, with liability apportioned according to the actual impact.','In the Nanwang Yating case, the court clarified that a landlord who fails to make timely repairs after becoming aware of the issue should bear the corresponding liability, and that key fees and residential conditions should be documented through contract appendices, handover forms, or notification records.','The court ruled regarding Nanwang Yating: bear the repair costs and compensate for reasonable losses; the verified losses are assessed at 1287 yuan and assigned as liability, while the parties shall continue performing the remainder of the contract.','Partial support','Wuhan, rental, repair responsibility, deposit');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_99cfbfc9','(2023) E 0102 Civil First-Instance No. 19107','Nanwang Chunxiao Door-Width Disclosure Contract Dispute Case','court_wh_jiangan','Contract Dispute','Housing lease contract dispute','2023-11-16','Tenant Luo, Landlord Ye','Nanwang Chunxiao door-width disclosure dispute: An intermediary verbally promised a certain entrance-door width, but the measurement at delivery did not match; the disputed amount was approximately 35899 yuan.','Regarding the Nanwang Chunxiao property, the parties confirm that the intermediary verbally promised a certain entrance-door width, but the measurement at handover did not match; because the landlord submitted repair quotations and proof of payment, they were unable to reach agreement on how the deposit, repair costs, or service fees should be allocated.','The chat records, door-width measurement photos, and time records in the Nanwang Chunxiao case corroborate one another. On this basis, the court held that key residential conditions must be truthfully disclosed when they form the basis for entering into a contract, and that promises between the parties not included in the contract should be examined strictly.','The Nanwang Chunxiao case confirmed that key residential conditions must be truthfully disclosed when they form the basis for entering into a contract; the door width, repair costs, and service fees at issue should all be determined based on specific written evidence.','Regarding the Nanwang Chunxiao dispute, the court ordered the service fee to be refunded and adjusted the contractual liability for breach; the amount supported by documentation was determined to be 28758 yuan, and the remaining claims were handled separately.','Partial support','Wuhan, rental, door width details, repairs');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_b880d57e','(2023) E 0111 Civil First-Instance No. 15441','Nanwang Heyuan Elevator Shutdown Contract Dispute Case','court_wh_hongshan','Contract Dispute','Housing lease contract dispute','2023-01-07','Tenant Xu, Landlord Shen','Nanwang Heyuan elevator shutdown dispute: The prolonged shutdown of elevators in a high-rise residential building affected normal use, with the disputed amount approximately 4466 yuan.','This case arose from an elevator shutdown issue after the handover of Nanwang Heyuan. The tenant submitted materials stating that the prolonged shutdown of the elevator in the high-rise residential building affected normal use, while the landlord explained its handling by saying that “the agency was unable to provide complete records of the service process.”','For the elevator shutdown issue at Nanwang Heyuan, the court primarily relied on property-management notices and maintenance records, considered the handover condition and subsequent remedial measures, and held that rent may be reduced at the court’s discretion when the prolonged shutdown reaches a level that affects habitability.','The key point of the judgment is that rent may be reduced at the court''s discretion when a prolonged shutdown reaches a level that affects habitability; in the Nanwang Heyuan lease, the deposit, accessibility facilities, and repair deadline cannot be left to oral statements alone.','The Nanwang Heyuan elevator shutdown matter shall ultimately be handled by “reducing part of the rent for the affected period.” Upon calculation, the supported amount is 4226 yuan; no support is given to the portion exceeding the scope of the evidence.','Rejected','Wuhan, rental, elevator outage, service fee');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_72940c7f','(2024) E 0106 Civil First Instance No. 20111','Nanwang Qingting Passageway Occupation Contract Dispute Case','court_wh_wuchang','Contract Dispute','Housing lease contract dispute','2024-11-11','Tenant Han, landlord Lin','Nanwang Qingting Passageway Occupation Dispute: The public ramp was repeatedly occupied by electric scooters and miscellaneous items, involving a disputed amount of approximately 11,513 yuan.','After moving into Nanwang Qingting, tenant Han claimed that the public ramp was repeatedly obstructed by electric bicycles and miscellaneous items. During the handover of Nanwang Qingting, the agent was unable to provide complete records of the service process, and the parties consequently disagreed over the timing of the notice and the scope of the fees.','In the matter concerning Nanwang Qingting, the court examined on-site video and property-management complaint records. These materials establish how the transaction proceeded. In conjunction with the order in which the parties performed, it may be determined that the management party should take reasonable cleanup measures after receiving a report, while oral assertions unsupported by other evidence should not serve as the primary basis.','In the Nanwang Qingting case, the court held that the management party should take reasonable cleanup measures after receiving a report; key fees and living conditions should be documented through contract appendices, handover forms, or notice records.','The court ruled regarding Nanwang Qingting: complete the cleanup and improve inspections within a specified period; the verified losses are assessed at 1584 yuan and assigned as liability, while the parties shall continue performing the remainder of the contract.','Rejected','Wuhan, rental, passageway obstruction, accessibility');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_1478ba49','(2024) E01 Civil First Instance Case No. 7202','Chufeng Apartment Intermediary Service Fee Contract Dispute Case','court_wh_intermediate','Contract Dispute','Housing lease contract dispute','2024-06-22','Tenant Wu, Landlord Zhou','Chufeng Apartment intermediary service fee dispute: after the contract was not concluded, the intermediary charged the entire service fee, with the disputed amount being approximately 21185 yuan.','After the tenancy at Chufeng Apartment was established, a problem arose in which the intermediary charged the entire service fee after the contract was not concluded. The parties had attempted to resolve the matter through property-management mediation but failed to reach an agreement, after which the tenant and landlord each submitted evidence concerning the written attachments and actual losses.','In hearing the dispute over intermediary service fees for Chufeng Apartment, the adjudicating panel first checked the service agreement and property-viewing records, then compared the contract appendices with the notification records. Based on the existing evidence, where the services were not fully performed, the fees should be determined in light of the actual workload, and liability should be apportioned according to the actual impact.','The Chufeng Apartment case confirmed that when services have not been fully performed, the fee should be determined in light of the actual workload; the issues of door width, repairs, and service fees involved must all be determined based on specific written evidence.','Regarding the Chufeng Apartment dispute, the court ordered a refund of service fees that were not actually incurred, determining the amount supported by documentation as 14251 yuan; the remaining claims shall be handled separately.','Rejected','Wuhan, rental, agency service fee, service fee');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_efb399cd','(2025) E0102 Civil First Instance No. 3158','Chufeng Jiayuan Early Lease Termination Contract Dispute Case','court_wh_jiangan','Contract Dispute','Housing lease contract dispute','2025-07-01','Tenant Jiang, Landlord Gu','Chufeng Jiayuan early lease termination dispute: The tenant sought early termination due to changes in living conditions, with the disputed amount being approximately RMB 8640.','Regarding the property at Chufeng Jiayuan, both parties confirmed that the tenant requested early termination due to changes in living conditions; because the landlord submitted repair quotations and proof of payment, they were unable to agree on the allocation of the deposit, repair, or service costs.','The contract attachments and correspondence emails in the Chufeng Jiayuan case file corroborate each other with the time records. On this basis, the court held that a penalty may be adjusted in accordance with the law when it is excessively high and the losses are limited, and that promises by either party not written into the contract should be subject to strict scrutiny.','The key point of the ruling is that when liquidated damages are excessively high and the losses are limited, they may be adjusted in accordance with the law; in the Chufeng Jiayuan lease, the deposit, accessibility facilities, and repair deadlines cannot rely solely on oral statements.','The matter of early termination of the lease at Chufeng Jiayuan was ultimately resolved on the basis that “appropriate liability shall be borne according to the actual losses.” After calculation, the amount awarded was RMB 3499; the portion exceeding the scope of the evidence was not supported.','Support','Wuhan, Early Lease Termination, Repairs');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_f2755471','(2024) E 0111 Civil First-Instance No. 1906','Chufeng Lixiang Identity Materials Contract Dispute Case','court_wh_hongshan','Contract Dispute','Housing lease contract dispute','2024-04-10','Tenant Ye, Landlord Chen','Chufeng Lixiang identity document dispute: Before signing the contract, the agent requested too many photos of identification documents; the disputed amount was approximately 14,216 yuan.','This case arose from a dispute over identity documents after the handover of Chufeng Lixiang. The tenant submitted materials stating that the agent had requested excessive photos of identification documents before the contract was signed, while the landlord explained its handling by stating that “the parties had previously sought coordination through the property management company but failed to reach an agreement.”','Regarding the identity-document issue in Chufeng Lane, the court treated the information-collection page and chat records as the key evidence, considered the handover condition and subsequent remedial measures, and held that rental verification should follow the principles of clearly defined purpose and minimum necessity.','In the Chufeng Lixiang case, the court made clear that rental verification should follow the principles of purpose specification and data minimization, and that key fees and living conditions should be documented through contract appendices, handover forms, or notice records.','The court ordered the following regarding Chufeng Lixiang: irrelevant materials shall be deleted and further processing shall cease, with the established loss of 3453 yuan included in the liability; the parties shall continue performing the remainder of the contract.','Rejected','Wuhan, rental, identity documents, door width');
