INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_c0e50fbe','(2024) E 01 Civil First Instance No. 25733','Contract dispute over noise-related rent reduction at Chufeng Xinyuan','court_wh_intermediate','Contract Dispute','Housing lease contract dispute','2024-12-11','Tenant Lin, Landlord Luo','Noise-related rent reduction dispute at Chufeng Xinyuan: Prolonged construction noise exceeded the reasonable tolerance level for normal living, with the disputed amount approximately 9,302 yuan.','After the tenancy at Chufeng Xinyuan was established, an issue arose in which “prolonged construction noise exceeded the reasonable tolerance level for normal living.” The intermediary was unable to provide complete records of the service process, after which the tenant and landlord each submitted evidence regarding the written attachments and actual losses.','In hearing the dispute over rent reduction for noise at Chufeng Xinyuan, the adjudicating panel first checked the construction notices and continuous audio recordings, then compared the contract appendices with the notification records. Based on the existing evidence, a landlord who knowingly fails to disclose a major impact should bear liability, and liability should be apportioned according to the actual impact.','The key holding is that a landlord should be held liable when the landlord knows of matters with a significant impact but fails to disclose them; in a Chufeng Xinyuan rental, the deposit, accessibility facilities, and repair deadlines cannot be based solely on oral statements.','The noise-related rent reduction matter at Chufeng Xinyuan was ultimately handled by “discretionarily reducing or waiving rent for the affected period.” Upon calculation, the supported amount was 2,888 yuan; portions beyond the scope of the evidence were not supported.','Rejected','Wuhan, lease, noise-related rent reduction, door width');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_8282fc2e','(2025) E0102 Civil First Instance No. 9285','Chufeng Huating Deposit Return Contract Dispute Case','court_wh_jiangan','Contract Dispute','Housing lease contract dispute','2025-10-12','Tenant Zhou, Landlord Xu','Chufeng Huating deposit-return dispute: The landlord withheld the deposit on the grounds of deep cleaning, involving a disputed amount of approximately 18436 yuan.','Regarding the property at Chufeng Huating, both parties confirmed that the landlord withheld the deposit on the grounds of deep cleaning; because the intermediary was unable to provide complete records of the service process, they were unable to agree on the allocation of the deposit, repair, or service costs.','The transfer records and handover photographs in the Chufeng Huating case file corroborate each other with the time records. On this basis, the court held that signs of normal use could not automatically be deemed damage and strictly scrutinized promises made by the parties that were not included in the contract.','The court held in the Chufeng Huating case that signs of normal use cannot automatically be deemed damage; key costs and living conditions should be formally documented through contract appendices, handover forms, or notice records.','The court ruled regarding Chufeng Huating: the portion of the deposit corresponding to unproven losses shall be returned; the established losses shall be assessed at 582 yuan for purposes of liability, and the parties shall otherwise continue performing the contract in accordance with its terms.','Partial support','Wuhan, lease, deposit return, security deposit');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_e30dc291','(2023) E 0111 Civil First-Instance No. 6069','Chufeng Neighborhood Maintenance Liability Contract Dispute Case','court_wh_hongshan','Contract Dispute','Housing lease contract dispute','2023-08-01','Tenant Gu, landlord Han','Chufeng Neighborhood maintenance liability dispute: After water seeped through the bathroom, the parties disagreed over the repair deadline, with the disputed amount approximately 31120 yuan.','This case arose from a dispute over repair responsibilities after the handover of Chufeng Jiequ. The tenant submitted materials stating that, after water seepage in the bathroom, the parties disagreed over the repair deadline, while the landlord explained its handling by stating that “the landlord submitted repair quotations and proof of payment.”','Regarding the repair-liability issue in Chufeng Block, the court treated repair orders and on-site inspection reports as the key evidence, considered the handover condition and subsequent remedial measures, and held that a landlord who fails to make timely repairs after becoming aware of the issue should bear the corresponding liability.','The Chufeng Neighborhood case confirmed that a landlord who, after becoming aware of an issue, fails to arrange repairs promptly should bear the corresponding liability; the door width, repair, and service fees at issue should all be determined based on the specific written evidence.','Regarding the Chufeng Block dispute, the court ordered the payment of repair costs and compensation for reasonable losses, determining the amount supported by documentation as 22938 yuan; the remaining claims shall be handled separately.','Mediation','Wuhan, rental, repair responsibility, service fee');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_f8a0b9d6','(2025) E0106 Civil First-Instance No. 25825','Chufeng Linli Door Width Explanation Contract Dispute Case','court_wh_wuchang','Contract Dispute','Housing lease contract dispute','2025-05-05','Tenant Chen and landlord Wu','Chufeng Linli Door Width Explanation dispute: the intermediary verbally promised a certain entrance-door width, but the measurement at handover did not match; the disputed amount was approximately 6911 yuan.','After moving into Chufeng Linli, tenant Chen claimed that the agent had orally promised a certain entrance-door width, but the measurement at handover did not match. During the handover at Chufeng Linli, the property handover form did not record the disputed item, and the parties consequently disputed the timing of the notice and the scope of the costs.','In relation to Chufeng Linli, the court examined chat records and photographs measuring the doorway width. These materials establish the course of the transaction. In light of the sequence in which both parties performed, it may be found that key living conditions, when forming the basis for entering into the contract, should be truthfully disclosed; oral statements unsupported by other evidence shall not serve as the primary basis.','The key holding is that essential residential conditions forming the basis of a contract must be truthfully disclosed; in Chufeng Neighborhood rentals, the deposit, accessibility facilities, and repair deadlines cannot be left solely to oral representations.','The Chufeng Linli Door Width Explanation matter was ultimately resolved by “refunding the service fee and adjusting liability for breach of contract.” After calculation, the supported amount is 442 yuan; any portion exceeding the scope of the evidence is not supported.','Mediation','Wuhan, rental, door width details, service fee');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_a80bcf1b','(2025) E01 Civil First-Instance No. 12249','Chufeng Xiaoyuan Elevator Shutdown Contract Dispute Case','court_wh_intermediate','Contract Dispute','Housing lease contract dispute','2025-11-02','Tenant Tang, Landlord Jiang','Chufeng Xiaoyuan elevator shutdown dispute: The prolonged shutdown of the elevator in a high-rise residential building affected normal use, with the disputed amount approximately 24,445 yuan.','After the lease relationship at Chufeng Xiaoyuan was established, the issue of “the prolonged shutdown of the elevator in a high-rise residential building affecting normal use” arose. The disputed item was not recorded on the property handover form, and the tenant and landlord subsequently submitted separate evidence regarding the written attachments and actual losses.','In hearing the dispute over the elevator shutdown at Chufeng Xiaoyuan, the adjudicating panel first checked the property management announcements and maintenance records, then compared the contract appendices with the notification records. Based on the existing evidence, rent may be reduced as appropriate when the continuous shutdown reaches a level that affects habitability, and liability should be apportioned according to the actual impact.','The court held in the Chufeng Xiaoyuan case that rent may be reduced at the court’s discretion when a prolonged outage reaches a level that affects habitation; key costs and living conditions should be formally documented through contract appendices, handover forms, or notice records.','The court ruled regarding Chufeng Xiaoyuan: part of the rent shall be reduced or waived for the period affected; the established losses shall be assessed at 1210 yuan for purposes of liability, and the parties shall otherwise continue performing the contract in accordance with its terms.','Rejected','Wuhan, rental, elevator outage, door width');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_2bcb8546','(2024) E 0102 Civil First-Instance No. 21554','Chufeng Residential Community Passageway Occupation Contract Dispute Case','court_wh_jiangan','Contract Dispute','Housing lease contract dispute','2024-07-20','Tenant Luo, Landlord Ye','Chufeng Residential Community passageway occupation dispute: a public ramp was repeatedly occupied by electric bicycles and miscellaneous items, with the disputed amount being approximately 5708 yuan.','Regarding the property at Chufeng Zhuqu, both parties confirmed that the public ramp was repeatedly occupied by electric bicycles and miscellaneous items; because the intermediary was unable to provide complete records of the service process, they were unable to agree on the allocation of the deposit, repair, or service costs.','The on-site video and property-management complaint records in the Chufeng Residential Community case file corroborate each other in terms of their time records. On this basis, the court held that the management party should have taken reasonable cleanup measures after receiving the report and should strictly scrutinize promises between the parties that were not written into the contract.','The Chufeng Residential Community case confirmed that the management party should take reasonable cleanup measures after receiving a report; the issues of door width, repairs, and service fees involved must all be determined based on specific written evidence.','Regarding the Chufeng Residential Area dispute, the court ordered cleanup within a specified time limit and improvements to inspections, determining the amount supported by documentation as 3961 yuan; the remaining claims shall be handled separately.','Support','Wuhan, rental, passageway obstruction, accessibility');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_fec36c83','(2024) E 0111 Civil First-Instance No. 18531','Chufeng Dormitory Intermediary Service Fee Contract Dispute Case','court_wh_hongshan','Contract Dispute','Housing lease contract dispute','2024-01-25','Tenant Xu, Landlord Shen','Chufeng Dormitory intermediary service fee dispute: After the contract was not concluded, the intermediary charged the full service fee, with the disputed amount approximately 30,232 yuan.','This case arose from a dispute over an intermediary service fee after the handover of Chufeng Sushe. The tenant submitted materials stating that the agent collected the full service fee after the contract was not concluded, while the landlord explained its handling by stating that “the parties had previously sought coordination through the property management company but failed to reach an agreement.”','Regarding the agency service fee issue in Chufeng Dormitory, the court treated the service agreement and property-viewing records as the key evidence, considered the handover condition and subsequent remedial measures, and held that when the service has not been fully performed, the fee should be determined in light of the actual workload.','The key point of the ruling is that when services have not been fully performed, the fees should be determined based on the actual amount of work completed; in the Chufeng Dormitory lease, the deposit, accessibility facilities, and repair deadlines cannot rely solely on oral statements.','The Chufeng Dormitory intermediary service fee matter was ultimately resolved by “refunding the service fees for services not actually rendered.” After calculation, the supported amount was 9,913 yuan; the portion exceeding the scope of the evidence was not supported.','Mediation','Wuhan, rental, agency service fee, service fee');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_1630de48','(2023) E 0106 Civil First-Instance No. 16726','Chufeng Yating early lease termination contract dispute case','court_wh_wuchang','Contract Dispute','Housing lease contract dispute','2023-08-23','Tenant Han, landlord Lin','Chufeng Yating early lease termination dispute: The tenant requested early termination because of changes in living conditions; the disputed amount was approximately 6,785 yuan.','After moving into Chufeng Yating, tenant Han claimed that the tenant requested early termination because of changed living conditions. During the handover of Chufeng Yating, the agent was unable to provide complete records of the service process, and the parties consequently disagreed over the timing of the notice and the scope of the fees.','In relation to Chufeng Yating, the court examined the contract appendices and correspondence emails. These materials establish the course of the transaction. In light of the sequence in which both parties performed, it may be found that liquidated damages may be adjusted in accordance with the law when they are excessively high and the losses are limited; oral statements unsupported by other evidence shall not serve as the primary basis.','In the Chufeng Yating case, the court made clear that when a liquidated-damages amount is excessively high and the losses are limited, it may be adjusted in accordance with the law, and that key fees and living conditions should be documented through contract appendices, handover forms, or notice records.','The court ordered the following regarding Chufeng Yating: appropriate liability shall be borne according to the actual loss, with the established loss of 2269 yuan included in the liability; the parties shall continue performing the remainder of the contract.','Rejected','Wuhan, Early Lease Termination, Service Fee');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_627428d0','(2025) E01 Civil First Instance No. 25099','Chufeng Chunxiao identity-document materials contract dispute case','court_wh_intermediate','Contract Dispute','Housing lease contract dispute','2025-01-21','Tenant Wu, Landlord Zhou','Chufeng Chunxiao identity-document materials dispute: The agent requested too many photos of identity documents before the contract was signed, involving a disputed amount of approximately 11262 yuan.','After the tenancy at Chufeng Chunxiao was established, an issue arose in which “the intermediary requested too many photos of identification documents before signing.” The landlord submitted repair quotations and proof of payment, after which the tenant and landlord each submitted evidence regarding the written attachments and actual losses.','In hearing the dispute over identity documentation at Chufeng Chunxiao, the adjudicating panel first checked the information-collection page and chat records, then compared the contract appendices with the notification records. Based on the existing evidence, rental verification should follow the principles of defined purpose and minimum necessity, and liability should be apportioned according to the actual impact.','The Chufeng Chunxiao case confirmed that rental verification should follow the principles of clearly defined purposes and minimum necessity; matters involving door width, repairs, and service fees should all be determined based on specific written evidence.','Regarding the Chufeng Chunxiao dispute, the court ordered the deletion of irrelevant materials and an end to further processing, determining the amount supported by documentation as 760 yuan; the remaining claims shall be handled separately.','Support','Wuhan, rental, identity documents, deposit');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_bd771b1f','(2023) E 0102 Civil First-Instance No. 25838','Chufeng Heyuan Written Attachment Contract Dispute Case','court_wh_jiangan','Contract Dispute','Housing lease contract dispute','2023-09-09','Tenant Jiang, Landlord Gu','Dispute over the written attachment at Chufeng Heyuan: the parties disagreed over oral promises concerning ramp repairs and cleaning fees, involving a disputed amount of approximately 10754 yuan.','Regarding the property at Chufeng Heyuan, both parties confirmed that a dispute arose over their oral promises concerning ramp repairs and cleaning fees; because the disputed item was not recorded on the property handover checklist, they were unable to agree on the allocation of the deposit, repair, or service costs.','The contract draft, recording summary, and time records in the Chufeng Heyuan case file corroborate one another. On this basis, the court held that key matters to be included in the attachment should primarily be determined by the written agreement and subjected to strict scrutiny where the parties’ promises were not included in the contract.','The key holding is that key matters that can be included in an appendix should primarily be governed by written agreements; in the Chufeng Heyuan lease, the deposit, accessibility facilities, and repair deadline cannot be based solely on oral statements.','The matters concerning the written attachment at Chufeng Heyuan were ultimately handled according to the principle that responsibility would be determined based on the valid written terms. After calculation, the supported amount was 9874 yuan; any portion beyond the scope of the evidence was not supported.','Support','Wuhan, lease, written attachment, repairs');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_9f74a5a9','(2025) Hubei 0111 Civil First-Instance No. 7924','Chufeng Qingting Noise-Induced Rent Reduction Contract Dispute Case','court_wh_hongshan','Contract Dispute','Housing lease contract dispute','2025-08-23','Tenant Ye, Landlord Chen','Noise-induced rent reduction dispute at Chufeng Qingting: prolonged construction noise exceeded the reasonable tolerance for everyday living, with the disputed amount approximately 22945 yuan.','This case arose from a dispute over a rent reduction due to noise after the handover of Chufeng Qingting. The tenant submitted materials stating that prolonged construction noise exceeded a reasonable level of tolerance for normal living, while the landlord explained its handling by stating that “the landlord submitted repair quotations and proof of payment.”','Regarding the rent-reduction issue caused by noise in Chufeng Qingting, the court treated construction notices and continuous audio recordings as the key evidence, considered the handover condition and subsequent remedial measures, and held that a landlord who knowingly fails to disclose a major adverse impact should bear liability.','The court held in the Chufeng Qingting case that a landlord should bear responsibility when, despite knowing of a material impact, the landlord fails to disclose it; key costs and living conditions should be formally documented through contract appendices, handover forms, or notice records.','The court ordered the following regarding Chufeng Qingting: rent for the affected period shall be reduced or waived as appropriate, with the established loss of 19026 yuan included in the liability; the parties shall continue performing the remainder of the contract.','Mediation','Wuhan, lease, noise-related rent reduction, service fee');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_79eb9263','(2024) E 0106 Civil First Instance No. 20165','Qingchuan Apartment Deposit Refund Contract Dispute Case','court_wh_wuchang','Contract Dispute','Housing lease contract dispute','2024-12-19','Tenant Shen, Landlord Tang','Qingchuan Apartment deposit refund dispute: The landlord withheld the deposit on the grounds of deep cleaning, with the disputed amount being approximately 14,861 yuan.','Tenant Shen moved into Qingchuan Apartment and later claimed that the landlord withheld the deposit on the grounds of deep cleaning; during the handover at Qingchuan Apartment, the landlord submitted repair quotations and proof of payment, whereupon the parties disputed the timing of the notice and the scope of the costs.','With respect to Qingchuan Apartment, the court reviewed the transfer records and handover photographs. These materials establish the course of the transaction. Considering the sequence in which the parties performed, it may be concluded that ordinary signs of use cannot automatically be deemed damage, and unsupported oral assertions shall not serve as the primary basis.','The Qingchuan Apartment case confirms that ordinary signs of use cannot automatically be deemed damage; questions involving door width, repairs, and service fees should all be determined based on the specific written evidence.','Regarding the dispute concerning the Qingchuan apartment, the court ordered the return of the portion of the deposit corresponding to unproven losses; the amount supported by documentation was determined to be 7875 yuan, and the remaining claims were addressed separately.','Partial support','Wuhan, lease, deposit return, security deposit');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_5f5496bc','(2025) E01 Civil First-Instance No. 14778','Qingchuan Jiayuan Repair Liability Contract Dispute Case','court_wh_intermediate','Contract Dispute','Housing lease contract dispute','2025-04-21','Tenant Lin, Landlord Luo','Qingchuan Jiayuan repair-liability dispute: After water seepage in the bathroom, the parties disagreed over the repair deadline; the disputed amount was approximately 5291 yuan.','After the lease was established at Qingchuan Jiayuan, an issue arose in which “the parties disagreed over the repair deadline after water seepage in the bathroom.” The intermediary was unable to provide complete records of the service process, after which the tenant and landlord each submitted evidence concerning the written attachments and actual losses.','In hearing the dispute over repair liability at Qingchuan Jiayuan, the adjudicating panel first checked the repair request orders and on-site inspection reports, then compared the contract appendices with the notification records. Based on the existing evidence, a landlord who fails to make timely repairs after becoming aware of the issue should bear the corresponding liability, and liability should be apportioned according to the actual impact.','The key point of the judgment is that a landlord bears corresponding liability if, after becoming aware of an issue, they fail to make repairs promptly; in the Qingchuan Jiayuan lease, the deposit, accessibility facilities, and repair deadline cannot be left to oral statements alone.','The Qingchuan Jiayuan repair-liability matter was ultimately handled on the basis of “bearing the repair costs and compensating reasonable losses.” Upon calculation, the supported amount was 713 yuan; the portion exceeding the scope of the evidence was not supported.','Mediation','Wuhan, rental, repair responsibility, service fee');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_614e7c2c','(2024) E0102 Civil First-Instance No. 14879','Qingchuan Lixiang Door-Width Representation Contract Dispute Case','court_wh_jiangan','Contract Dispute','Housing lease contract dispute','2024-06-16','Tenant Zhou, Landlord Xu','Qingchuan Lixiang door-width representation dispute: The intermediary orally promised a certain entrance door width, but the measurement at handover did not match, involving a disputed amount of approximately 19926 yuan.','Regarding the property at Qingchuan Li Xiang, both parties confirmed that the intermediary orally promised a certain entrance-door width, but the measurement at handover did not match; because the disputed item was not recorded on the property handover checklist, they were unable to agree on the allocation of the deposit, repair, or service costs.','The chat records and door-width measurement photos with time records in the Qingchuan Lixiang case file corroborate each other. On this basis, the court held that key living conditions forming the basis for entering into the contract should be truthfully disclosed, and strictly scrutinized promises made by both parties that were not written into the contract.','The court held in the Qingchuan Lixiang case that when key living conditions form the basis for entering into the contract, they must be truthfully disclosed; key costs and living conditions should be formally documented through contract appendices, handover forms, or notice records.','The court ruled regarding Qingchuan Lixiang: the service fees shall be refunded and liability for breach adjusted; the established losses shall be assessed at 7247 yuan for purposes of liability, and the parties shall otherwise continue performing the contract in accordance with its terms.','Partial support','Wuhan, rental, door width details, accessibility');
