INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_dc521dd9','(2024) Hubei 0111 Civil First Instance No. 5174','Qingchuan Linli Identity-Document Contract Dispute Case','court_wh_hongshan','Contract Dispute','Housing lease contract dispute','2024-10-07','Tenant Xu, Landlord Shen','Qingchuan Linli identity-document dispute: Before signing the contract, the intermediary requested excessive photos of identity documents, involving a disputed amount of approximately 16679 yuan.','This case arose from a dispute over identity documents after the handover of Qingchuan Linli. The tenant submitted materials stating that the agent had requested excessive photos of identification documents before the contract was signed, while the landlord explained its handling by stating that “the disputed items were not recorded on the property handover form.”','Regarding the identity-document issue in Qingchuan Neighborhood, the court treated the information-collection page and chat records as the key evidence, considered the handover condition and subsequent remedial measures, and held that rental verification should follow the principles of clearly defined purpose and minimum necessity.','The key holding is that lease verification should follow the principles of purpose specification and data minimization; in the Qingchuan Neighborhood lease, the deposit, accessibility facilities, and repair deadlines cannot rely solely on oral statements.','The Qingchuan Linli identity-document matter was ultimately handled by “deleting irrelevant materials and ceasing further processing.” Upon calculation, the supported amount was 6797 yuan; the portion exceeding the scope of the evidence was not supported.','Partial support','Wuhan, rental, identity documents, deposit');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_e25acc12','(2023) E 0106 Civil First-Instance No. 18889','Qingchuan Courtyard Written Attachment Contract Dispute Case','court_wh_wuchang','Contract Dispute','Housing lease contract dispute','2023-10-27','Tenant Han, landlord Lin','Qingchuan Courtyard Written Attachment Dispute: The parties disputed oral promises concerning ramp repairs and cleaning fees, with the disputed amount approximately 23,675 yuan.','After moving into Qingchuan Xiaoyuan, tenant Han claimed that the parties disputed their oral agreement regarding ramp repairs and cleaning fees. During the handover of Qingchuan Xiaoyuan, the landlord submitted a repair quotation and proof of payment, and the parties consequently disagreed over the timing of the notice and the scope of the fees.','With respect to Qingchuan Courtyard, the court reviewed the contract draft and audio-recording summary. These materials establish the course of the transaction. Considering the sequence in which the parties performed, it may be concluded that key matters capable of being included in an attachment should be based primarily on a written agreement, and unsupported oral assertions shall not serve as the primary basis.','The court held in the Qingchuan Xiaoyuan case that key matters capable of being included in an appendix should primarily be governed by written agreements; key costs and living conditions should be formally documented through contract appendices, handover forms, or notice records.','The court ruled regarding Qingchuan Xiaoyuan: liability shall be determined in accordance with the valid written provisions; the established losses shall be assessed at 15484 yuan for purposes of liability, and the parties shall otherwise continue performing the contract in accordance with its terms.','Rejected','Wuhan, lease, written attachment, accessibility');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_18be3e75','(2024) E 01 Civil First Instance No. 23519','Qingchuan Residential Community Noise-Related Rent Reduction Contract Dispute Case','court_wh_intermediate','Contract Dispute','Housing lease contract dispute','2024-12-11','Tenant Wu, Landlord Zhou','Qingchuan Residential Community noise-related rent reduction dispute: Long-term construction noise exceeded reasonable tolerance for ordinary living, with the disputed amount being approximately 25,520 yuan.','After the rental relationship was established at Qingchuan Residential Community, the issue arose that “long-term construction noise exceeded reasonable tolerance for ordinary living.” The landlord submitted repair quotations and payment receipts, after which the tenant and landlord each presented evidence concerning the written attachments and actual losses.','In hearing the dispute over a rent reduction for noise at the Qingchuan Residential Community, the judicial panel first verified the construction notices and continuous audio recordings, then compared them with the contract appendices and notice records. Based on the evidence currently available, the landlord should bear liability if, despite knowing of the significant impact, it failed to disclose it, with liability apportioned according to the actual impact.','The Qingchuan Residential Community case confirms that when a landlord knows of a material adverse impact but fails to disclose it, the landlord should be held liable; questions involving door width, repairs, and service fees should all be determined based on the specific written evidence.','Regarding the dispute concerning the Qingchuan residential area, the court ordered a discretionary reduction or waiver of rent for the affected period; the amount supported by documentation was determined to be 3191 yuan, and the remaining claims were addressed separately.','Support','Wuhan, lease, noise-related rent reduction, repairs');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_946f323e','(2024) E0102 Civil First-Instance No. 12459','Qingchuan Dormitory Deposit Refund Contract Dispute Case','court_wh_jiangan','Contract Dispute','Housing lease contract dispute','2024-10-07','Tenant Jiang, Landlord Gu','Qingchuan Dormitory Deposit Refund Dispute: The landlord withheld the deposit on the grounds of deep cleaning, with the disputed amount approximately 17,698 yuan.','Regarding the property at Qingchuan Sushe, both parties confirmed that the landlord withheld the deposit on the grounds of deep cleaning; because the parties had previously attempted to resolve the matter through property management coordination but failed to reach an agreement, they were unable to agree on the allocation of the deposit, repair, or service costs.','The transfer records and handover photos with timestamps in the Qingchuan Dormitory case file corroborate each other. On this basis, the court held that signs of normal use cannot automatically be deemed damage and strictly scrutinized the parties’ promises that were not written into the contract.','The key point of the judgment is that signs of normal use cannot automatically be deemed damage; in the Qingchuan dormitory rental, the deposit, accessibility facilities, and repair deadline cannot be based solely on oral statements.','The Qingchuan Dormitory deposit-return matter was ultimately handled on the basis of “returning the portion of the deposit for which no losses were proven.” Upon calculation, the supported amount was 5891 yuan; the portion exceeding the scope of the evidence was not supported.','Support','Wuhan, Rental, Deposit Refund, Door Width');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_f7847693','(2024) E 0111 Civil First-Instance No. 3214','Qingchuan Yating Repair Responsibility Contract Dispute Case','court_wh_hongshan','Contract Dispute','Housing lease contract dispute','2024-11-11','Tenant Ye, Landlord Chen','Qingchuan Yating repair responsibility dispute: After water seeped through the bathroom, the two parties disagreed over the repair period, involving a disputed amount of approximately 17193 yuan.','This case arose from a dispute over repair responsibilities after the handover of Qingchuan Yating. The tenant submitted materials stating that, after water seepage in the bathroom, the parties disagreed over the repair deadline, while the landlord explained its handling by stating that “the tenant promptly sent written notice after discovering the problem.”','Regarding the repair-liability issue in Qingchuan Yating, the court treated repair orders and on-site inspection reports as the key evidence, considered the handover condition and subsequent remedial measures, and held that a landlord who fails to make timely repairs after becoming aware of the issue should bear the corresponding liability.','The court held in the Qingchuan Yating case that a landlord who fails to make timely repairs after becoming aware of the issue should bear the corresponding responsibility; key costs and living conditions should be formally documented through contract appendices, handover forms, or notice records.','The court ruled regarding Qingchuan Yating: repair costs shall be borne and reasonable losses compensated; the established losses shall be assessed at 14501 yuan for purposes of liability, and the parties shall otherwise continue performing the contract in accordance with its terms.','Mediation','Wuhan, rental, repair responsibility, repairs');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_47e2b60d','(2023) E 0106 Civil First-Instance No. 16128','Contract Dispute Case Regarding Qingchuan Chunxiao''s Door-Width Disclosure','court_wh_wuchang','Contract Dispute','Housing lease contract dispute','2023-01-10','Tenant Shen, Landlord Tang','Door-Width Disclosure Dispute at Qingchuan Chunxiao: The agent verbally promised a certain entrance door width, but the measurement at handover did not match; the disputed amount is approximately 28858 yuan.','Tenant Shen moved into Qingchuan Chunxiao and later claimed that the agent had orally promised a certain entrance-door width, but the measurement at handover did not match; during the handover at Qingchuan Chunxiao, the parties attempted to resolve the matter through property-management mediation but failed to reach an agreement, whereupon they disputed the timing of the notice and the scope of the costs.','In relation to Qingchuan Chunxiao, the court examined chat records and photographs measuring the doorway width. These materials establish the course of the transaction. In light of the sequence in which both parties performed, it may be found that key living conditions, when forming the basis for entering into the contract, should be truthfully disclosed; oral statements unsupported by other evidence shall not serve as the primary basis.','The Qingchuan Chunxiao case confirmed that key living conditions forming the basis for entering into a contract should be truthfully disclosed; the issues involving door width, repairs, and service fees should all be determined based on specific written evidence.','Regarding the dispute concerning Qingchuan Chunxiao, the court ordered a refund of the service fee and adjusted the liability for breach of contract; the amount supported by documentation was determined to be 26639 yuan, and the remaining claims were addressed separately.','Support','Wuhan, rental, door width details, service fee');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_ae8bb8fb','(2023) E 01 Civil First-Instance No. 23094','Qingchuan Heyuan Elevator Shutdown Contract Dispute Case','court_wh_intermediate','Contract Dispute','Housing lease contract dispute','2023-02-02','Tenant Lin, Landlord Luo','Qingchuan Heyuan elevator shutdown dispute: The prolonged shutdown of the elevator in a high-rise residential building affected normal use, with the disputed amount totaling approximately 35981 yuan.','After the lease relationship at Qingchuan Heyuan was established, the problem of the “prolonged shutdown of the elevator in a high-rise residential building affecting normal use” arose. The parties attempted to resolve the matter through property-management coordination but failed to reach an agreement. The tenant and landlord subsequently presented separate evidence concerning the written annexes and actual losses.','In hearing the dispute over the elevator shutdown at Qingchuan Heyuan, the adjudicating panel first checked the property management announcements and maintenance records, then compared the contract appendices with the notification records. Based on the existing evidence, rent may be reduced as appropriate when the continuous shutdown reaches a level that affects habitability, and liability should be apportioned according to the actual impact.','The key point of the ruling is that rent may be reduced at the court’s discretion when a prolonged service suspension reaches a level that affects habitability; in the Qingchuan Heye lease, the deposit, accessibility facilities, and repair deadlines cannot rely solely on oral statements.','The Qingchuan Heyuan elevator shutdown matter was ultimately resolved by reducing part of the rent for the period affected. After calculation, the supported amount was 11174 yuan; the portion exceeding the scope of the evidence was not supported.','Support','Wuhan, rental, elevator outage, door width');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_81776405','(2024) E 0102 Civil First-Instance No. 27497','Qingchuan Qingting Passageway Occupancy Contract Dispute Case','court_wh_jiangan','Contract Dispute','Housing lease contract dispute','2024-03-19','Tenant Zhou, Landlord Xu','Qingchuan Qingting Passageway Occupancy Dispute: The public ramp was repeatedly occupied by electric bicycles and miscellaneous items, with the disputed amount approximately 14,421 yuan.','Regarding the property at Qingchuan Qingting, both parties confirmed that the public ramp was repeatedly occupied by electric bicycles and miscellaneous items; because the landlord submitted repair quotations and proof of payment, they were unable to agree on the allocation of the deposit, repair, or service costs.','The on-site video footage, property complaint records, and time records in the Qingchuan Qingting case file corroborate one another. On this basis, the court held that after receiving the report, the management party should have taken reasonable cleaning measures, and strictly scrutinized the parties’ promises that were not included in the contract.','The court held in the Qingchuan Qingting case that after receiving a report, the management party should take reasonable cleanup measures; key costs and living conditions should be formally documented through contract appendices, handover forms, or notice records.','The court ruled regarding Qingchuan Qingting: clean-up shall be completed within a specified time and inspections improved; the established losses shall be assessed at 7892 yuan for purposes of liability, and the parties shall otherwise continue performing the contract in accordance with its terms.','Partial support','Wuhan, rental, passageway obstruction, door width');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_6f0590f5','(2024) E 0111 Civil First-Instance No. 15805','Dispute over the Brokerage Service Fee Contract for Hanshui Apartment','court_wh_hongshan','Contract Dispute','Housing lease contract dispute','2024-03-12','Tenant Gu, landlord Han','Dispute over the Hanshui Apartment brokerage service fee: After the agreement was not signed, the broker charged the entire service fee, with the disputed amount approximately 33,885 yuan.','This case arose from an intermediary service fee issue after the handover of Hanshui Gongyu. The tenant submitted materials alleging that the intermediary collected the entire service fee after the contract signing fell through, while the landlord explained its handling by stating that “the landlord submitted repair quotations and proof of payment.”','For the intermediary service fee issue at Hanshui Apartment, the court treated the service agreement and viewing records as the primary evidence, considered the condition at handover and subsequent remediation, and held that where the services were not fully performed, the fee should be determined based on the actual amount of work completed.','The Hanshui Apartment case confirmed that when services have not been fully performed, the fee should be determined based on the actual workload; the issues of door width, repairs, and service fees involved should all be assessed against specific written evidence.','Regarding the Hanshui apartment dispute, the court ordered a refund of service fees for services not actually provided, determining the amount supported by documentation to be 31204 yuan; the remaining claims were addressed separately.','Support','Wuhan, rental, agency service fee, accessibility');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_b898feb0','(2023) E 0106 Civil First Instance No. 26734','Hanshui Jiayuan early lease termination contract dispute case','court_wh_wuchang','Contract Dispute','Housing lease contract dispute','2023-12-09','Tenant Chen and landlord Wu','Hanshui Jiayuan early lease termination dispute: The tenant requested early termination due to changes in living conditions, with the disputed amount approximately 34,771 yuan.','After moving into Hanshui Jiayuan, tenant Chen claimed that the tenant requested early termination because of changes in the living conditions. During the handover at Hanshui Jiayuan, the tenant promptly sent written notice after discovering the issue, and the parties consequently disputed the timing of the notice and the scope of the costs.','The court, with respect to Hanshui Jiayuan, examined the contract attachments and correspondence emails. These materials can establish the course of the transaction; in conjunction with the sequence in which the parties performed, it can be determined that liquidated damages may be adjusted in accordance with the law when they are excessively high and the losses are limited, and oral statements unsupported by other evidence shall not serve as the primary basis.','The key point of the ruling is that when liquidated damages are excessively high and the losses are limited, they may be adjusted in accordance with the law; in the Hanshui Jiayuan lease, the deposit, accessibility facilities, and repair deadlines cannot rely solely on oral statements.','The early lease termination matter at Hanshui Jiayuan was ultimately handled under the principle of “assuming appropriate liability based on the actual loss.” After calculation, the supported amount was 24563 yuan; the portion exceeding the scope of the evidence was not supported.','Mediation','Wuhan, Early Lease Termination, Door Width');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_e0c5bbff','(2025) E 01 Civil First Instance No. 6515','Hanshui Lixiang Identity Document Materials Contract Dispute Case','court_wh_intermediate','Contract Dispute','Housing lease contract dispute','2025-03-20','Tenant Tang, Landlord Jiang','Hanshui Lixiang Identity Document Materials Dispute: The intermediary requested too many photos of identity documents before signing; the disputed amount is approximately 13030 yuan.','After the tenancy relationship at Hanshui Lixiang was established, an issue arose that “the intermediary requested too many photos of identity documents before signing.” The disputed items were not recorded on the property handover form, and the tenant and landlord subsequently each submitted evidence regarding the written attachments and actual losses.','When hearing the dispute over identity materials at Hanshui Lixiang, the judicial panel first verified the information-collection page and chat records, then compared them with the contract appendices and notice records. Based on the evidence currently available, rental verification should follow the principles of a clearly defined purpose and minimum necessity, and liability should be apportioned according to the actual impact.','In the Hanshui Lixiang case, the court clarified that rental verification should follow the principles of purpose specification and data minimization, and that key fees and living conditions should be documented in contract appendices, handover forms, or notice records.','The court ruled as follows regarding Hanshui Lixiang: delete the irrelevant materials and cease further processing; include the established loss of 3746 yuan in the liability; the parties shall continue performing the remainder of the contract in accordance with its terms.','Support','Wuhan, rental, identity documents, door width');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_97bfede7','(2023) E 0102 Civil First-Instance No. 15911','Hanshui Community Written Attachment Contract Dispute Case','court_wh_jiangan','Contract Dispute','Housing lease contract dispute','2023-03-20','Tenant Luo, Landlord Ye','Hanshui Community Written Attachment Dispute: The parties disputed oral promises concerning ramp repairs and cleaning fees, with the amount in dispute being approximately 35944 yuan.','Regarding the property at Hanshui Shequ, both parties acknowledged that a dispute had arisen over their oral commitments concerning ramp repairs and cleaning fees; because they had attempted to resolve the matter through the property management service but failed to reach an agreement, they were unable to agree on the allocation of the deposit, repair, or service fees.','The contract drafts, recording summaries, and time records in the Hanshui Community case corroborate one another. On this basis, the court held that key matters capable of being included in an attachment should primarily be determined by the written agreement, and that promises not included in the contract should be examined strictly.','The Hanshui Community case confirmed that key matters capable of being included in an attachment should primarily be determined by the written agreement; the door width, repair fees, and service fees at issue should all be assessed based on the specific written evidence.','Regarding the Hanshui community dispute, the court ordered liability to be determined in accordance with the valid written terms, determining the amount supported by documentation to be 26322 yuan; the remaining claims were addressed separately.','Mediation','Wuhan, lease, written attachment, door width');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_84290841','(2025) Hubei 0111 Civil First-Instance No. 4642','Hanshui Xinyuan Noise-Related Rent Reduction Contract Dispute Case','court_wh_hongshan','Contract Dispute','Housing lease contract dispute','2025-10-07','Tenant Xu, Landlord Shen','Hanshui Xinyuan Noise-Related Rent Reduction Dispute: Prolonged construction noise exceeded the reasonable tolerance for normal living, with the amount in dispute approximately 21376 yuan.','This case arose from a rent reduction issue due to noise after the handover of Hanshui Xinyuan. The tenant submitted materials alleging that prolonged construction noise exceeded the reasonable tolerance threshold for ordinary living, while the landlord explained its handling by stating that “the tenant promptly sent written notice after discovering the problem.”','For the noise-related rent reduction issue at Hanshui Xinyuan, the court treated the construction notices and continuous audio recordings as the primary evidence, considered the condition at handover and subsequent remediation, and held that the landlord should be liable if the landlord knew of the significant impact but failed to disclose it.','The key holding is that a landlord should be held liable when the landlord knows of matters with a significant impact but fails to disclose them; in a Hanshui Xinyuan rental, the deposit, accessibility facilities, and repair deadlines cannot be based solely on oral statements.','The Hanshui Xinyuan noise-related rent reduction matter was ultimately resolved by granting a discretionary reduction of rent for the affected period. Upon calculation, the supported amount was 15313 yuan; the portion exceeding the scope of the evidence was not supported.','Partial support','Wuhan, lease, noise-related rent reduction, accessibility');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_c67f320c','(2023) E 0106 Civil First-Instance No. 11380','Hanshui Huating Deposit Refund Contract Dispute Case','court_wh_wuchang','Contract Dispute','Housing lease contract dispute','2023-12-28','Tenant Han, landlord Lin','Hanshui Huating deposit refund dispute: The lessor withheld the deposit on the grounds of deep cleaning, involving a disputed amount of approximately 29947 yuan.','After moving into Hanshui Huating, tenant Han claimed that the landlord withheld the deposit on the grounds that deep cleaning was required. During the handover of Hanshui Huating, the agent was unable to provide complete records of the service process, and the parties consequently disagreed over the timing of the notice and the scope of the fees.','The court, with respect to Hanshui Huating, examined the transfer records and handover photographs. These materials can establish the course of the transaction; in conjunction with the sequence in which the parties performed, it can be determined that signs of normal use cannot automatically be deemed damage, and oral statements unsupported by other evidence shall not serve as the primary basis.','In the Hanshui Huating case, the court made clear that traces resulting from normal use cannot automatically be deemed damage, and that key fees and living conditions should be documented through contract appendices, handover forms, or notice records.','The court ordered the following regarding Hanshui Huating: the portion of the deposit corresponding to unproven losses shall be returned, with the established loss of 4571 yuan included in the liability; the parties shall continue performing the remainder of the contract.','Rejected','Wuhan, Rental, Deposit Refund, Door Width');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_70f6f80b','(2024) E 01 Civil First Instance No. 21866','Hanshui Neighborhood Repair Responsibility Contract Dispute Case','court_wh_intermediate','Contract Dispute','Housing lease contract dispute','2024-11-04','Tenant Wu, Landlord Zhou','Hanshui Neighborhood Repair Responsibility Dispute: After water seepage in the bathroom, the parties disagreed over the repair deadline, with the amount in dispute being approximately 12549 yuan.','After the lease relationship for Hanshui Neighborhood was established, an issue arose involving “the parties disagreeing over the repair deadline after water seepage in the bathroom.” The intermediary was unable to provide complete records of the service process, and the tenant and landlord subsequently each presented evidence regarding the written attachments and actual losses.','When hearing the dispute over repair liability at Hanshui Block, the judicial panel first verified the repair request tickets and on-site inspection report, then compared them with the contract appendices and notice records. Based on the evidence currently available, when the landlord, after becoming aware of the issue, failed to carry out repairs promptly, the landlord should bear corresponding liability, which should be apportioned according to the actual impact.','The Hanshui Neighborhood case confirmed that a landlord who, after becoming aware of an issue, fails to repair it promptly should bear the corresponding responsibility; the door width, repair fees, and service fees at issue should all be assessed based on the specific written evidence.','Regarding the Hanshui neighborhood dispute, the court ordered the payment of repair costs and compensation for reasonable losses, determining the amount supported by documentation to be 8816 yuan; the remaining claims were addressed separately.','Mediation','Wuhan, rental, repair responsibility, repairs');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_03e2cce1','(2023) E 0102 Civil First-Instance No. 2656','Hanshui Linli Door-Width Disclosure Contract Dispute Case','court_wh_jiangan','Contract Dispute','Housing lease contract dispute','2023-02-19','Tenant Jiang, Landlord Gu','Hanshui Neighborhood Gate Width Disclosure Dispute: The intermediary verbally promised a certain entrance gate width, but the measurement at handover did not match; the disputed amount is approximately 13219 yuan.','Regarding the property at Hanshui Linli, both parties acknowledged that the intermediary had orally promised a certain entrance-door width, but the measurement at handover did not match; because the landlord submitted repair quotations and proof of payment, they were unable to agree on the allocation of the deposit, repair, or service fees.','The chat records and door-width measurement photographs with timestamps in the Hanshui Linli case file corroborate each other. On that basis, the court held that key living conditions forming the basis for entering into the contract should be truthfully disclosed, and that promises not written into the contract should be examined strictly.','The key holding is that essential residential conditions forming the basis of a contract must be truthfully disclosed; in Hanshui Neighborhood rentals, the deposit, accessibility facilities, and repair deadlines cannot be left solely to oral representations.','The matter concerning the door-width disclosure at Hanshui Linli was ultimately handled under the arrangement of “refunding the service fee and adjusting liability for breach of contract.” After calculation, the supported amount was 7197 yuan; the portion exceeding the scope of the evidence was not supported.','Rejected','Wuhan, rental, door width details, repairs');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_52b286eb','(2024) E 0111 Civil First-Instance No. 23169','Hanshui Courtyard elevator shutdown contract dispute case','court_wh_hongshan','Contract Dispute','Housing lease contract dispute','2024-10-22','Tenant Ye, Landlord Chen','Hanshui Courtyard elevator shutdown dispute: The prolonged shutdown of the elevator in a high-rise residential building affected normal use, with the disputed amount approximately 3,196 yuan.','This case arose from the elevator being out of service after the handover of Hanshui Xiaoyuan. The tenant submitted materials alleging that the prolonged outage of the elevator in the high-rise residence affected normal use, while the landlord explained its handling by stating that “the parties had previously coordinated through the property management company but failed to reach an agreement.”','For the elevator outage issue at Hanshui Xiaoyuan, the court treated property-management notices and maintenance records as the primary evidence, considered the condition at handover and subsequent remediation, and held that rent may be reduced at its discretion when the prolonged outage affected the ability to reside in the premises.','In the Hanshui Xiaoyuan case, the court made clear that rent may be reduced as appropriate when a continued shutdown reaches a level that affects habitation, and that key fees and living conditions should be documented through contract appendices, handover forms, or notice records.','The court ordered the following regarding Hanshui Xiaoyuan: part of the rent shall be reduced or waived based on the period of impact, with the established loss of 2210 yuan included in the liability; the parties shall continue performing the remainder of the contract.','Rejected','Wuhan, rental, elevator outage, door width');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_947255d0','(2025) E0106 Civil First-Instance No. 25904','Hanshui Residential Community Passageway Occupation Contract Dispute Case','court_wh_wuchang','Contract Dispute','Housing lease contract dispute','2025-05-06','Tenant Shen, Landlord Tang','Hanshui Residential Community passageway occupation dispute: the public ramp was repeatedly occupied by electric scooters and miscellaneous items, involving a disputed amount of approximately 24776 yuan.','Tenant Shen moved into Hanshui Residential Community and later claimed that the public ramp was repeatedly occupied by electric bicycles and miscellaneous items; during the handover at Hanshui Residential Community, the parties attempted to resolve the matter through property-management mediation but failed to reach an agreement, whereupon they disputed the timing of the notice and the scope of the costs.','In relation to Hanshui Zhuqu, the court examined on-site video footage and property management complaint records. These materials establish the course of the transaction. In light of the sequence in which both parties performed, it may be found that the management party should have taken reasonable cleaning measures after receiving the report; oral statements unsupported by other evidence shall not serve as the primary basis.','The Hanshui Residential Community case confirms that, after receiving a report, the management party should take reasonable cleanup measures; issues involving door width, repairs, and service fees must all be determined based on specific written evidence.','Regarding the Hanshui residential-community dispute, the court ordered the area to be cleaned within a specified period and inspections to be improved, determining the amount supported by documentation to be 23323 yuan; the remaining claims were addressed separately.','Rejected','Wuhan, rental, passageway obstruction, accessibility');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_8e89d9e9','(2025) E01 Civil First-Instance No. 16370','Hanshui Dormitory intermediary service fee contract dispute case','court_wh_intermediate','Contract Dispute','Housing lease contract dispute','2025-11-16','Tenant Lin, Landlord Luo','Hanshui Dormitory intermediary service fee dispute: After the contract was not concluded, the intermediary charged the full service fee, with the disputed amount approximately 22,620 yuan.','After the tenancy relationship at Hanshui Dormitory was established, a dispute arose over the intermediary charging the full service fee after the contract was not concluded. The parties attempted to resolve the matter through property management coordination but failed to reach an agreement. The tenant and landlord subsequently each submitted evidence regarding the written attachments and actual losses.','When hearing the dispute over the intermediary service fee for Hanshui Dormitory, the judicial panel first verified the service agreement and viewing records, then compared them with the contract appendices and notice records. Based on the evidence currently available, when the service has not been fully performed, the fee should be determined in light of the actual workload, and liability should be apportioned according to the actual impact.','The key point of the ruling is that when services have not been fully performed, the fees should be determined based on the actual amount of work completed; in the Hanshui Dormitory lease, the deposit, accessibility facilities, and repair deadlines cannot rely solely on oral statements.','The Hanshui Dormitory intermediary service fee matter was ultimately resolved by “refunding the service fees that had not actually been incurred.” Upon calculation, the supported amount was 20,560 yuan; the portion exceeding the scope of the evidence was not supported.','Partial support','Wuhan, rental, agency service fee, accessibility');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_8d301638','(2024) E 0102 Civil First-Instance No. 21870','Hanshui Yating Early Lease Termination Contract Dispute Case','court_wh_jiangan','Contract Dispute','Housing lease contract dispute','2024-08-17','Tenant Zhou, Landlord Xu','Hanshui Yating Early Lease Termination Dispute: The tenant requested early termination due to changes in living conditions; the disputed amount is approximately 34081 yuan.','Regarding the property at Hanshui Yating, both parties acknowledged that the tenant requested early termination because of changes in living conditions; because the landlord submitted repair quotations and proof of payment, they were unable to agree on the allocation of the deposit, repair, or service fees.','The contract attachments, correspondence emails, and timeline records in the Hanshui Yating case file corroborate one another. Based on these materials, the court held that liquidated damages may be adjusted in accordance with the law when they are excessively high and the losses are limited, and that promises made by either party but not included in the contract should be subject to strict scrutiny.','In the Hanshui Yating case, the court clarified that when a penalty is excessively high and the losses are limited, it may be adjusted in accordance with the law, and that key fees and living conditions should be documented in contract appendices, handover forms, or notice records.','The court ruled as follows regarding Hanshui Yating: bear appropriate liability based on the actual loss; include the established loss of 7756 yuan in the liability; the parties shall continue performing the remainder of the contract in accordance with its terms.','Rejected','Wuhan, Early Lease Termination, Accessibility');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_27fea30d','(2025) Hubei 0111 Civil First-Instance No. 29318','Hanshui Chunxiao Identity Documents Contract Dispute Case','court_wh_hongshan','Contract Dispute','Housing lease contract dispute','2025-03-25','Tenant Gu, landlord Han','Hanshui Chunxiao identity documents dispute: Before signing the contract, the intermediary requested photos of too many identity documents, and the disputed amount was approximately 29591 yuan.','This case arose from an identity-document issue after the handover of Hanshui Chunxiao. The tenant submitted materials alleging that the intermediary requested too many photographs of identity documents before the contract was signed, while the landlord explained its handling by stating that “the disputed item was not recorded on the property handover form.”','For the identity-document issue at Hanshui Chunxiao, the court treated the information-collection page and chat records as the primary evidence, considered the condition at handover and subsequent remediation, and held that lease verification should follow the principles of specified purposes and data minimization.','The Hanshui Chunxiao case confirms that rental verification should follow the principles of a clearly defined purpose and minimum necessity; the door width, repair costs, and service fees involved should all be determined based on specific written evidence.','Regarding the Hanshui Chunxiao dispute, the court ordered the deletion of irrelevant materials and an end to further processing, determining the amount supported by documentation to be 1949 yuan; the remaining claims were addressed separately.','Partial support','Wuhan, rental, identity documents, accessibility');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_9f391bcc','(2023) E 0106 Civil First-Instance No. 13117','Hanshui Heyuan Written Attachment Contract Dispute Case','court_wh_wuchang','Contract Dispute','Housing lease contract dispute','2023-07-09','Tenant Chen and landlord Wu','Hanshui Heyuan written-attachment dispute: The parties disputed oral promises regarding ramp repairs and cleaning fees, involving approximately 16578 yuan.','After moving into Hanshui Heyuan, tenant Chen claimed that a dispute arose over the parties'' oral promises concerning ramp repairs and cleaning fees. During the handover at Hanshui Heyuan, the landlord submitted repair quotations and proof of payment, and the parties consequently disputed the timing of the notice and the scope of the costs.','The court, with respect to Hanshui Heyuan, examined the contract draft and recording summary. These materials can establish the course of the transaction; in conjunction with the sequence in which the parties performed, it can be determined that key matters capable of being included in an attachment should be based primarily on written agreement, and oral statements unsupported by other evidence shall not serve as the primary basis.','The key holding is that key matters that can be included in an appendix should primarily be governed by written agreements; in the Hanshui Heyuan lease, the deposit, accessibility facilities, and repair deadline cannot be based solely on oral statements.','The matters concerning the written attachments for Hanshui Heyuan were ultimately handled according to the principle of "determining liability based on the valid written terms." After calculation, the supported amount was 13785 yuan; the portion exceeding the scope of the evidence was not supported.','Rejected','Wuhan, lease, written attachment, service fee');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_e9a7d93d','(2024) Hubei 01 Civil First Instance No. 15243','Hanshui Qingting Noise Rent Reduction Contract Dispute Case','court_wh_intermediate','Contract Dispute','Housing lease contract dispute','2024-06-10','Tenant Tang, Landlord Jiang','Hanshui Qingting noise rent reduction dispute: prolonged construction noise exceeded the reasonable tolerance for normal living, with the disputed amount being approximately 31955 yuan.','After the lease relationship for Hanshui Qingting was established, an issue arose involving “long-term construction noise exceeding a reasonable level of tolerance for daily life.” The property handover form did not record the disputed items, and the tenant and landlord subsequently each presented evidence regarding the written attachments and actual losses.','When hearing the dispute over a rent reduction for noise at Hanshui Qingting, the judicial panel first verified the construction notices and continuous audio recordings, then compared them with the contract appendices and notice records. Based on the evidence currently available, when the landlord knew of a significant impact but failed to disclose it, the landlord should bear liability, which should be apportioned according to the actual impact.','In the Hanshui Qingting case, the court made clear that a lessor bears liability when, despite knowing of a major impact, the lessor fails to disclose it, and that key fees and living conditions should be documented through contract appendices, handover forms, or notice records.','The court ruled as follows regarding Hanshui Qingting: reduce or waive the rent for the affected period as appropriate; include the established loss of 15321 yuan in the liability; the parties shall continue performing the remainder of the contract in accordance with its terms.','Support','Wuhan, lease, noise-related rent reduction, door width');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_4fc13b54','(2023) E 0102 Civil First-Instance No. 13261','Shahu Apartment Deposit Return Contract Dispute Case','court_wh_jiangan','Contract Dispute','Housing lease contract dispute','2023-04-01','Tenant Luo, Landlord Ye','Shahu Apartment deposit return dispute: The landlord withheld the deposit on the grounds of deep cleaning, with the disputed amount being approximately RMB 32455.','Regarding the property at Shahu Gongyu, both parties acknowledged that the landlord withheld the deposit on the grounds of deep cleaning; because the intermediary failed to provide complete records of the service process, they were unable to agree on the allocation of the deposit, repair, or service fees.','In the Shahu Apartment case file, the transfer records, handover photographs, and time records corroborate one another. On this basis, the court held that traces of normal use cannot automatically be deemed damage and strictly scrutinized the parties’ promises that were not written into the contract.','Shahu Apartment case confirmation: Traces of normal use cannot automatically be deemed damage; the issues concerning door width, repairs, and service fees should all be determined based on specific written evidence.','Regarding the Shahu apartment dispute, the court ordered the return of the portion of the deposit for which no loss was proven, determining the amount supported by documentation to be 10561 yuan; the remaining claims were addressed separately.','Support','Wuhan, Rental, Deposit Refund, Accessibility');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_331b9f60','(2023) E 0111 Civil First-Instance No. 2868','Shahu Jiayuan Repair Liability Contract Dispute Case','court_wh_hongshan','Contract Dispute','Housing lease contract dispute','2023-07-12','Tenant Xu, Landlord Shen','Shahu Jiayuan repair liability dispute: After water seepage in the bathroom, the parties disagreed over the repair period; the amount in dispute was approximately 18486 yuan.','This case arose from a repair responsibility issue after the handover of Shahu Jiayuan. The tenant submitted materials alleging that, after water seepage in the bathroom, the parties disagreed over the repair deadline, while the landlord explained its handling by stating that “the landlord submitted repair quotations and proof of payment.”','Regarding the repair liability issue at Shahu Jiayuan, the court relied primarily on repair requests and on-site inspection reports, while considering the condition at handover and subsequent remedial measures; a landlord who, after becoming aware of the issue, fails to make timely repairs should bear the corresponding liability.','The key point of the judgment is that a landlord bears corresponding liability if, after becoming aware of an issue, they fail to make repairs promptly; in the Shahu Jiayuan lease, the deposit, accessibility facilities, and repair deadline cannot be left to oral statements alone.','The Shahu Jiayuan repair liability matter was ultimately resolved on the basis that the responsible party would “pay the repair costs and compensate for reasonable losses.” Upon calculation, the supported amount was 2164 yuan; any portion exceeding the scope of the evidence was not supported.','Partial support','Wuhan, rental, repair responsibility, repairs');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_0a176077','(2025) E0106 Civil First-Instance No. 28352','Shahu Lixiang Doorway-Width Description Contract Dispute Case','court_wh_wuchang','Contract Dispute','Housing lease contract dispute','2025-01-26','Tenant Han, landlord Lin','Shahu Lixiang doorway-width description dispute: The intermediary orally promised a certain entrance doorway width, but the measurement at delivery did not match; the disputed amount was approximately 21117 yuan.','After moving into Sha Hu Li Xiang, tenant Han claimed that the agent had orally promised a certain entrance-door width, but the measurement at handover did not match. During the handover at Sha Hu Li Xiang, the disputed issue was not recorded on the property handover form, and the parties consequently disagreed over the notification timing and the scope of the costs.','The court, with respect to Shahu Alley, examined the chat records and photographs measuring the doorway width. These materials can establish the course of the transaction; in conjunction with the sequence in which the parties performed, it can be determined that key residential conditions should be truthfully disclosed when they constitute the basis for entering into the contract, and oral statements unsupported by other evidence shall not serve as the primary basis.','In the Shahu Lixiang case, the court clarified that when key living conditions form the basis for entering into a contract, they should be truthfully disclosed, and that key fees and living conditions should be documented in contract appendices, handover forms, or notice records.','The court ruled as follows regarding Shahu Lixiang: refund the service fees and adjust the liability for breach of contract; include the established loss of 3106 yuan in the liability; the parties shall continue performing the remainder of the contract in accordance with its terms.','Partial support','Wuhan, rental, door width explanation, deposit');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_739ec239','(2025) E01 Civil First-Instance No. 17245','Shahu Community Elevator Shutdown Contract Dispute Case','court_wh_intermediate','Contract Dispute','Housing lease contract dispute','2025-11-25','Tenant Wu, Landlord Zhou','Shahu Community Elevator Shutdown Dispute: The prolonged shutdown of the elevator in a high-rise residential building affected normal use, with the disputed amount approximately RMB 24507.','After the lease relationship in Shahu Community was established, the issue arose that “the prolonged shutdown of the elevator in a high-rise residential building affected normal use.” The landlord submitted repair quotations and proof of payment, after which the tenant and landlord each submitted evidence regarding the written appendices and actual losses.','When hearing the dispute over the elevator shutdown at Shahu Community, the judicial panel first verified the property-management notices and maintenance records, then compared them with the contract appendices and notice records. Based on the evidence currently available, when a continuous shutdown reaches a level that affects habitability, a rent reduction may be granted at the court’s discretion, and liability should be apportioned according to the actual impact.','Confirmation in the Shahu Community case: When a continuous shutdown reaches a level that affects residential living, a rent reduction may be granted at the court’s discretion; the door width, repair costs, and service fees at issue should all be determined based on specific written evidence.','Regarding the Shahu community dispute, the court ordered a partial rent reduction for the period affected, determining the amount supported by documentation to be 12817 yuan; the remaining claims were addressed separately.','Partial support','Wuhan, rental, elevator outage, accessibility');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_2acff2ef','(2024) E0102 Civil First-Instance No. 10022','Shahu Xinyuan Passage Occupancy Contract Dispute Case','court_wh_jiangan','Contract Dispute','Housing lease contract dispute','2024-01-25','Tenant Jiang, Landlord Gu','Shahu Xinyuan passage-occupancy dispute: the public ramp was repeatedly occupied by electric bicycles and miscellaneous items, with a disputed amount of approximately 7137 yuan.','Regarding the property at Shahu Xinyuan, both parties acknowledged that the common ramp had repeatedly been obstructed by electric bicycles and miscellaneous items; because the landlord submitted repair quotations and proof of payment, they were unable to agree on the allocation of the deposit, repair, or service fees.','The on-site video and property-management complaint records in the Shahu Xinyuan case file corroborate each other with the time records. On this basis, the court held that the management party should take reasonable cleanup measures after receiving a report, and that promises made by either party but not included in the contract should be scrutinized strictly.','The key holding is that after receiving a report, the management party should take reasonable cleaning measures; in the Shahu Xinyuan lease, the deposit, accessibility facilities, and repair deadline cannot be based solely on oral statements.','The Shahu Xinyuan passage-occupancy matter was ultimately handled by requiring clearance within a specified period and improved inspections; after calculation, the supported amount was 3030 yuan, and any portion beyond the scope of the evidence was not supported.','Partial support','Wuhan, rental, passageway obstruction, deposit');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_de59a339','(2023) E 0111 Civil First-Instance No. 22496','Shahu Huating Intermediary Service Fee Contract Dispute Case','court_wh_hongshan','Contract Dispute','Housing lease contract dispute','2023-12-24','Tenant Ye, Landlord Chen','Shahu Huating intermediary service fee dispute: After the contract was not concluded, the intermediary charged the full service fee, with the disputed amount being approximately RMB 5896.','This case arose from an intermediary service fee issue after the handover of Shahu Huating. The tenant submitted materials alleging that the intermediary collected the entire service fee after the contract signing fell through, while the landlord explained its handling by stating that “the intermediary was unable to provide a complete record of the services performed.”','For the intermediary service fee issue at Shahu Huating, the court treated the service agreement and viewing records as the primary evidence, considered the condition at handover and subsequent remediation, and held that where the services were not fully performed, the fee should be determined based on the actual amount of work completed.','In the Shahu Huating case, the court clarified that when services have not been fully performed, the fee should be determined based on the actual workload, and that key fees and living conditions should be documented in contract appendices, handover forms, or notice records.','The court ruled as follows regarding Shahu Huating: refund service fees that were not actually incurred; include the established loss of 745 yuan in the liability; the parties shall continue performing the remainder of the contract in accordance with its terms.','Rejected','Wuhan, rental, agency service fee, service fee');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_ab455737','(2023) E 0106 Civil First Instance No. 28498','Shahu Neighborhood Early Lease Termination Contract Dispute Case','court_wh_wuchang','Contract Dispute','Housing lease contract dispute','2023-09-24','Tenant Shen, Landlord Tang','Shahu Neighborhood Early Lease Termination Dispute: The tenant sought early termination because of changes in living conditions, with the disputed amount approximately RMB 34133.','Tenant Shen moved into Shahu District and later claimed that the tenant requested early termination because of changes in the living conditions; during the handover at Shahu District, the parties attempted to resolve the matter through property-management mediation but failed to reach an agreement, whereupon they disputed the timing of the notice and the scope of the costs.','The court, with respect to Shahu Neighborhood, examined the contract attachments and correspondence emails. These materials can establish the course of the transaction; in conjunction with the sequence in which the parties performed, it can be determined that liquidated damages may be adjusted in accordance with the law when they are excessively high and the losses are limited, and oral statements unsupported by other evidence shall not serve as the primary basis.','Confirmation in the Shahu Neighborhood case: When a contractual penalty is excessively high and the losses are limited, it may be adjusted in accordance with the law; the issues concerning the doorway width, repairs, and service fees must all be determined based on the specific written evidence.','Regarding the dispute concerning the Shahu neighborhood, the court ordered appropriate liability based on the actual losses; the amount supported by documentation was determined to be 7682 yuan, with the remaining claims addressed separately.','Mediation','Wuhan, Early Lease Termination, Deposit');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_1e3a6ff5','(2025) E01 Civil First Instance No. 23697','Shahu Linli Identity-Materials Contract Dispute Case','court_wh_intermediate','Contract Dispute','Housing lease contract dispute','2025-10-27','Tenant Lin, Landlord Luo','Shahu Linli identity-materials dispute: The intermediary requested too many photos of identity documents before signing the contract, and the disputed amount was approximately 21312 yuan.','After the tenancy relationship in Shahu Linli was established, an issue arose in which “the intermediary requested too many photos of identity documents before signing the contract.” The intermediary was unable to provide complete records of the service process, and the tenant and landlord subsequently each presented evidence regarding the written attachments and actual losses.','When hearing the dispute over identity materials at Shahu Linli, the judicial panel first verified the information-collection page and chat records, then compared them with the contract appendices and notice records. Based on the evidence currently available, rental verification should follow the principles of a clearly defined purpose and minimum necessity, and liability should be apportioned according to the actual impact.','The key holding is that lease verification should follow the principles of purpose specification and data minimization; in the Shahu Neighborhood lease, the deposit, accessibility facilities, and repair deadlines cannot rely solely on oral statements.','The Shahu Linli identity-materials matter was ultimately handled by “deleting irrelevant materials and ceasing further processing.” After calculation, the supported amount was 15858 yuan; the portion exceeding the scope of the evidence was not supported.','Mediation','Wuhan, rental, identity documents, accessibility');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_2c919b24','(2023) E 0102 Civil First-Instance No. 15231','Shahu Xiaoyuan Written Annex Contract Dispute Case','court_wh_jiangan','Contract Dispute','Housing lease contract dispute','2023-11-10','Tenant Zhou, Landlord Xu','Shahu Xiaoyuan written annex dispute: The parties disputed oral promises concerning ramp repairs and cleaning fees; the amount in dispute was approximately 24484 yuan.','Regarding the property at Shahu Xiaoyuan, both parties acknowledged that a dispute had arisen over their oral commitments concerning ramp repairs and cleaning fees; because the tenant promptly sent written notice after discovering the problem, they were unable to agree on the allocation of the deposit, repair, or service fees.','The contract draft and recording summary in the Shahu Xiaoyuan case file corroborate each other with the time records. On this basis, the court held that key matters capable of being included in the annex should primarily be governed by written agreements, and that promises made by either party but not included in the contract should be scrutinized strictly.','In the Shahu Xiaoyuan case, the court clarified that key matters capable of being included in an appendix should be governed primarily by written agreements, and that key fees and living conditions should be documented in contract appendices, handover forms, or notice records.','The court ruled as follows regarding Shahu Xiaoyuan: determine liability in accordance with the valid written terms; include the established loss of 11374 yuan in the liability; the parties shall continue performing the remainder of the contract in accordance with its terms.','Mediation','Wuhan, lease, written attachment, repairs');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_343795e4','(2025) E 0111 Civil First-Instance No. 14956','Shahu Residential Area Noise Rent Reduction Contract Dispute Case','court_wh_hongshan','Contract Dispute','Housing lease contract dispute','2025-03-05','Tenant Gu, landlord Han','Noise rent reduction dispute in Shahu Residential Area: prolonged construction noise exceeded the reasonable tolerance for normal living, with the disputed amount approximately 35168 yuan.','This case arose from a rent reduction issue due to noise after the handover of Shahu Zhuqu. The tenant submitted materials alleging that prolonged construction noise exceeded the reasonable tolerance threshold for ordinary living, while the landlord explained its handling by stating that “the parties had previously coordinated through the property management company but failed to reach an agreement.”','For the noise-related rent reduction issue at Shahu Residential Community, the court treated the construction notices and continuous audio recordings as the primary evidence, considered the condition at handover and subsequent remediation, and held that the landlord should be liable if the landlord knew of the significant impact but failed to disclose it.','Shahu residential community case confirmation: When a landlord knowingly fails to disclose matters with a material impact, the landlord should bear liability; the issues concerning door width, repairs, and service fees should all be determined based on specific written evidence.','Regarding the Shahu residential-community dispute, the court ordered a discretionary reduction or waiver of rent for the affected period, determining the amount supported by documentation to be 4679 yuan; the remaining claims were addressed separately.','Rejected','Wuhan, lease, noise-related rent reduction, service fee');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_c014d54c','(2024) E 0106 Civil First-Instance No. 4899','Shahu Dormitory Deposit Refund Contract Dispute Case','court_wh_wuchang','Contract Dispute','Housing lease contract dispute','2024-11-22','Tenant Chen and landlord Wu','Shahu Dormitory deposit refund dispute: The lessor withheld the deposit on the grounds of deep cleaning; the amount in dispute was approximately 16128 yuan.','After moving into Shahu Dormitory, tenant Chen claimed that the landlord withheld the deposit on the grounds of deep cleaning. During the handover at Shahu Dormitory, the tenant promptly sent written notice after discovering the issue, and the parties consequently disputed the timing of the notice and the scope of the costs.','The court, with respect to Shahu Dormitory, examined the transfer records and handover photographs. These materials can establish the course of the transaction; in conjunction with the sequence in which the parties performed, it can be determined that signs of normal use cannot automatically be deemed damage, and oral statements unsupported by other evidence shall not serve as the primary basis.','The key point of the judgment is that signs of normal use cannot automatically be deemed damage; in the Shahu dormitory rental, the deposit, accessibility facilities, and repair deadline cannot be based solely on oral statements.','The Shahu Dormitory deposit refund matter was ultimately resolved on the basis that the portion of the deposit corresponding to unproven losses would be refunded. Upon calculation, the supported amount was 14528 yuan; any portion exceeding the scope of the evidence was not supported.','Rejected','Wuhan, Rental, Deposit Refund, Service Fee');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_c95b0cf3','(2023) E 01 Civil First-Instance No. 16102','Shahu Yating Repair Responsibility Contract Dispute Case','court_wh_intermediate','Contract Dispute','Housing lease contract dispute','2023-05-01','Tenant Tang, Landlord Jiang','Shahu Yating repair responsibility dispute: After water seepage occurred in the bathroom, the parties disagreed over the repair deadline, and the disputed amount was approximately 30363 yuan.','After the tenancy relationship in Shahu Yating was established, an issue arose in which “the parties disagreed over the repair deadline after water seepage occurred in the bathroom.” The property handover form did not record the disputed item, and the tenant and landlord subsequently each presented evidence regarding the written attachments and actual losses.','When hearing the dispute over repair liability at Shahu Yating, the judicial panel first verified the repair request tickets and on-site inspection report, then compared them with the contract appendices and notice records. Based on the evidence currently available, when the landlord, after becoming aware of the issue, failed to carry out repairs promptly, the landlord should bear corresponding liability, which should be apportioned according to the actual impact.','In the Shahu Yating case, the court clarified that a landlord who, after becoming aware of an issue, fails to carry out timely repairs should bear the corresponding liability, and that key fees and living conditions should be documented in contract appendices, handover forms, or notice records.','The court ruled as follows regarding Shahu Yating: bear the repair costs and compensate for reasonable losses; include the established loss of 8862 yuan in the liability; the parties shall continue performing the remainder of the contract in accordance with its terms.','Mediation','Wuhan, rental, repair responsibility, accessibility');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_3f86662d','(2023) E 0102 Civil First-Instance No. 27002','Shahu Chunxiao Doorway-Width Disclosure Contract Dispute Case','court_wh_jiangan','Contract Dispute','Housing lease contract dispute','2023-02-27','Tenant Luo, Landlord Ye','Shahu Chunxiao doorway-width disclosure dispute: an intermediary verbally promised a specific entrance-door width, but the measurement at delivery did not match, with a disputed amount of approximately 9532 yuan.','Regarding the property at Shahu Chunxiao, both parties acknowledged that the intermediary had orally promised a certain entrance-door width, but the measurement at handover did not match; because the intermediary failed to provide complete records of the service process, they were unable to agree on the allocation of the deposit, repair, or service fees.','The chat records, doorway-width measurement photos, and time records in the Shahu Chunxiao case corroborate one another. On that basis, the court held that key residential conditions must be truthfully disclosed when they form the basis for entering into a contract, and that promises made by either party but omitted from the contract should be scrutinized strictly.','The Shahu Chunxiao case confirmed that key residential conditions must be truthfully disclosed when they form the basis for entering into a contract; the doorway width, repair, and service fees at issue should all be determined based on specific written evidence.','Regarding the Shahu Chunxiao dispute, the court ordered a refund of service fees and an adjustment of liability for breach of contract, determining the amount supported by documentation to be 4841 yuan; the remaining claims were addressed separately.','Mediation','Wuhan, rental, door width details, door width');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_83b57256','(2025) Hubei 0111 Civil First-Instance No. 5162','Shahu Heyuan Elevator Shutdown Contract Dispute Case','court_wh_hongshan','Contract Dispute','Housing lease contract dispute','2025-07-14','Tenant Xu, Landlord Shen','Shahu Heyuan elevator shutdown dispute: The prolonged shutdown of the elevator in a high-rise residential building affected normal use, involving a disputed amount of approximately RMB 23,428.','This case arose from the elevator being out of service after the handover of Shahu Heyuan. The tenant submitted materials alleging that the prolonged outage of the elevator in the high-rise residence affected normal use, while the landlord explained its handling by stating that “the tenant promptly sent written notice after discovering the problem.”','Regarding the elevator outage at Shahu Heyuan, the court relied primarily on property management notices and maintenance records, while considering the condition at handover and subsequent remedial measures; rent may be reduced at the court’s discretion when the outage continues long enough to affect habitability.','The key point of the ruling is that rent may be reduced at the court’s discretion when a prolonged service suspension reaches a level that affects habitability; in the Shahu Heye lease, the deposit, accessibility facilities, and repair deadlines cannot rely solely on oral statements.','The elevator shutdown at Shahu Heyuan was ultimately resolved by “reducing part of the rent in proportion to the affected period.” After calculation, the supported amount was RMB 2,484; the portion exceeding the scope of the evidence was not supported.','Mediation','Wuhan, Elevator Outage, Deposit');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_85857b4d','(2024) E 0106 Civil First Instance No. 24480','Shahu Qingting Passage Occupancy Contract Dispute Case','court_wh_wuchang','Contract Dispute','Housing lease contract dispute','2024-03-05','Tenant Han, landlord Lin','Shahu Qingting Passage Occupancy Dispute: The public ramp was repeatedly occupied by electric bicycles and miscellaneous items, with the disputed amount approximately RMB 21914.','After moving into Shahu Qingting, tenant Han claimed that the public ramp was repeatedly obstructed by electric bicycles and miscellaneous items. During the handover of Shahu Qingting, the tenant promptly sent written notice after discovering the issue, and the parties consequently disagreed over the timing of the notice and the scope of the fees.','The court, with respect to Shahu Qingting, examined the on-site video and property-management complaint records. These materials can establish the course of the transaction; in conjunction with the sequence in which the parties performed, it can be determined that the management party should take reasonable cleaning measures after receiving a report, and oral statements unsupported by other evidence shall not serve as the primary basis.','In the Shahu Qingting case, the court clarified that after receiving a report, the management party should take reasonable cleaning measures, and that key fees and living conditions should be documented in contract appendices, handover forms, or notice records.','The court ruled as follows regarding Shahu Qingting: complete the cleanup within the specified time limit and improve inspections; include the established loss of 8768 yuan in the liability; the parties shall continue performing the remainder of the contract in accordance with its terms.','Partial support','Wuhan, rental, passageway obstruction, accessibility');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_e8deb11a','(2025) E01 Civil First Instance No. 4003','Guanshan Apartment Intermediary Service Fee Contract Dispute Case','court_wh_intermediate','Contract Dispute','Housing lease contract dispute','2025-08-11','Tenant Wu, Landlord Zhou','Guanshan Apartment Intermediary Service Fee Dispute: After the signing failed to take place, the intermediary charged the entire service fee, with the disputed amount being approximately 34,989 yuan.','After the rental relationship at Guanshan Apartment was established, a problem arose in which the intermediary charged the entire service fee after the signing failed to take place. Upon discovering the problem, the tenant promptly sent written notice, after which the tenant and landlord each submitted evidence regarding the written attachments and actual losses.','When hearing the dispute over brokerage service fees for Guanshan Apartment, the collegiate panel first verified the service agreement and property-viewing records, then compared the contract attachments with the notice records. Based on the evidence available, when the service has not been fully performed, the fee should be determined in light of the actual workload, and liability should be apportioned according to the actual impact.','Confirmation in the Guanshan Apartment Case: When the services have not been fully performed, the fee should be determined in light of the actual workload; the issues of doorway width, repairs, and service fees involved must all be assessed based on specific written evidence.','Regarding the Guanshan Apartment dispute, the court ordered a refund of service fees that were not actually incurred; the amount supported by documentation was determined to be 33531 yuan, and the remaining claims were handled separately.','Support','Wuhan, rental, agency service fee, accessibility');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_45e327ad','(2023) E 0102 Civil First-Instance No. 2776','Contract dispute over early lease termination at Guanshan Jiayuan','court_wh_jiangan','Contract Dispute','Housing lease contract dispute','2023-11-08','Tenant Jiang, Landlord Gu','Dispute over early lease termination at Guanshan Jiayuan: The tenant sought early termination because of changes in living conditions, involving a disputed amount of approximately 5331 yuan.','Regarding the property at Guanshan Jiayuan, both parties confirmed that the tenant had requested early termination due to changes in the living conditions; because the disputed items were not recorded on the property handover form, they were unable to reach agreement on how the deposit, repair, or service costs should be borne.','The contract appendices, communication emails, and time records in the Guanshan Jiayuan case file corroborate one another. On this basis, the court held that liquidated damages may be adjusted in accordance with the law when they are excessively high and the losses are limited, and that promises not included in the contract by either party should be subject to strict scrutiny.','The key point of the ruling is that when liquidated damages are excessively high and the losses are limited, they may be adjusted in accordance with the law; in the Guanshan Jiayuan lease, the deposit, accessibility facilities, and repair deadlines cannot rely solely on oral statements.','The matter of early lease termination at Guanshan Jiayuan was ultimately handled on the basis of “bearing appropriate liability according to actual losses.” Upon calculation, the supported amount was 4072 yuan; the portion exceeding the scope of the evidence was not supported.','Rejected','Wuhan, Early Lease Termination, Repairs');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_09074a15','(2024) E 0111 Civil First-Instance No. 1323','Guanshan Lixiang Identity Documents Contract Dispute Case','court_wh_hongshan','Contract Dispute','Housing lease contract dispute','2024-11-09','Tenant Ye, Landlord Chen','Guanshan Lixiang identity documents dispute: Before signing the contract, the agent requested excessive photos of identity documents; the disputed amount is approximately 958 yuan.','This case arose from an identity-document issue after the handover of Guanshan Lixiang. The tenant submitted materials stating that the agency had requested too many photos of identity documents before signing the lease, while the landlord explained its handling by saying that “the tenant promptly sent written notice after discovering the issue.”','For the identity-document issue at Guanshan Lixiang, the court primarily relied on the information-collection page and chat records, considered the handover condition and subsequent remedial measures, and held that rental verification should follow the principles of clear purpose and minimum necessity.','In the Guanshan Lixiang case, the court held that lease verification should follow the principles of purpose limitation and minimum necessity; key fees and living conditions should be documented through contract appendices, handover forms, or notice records.','The court ruled as follows regarding Guanshan Lixiang: delete irrelevant materials and cease further processing; established losses shall be included in the liability at 472 yuan, and the parties shall continue performing the contract with respect to the remainder.','Mediation','Wuhan, rental, identity documents, accessibility');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_b75ec80a','(2025) E 0106 Civil First Instance No. 2000','Guanshan Community Written-Appendix Contract Dispute Case','court_wh_wuchang','Contract Dispute','Housing lease contract dispute','2025-07-14','Tenant Shen, Landlord Tang','Guanshan Community written-appendix dispute: The parties disputed oral promises regarding ramp repairs and cleaning fees, with the disputed amount approximately 22888 yuan.','After moving into Guanshan Community, Tenant Shen claimed that the parties disputed an oral agreement regarding ramp repairs and cleaning fees. During the handover of Guanshan Community, the tenant promptly sent written notice after discovering the issue, and the parties consequently disagreed over the timing of the notice and the scope of the costs.','In the matter concerning Guanshan Shequ, the court examined the draft contract and recording summary. These materials establish how the transaction proceeded. In conjunction with the order in which the parties performed, it may be determined that key matters capable of being included in an attachment should primarily be based on written agreement, while oral assertions unsupported by other evidence should not serve as the primary basis.','Guanshan Community case confirmation: Key matters that can be included in an appendix should primarily be governed by written agreements, and the issues concerning door width, repairs, and service fees should all be determined by reference to the specific written evidence.','Regarding the Guanshan Community dispute, the court ordered liability to be determined in accordance with the valid written terms; the amount supported by documentation was determined to be 20559 yuan, and the remaining claims were handled separately.','Partial support','Wuhan, lease, written attachment, repairs');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_e4ba1097','(2024) E 01 Civil First Instance No. 23628','Guanshan Xinyuan Noise-Related Rent Reduction Contract Dispute Case','court_wh_intermediate','Contract Dispute','Housing lease contract dispute','2024-02-22','Tenant Lin, Landlord Luo','Guanshan Xinyuan Noise-Related Rent Reduction Dispute: Long-term construction noise exceeded the reasonable tolerance for ordinary living, with the disputed amount approximately 31587 yuan.','After the lease relationship at Guanshan Xinyuan was established, the issue of “long-term construction noise exceeding the reasonable tolerance for ordinary living” arose. The tenant promptly sent written notice upon discovering the issue, after which the tenant and landlord each presented evidence regarding the written attachments and actual losses.','When hearing the dispute over a rent reduction for noise at Guanshan Xinyuan, the collegiate panel first verified the construction notices and continuous audio recordings, then compared the contract attachments with the notice records. Based on the evidence available, when the landlord knew of a significant impact but still failed to disclose it, the landlord should bear liability, which should be apportioned according to the actual impact.','The key holding is that a landlord should be held liable when the landlord knows of matters with a significant impact but fails to disclose them; in a Guanshan Xinyuan rental, the deposit, accessibility facilities, and repair deadlines cannot be based solely on oral statements.','The rent reduction matter due to noise at Guanshan Xinyuan was ultimately handled by “discretionarily reducing or waiving rent for the affected period.” After calculation, the supported amount was 21776 yuan; the portion exceeding the scope of the evidence was not supported.','Rejected','Wuhan, lease, noise-related rent reduction, service fee');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_01b78932','(2025) E0102 Civil First Instance Case No. 17814','Guanshan Huating Deposit Refund Contract Dispute Case','court_wh_jiangan','Contract Dispute','Housing lease contract dispute','2025-04-05','Tenant Zhou, Landlord Xu','Guanshan Huating deposit refund dispute: The landlord withheld the deposit on the grounds of deep cleaning, involving a disputed amount of approximately 33404 yuan.','Regarding the property at Guanshan Huating, both parties confirmed that the landlord had withheld the deposit on the grounds of deep cleaning; because the landlord submitted repair quotations and proof of payment, they were unable to reach agreement on how the deposit, repair, or service costs should be borne.','The transfer records, handover photographs, and time records in the Guanshan Huating case file corroborate one another. On this basis, the court held that traces of normal use could not automatically be deemed damage and strictly scrutinized promises between the parties that were not included in the contract.','In the Guanshan Huating case, the court held that ordinary signs of use cannot automatically be deemed damage; key fees and living conditions should be documented through contract appendices, handover forms, or notice records.','The court ruled as follows regarding Guanshan Huating: return the portion of the deposit corresponding to unproven losses; established losses shall be included in the liability at 20337 yuan, and the parties shall continue performing the contract with respect to the remainder.','Mediation','Wuhan, lease, deposit return, security deposit');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_da93aeb9','(2024) Hubei 0111 Civil First Instance No. 3404','Guanshan Block Repair Responsibility Contract Dispute Case','court_wh_hongshan','Contract Dispute','Housing lease contract dispute','2024-01-26','Tenant Gu, landlord Han','Guanshan Block repair responsibility dispute: After water seepage occurred in the bathroom, the parties disagreed over the repair deadline, with the disputed amount approximately 18462 yuan.','This case arose from a repair-responsibility issue after the handover of Guanshan Block. The tenant submitted materials stating that, after water seepage occurred in the bathroom, the parties disagreed over the repair timeframe, while the landlord explained the handling process by stating that “the landlord submitted repair quotations and proof of payment.”','For the repair liability issue at Guanshan Jiequ, the court primarily relied on the repair requests and on-site inspection report, considered the handover condition and subsequent remedial measures, and held that the landlord bears corresponding liability when, after becoming aware of the issue, it failed to make timely repairs.','Guanshan Block case confirmation: A landlord who, after becoming aware of the issue, fails to make timely repairs shall bear corresponding liability; the issues concerning door width, repairs, and service fees should all be determined by reference to the specific written evidence.','Regarding the Guanshan neighborhood dispute, the court ordered the responsible party to bear the repair costs and compensate reasonable losses; the amount supported by documentation was determined to be 6817 yuan, and the remaining claims were handled separately.','Partial support','Wuhan, rental, repair responsibility, repairs');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_c757df8d','(2024) E 0106 Civil First-Instance No. 8563','Guanshan Linli Doorway-Width Statement Contract Dispute Case','court_wh_wuchang','Contract Dispute','Housing lease contract dispute','2024-04-06','Tenant Chen and landlord Wu','Guanshan Linli doorway-width dispute: The agent verbally promised that the entrance door would be a certain width, but measurements at handover did not match; the disputed amount is approximately 7211 yuan.','After moving into Guanshan Linli, tenant Chen claimed that the agent had orally promised a certain entrance-door width, but the measurement at handover did not match. During the handover at Guanshan Linli, the tenant promptly sent written notice after discovering the issue, and the parties consequently disputed the timing of the notice and the scope of the costs.','In the matter concerning Guanshan Linli, the court examined chat records and photographs measuring the doorway width. These materials establish how the transaction proceeded. In conjunction with the order in which the parties performed, it may be determined that key residential conditions should be truthfully disclosed when they constitute the basis for entering into the contract, while oral assertions unsupported by other evidence should not serve as the primary basis.','The key holding is that essential residential conditions forming the basis of a contract must be truthfully disclosed; in Guanshan Neighborhood rentals, the deposit, accessibility facilities, and repair deadlines cannot be left solely to oral representations.','The Guanshan Linli doorway-width matter will ultimately be handled by “refunding the service fee and adjusting the liability for breach of contract.” After calculation, the amount upheld is 410 yuan; portions exceeding the scope of the evidence are not supported.','Partial support','Wuhan, rental, door width details, repairs');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_514c2353','(2025) E01 Civil First-Instance No. 19871','Guanshan Xiaoyuan Elevator Shutdown Contract Dispute Case','court_wh_intermediate','Contract Dispute','Housing lease contract dispute','2025-01-03','Tenant Tang, Landlord Jiang','Guanshan Xiaoyuan Elevator Shutdown Dispute: The long-term shutdown of the elevator in a high-rise residential building affected normal use, with the disputed amount approximately 12740 yuan.','After the lease relationship at Guanshan Xiaoyuan was established, the issue of “the long-term shutdown of the elevator in a high-rise residential building affecting normal use” arose. The landlord submitted repair quotations and proof of payment, after which the tenant and landlord each presented evidence regarding the written attachments and actual losses.','When hearing the dispute over an elevator shutdown at Guanshan Xiaoyuan, the collegiate panel first verified the property-management notices and maintenance records, then compared the contract attachments with the notice records. Based on the evidence available, when a prolonged shutdown has reached a level that affects habitability, a rent reduction may be granted as appropriate, and liability should be apportioned according to the actual impact.','In the Guanshan Xiaoyuan case, the court held that rent may be reduced at its discretion when a prolonged shutdown reaches a level that affects habitability; key fees and living conditions should be documented through contract appendices, handover forms, or notice records.','The court ruled as follows regarding Guanshan Xiaoyuan: reduce part of the rent for the affected period; established losses shall be included in the liability at 4712 yuan, and the parties shall continue performing the contract with respect to the remainder.','Support','Wuhan, Elevator Outage, Deposit');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_ca69eca2','(2024) E 0102 Civil First-Instance No. 7287','Guanshan Residential Area Passageway Occupancy Contract Dispute Case','court_wh_jiangan','Contract Dispute','Housing lease contract dispute','2024-10-02','Tenant Luo, Landlord Ye','Guanshan Residential Area Passageway Occupancy Dispute: The public ramp was repeatedly occupied by electric bicycles and miscellaneous items, involving a disputed amount of approximately 26385 yuan.','Regarding the property in the Guanshan Residential Area, both parties confirmed that the common ramp had repeatedly been occupied by electric bicycles and miscellaneous items; because they had previously attempted to resolve the matter through property management but failed to reach agreement, they were unable to reach agreement on how the deposit, repair, or service costs should be borne.','The on-site video and property-management complaint records in the Guanshan Residential Area case corroborate each other in terms of their timestamps. On that basis, the court held that the management party should have taken reasonable cleanup measures after receiving the report and that promises not included in the contract should be scrutinized strictly.','The Guanshan Residential Area case confirms that the management party should have taken reasonable cleanup measures after receiving the report; the issues concerning doorway width, repairs, and service fees must all be determined based on specific written evidence.','Regarding the Guanshan Residential Area dispute, the court ordered cleanup within a specified time limit and improvements to inspections; the amount supported by documentation was determined to be 21404 yuan, and the remaining claims were handled separately.','Mediation','Wuhan, rental, passageway obstruction, accessibility');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_67384789','(2023) E 0111 Civil First Instance No. 13302','Contract dispute over the intermediary service fee at Guanshan Dormitory','court_wh_hongshan','Contract Dispute','Housing lease contract dispute','2023-09-15','Tenant Xu, Landlord Shen','Dispute over the intermediary service fee at Guanshan Dormitory: After the signing failed to materialize, the intermediary charged the full service fee, involving a disputed amount of approximately 2178 yuan.','This case arose from a brokerage service fee issue after the handover of Guanshan Dormitory. The tenant submitted materials stating that the broker charged the full service fee after the contract was not concluded, while the landlord explained the handling process by stating that “the landlord submitted repair quotations and proof of payment.”','For the dispute over an agency service fee at Guanshan Dormitory, the court treated the service agreement and property-viewing records as the primary evidence, considered the delivery status and subsequent remedial measures, and held that when the service was not fully performed, the fee should be determined in light of the actual workload.','The key point of the ruling is that when services have not been fully performed, the fees should be determined based on the actual amount of work completed; in the Guanshan Dormitory lease, the deposit, accessibility facilities, and repair deadlines cannot rely solely on oral statements.','The matter of the intermediary service fee at Guanshan Dormitory was ultimately handled on the basis of “refunding service fees that were not actually incurred.” Upon calculation, the supported amount was 2050 yuan; the portion exceeding the scope of the evidence was not supported.','Partial support','Wuhan, rental, agency service fee, repairs');
