INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_37c1ff4b','(2023) E 0111 Civil First Instance No. 1003','Guanshan Qingting Noise-Related Rent Reduction Contract Dispute Case','court_wh_hongshan','Contract Dispute','Housing lease contract dispute','2023-02-03','Tenant Ye, Landlord Chen','Guanshan Qingting noise-related rent reduction dispute: Prolonged construction noise exceeded the reasonable tolerance threshold for ordinary living, with the disputed amount approximately 23950 yuan.','This case arose from a rent reduction due to noise issue after the handover of Guanshan Qingting. The tenant submitted materials stating that prolonged construction noise exceeded a reasonable level of tolerance for daily living, while the landlord explained the handling process by stating that “the landlord submitted repair quotations and proof of payment.”','For the noise-related rent reduction issue at Guanshan Qingting, the court primarily relied on the construction notice and continuous audio recordings, considered the handover condition and subsequent remedial measures, and held that the landlord is liable when, despite knowing of the material impact, it failed to disclose it.','In the Guanshan Qingting case, the court held that a lessor should be held liable when it knew of a major adverse impact but failed to disclose it; key fees and living conditions should be documented through contract appendices, handover forms, or notice records.','The court ruled as follows regarding Guanshan Qingting: reduce the rent for the affected period as appropriate; established losses shall be included in the liability at 22475 yuan, and the parties shall continue performing the contract with respect to the remainder.','Partial support','Wuhan, lease, noise-related rent reduction, accessibility');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_1d8b68d0','(2023) E 0106 Civil First Instance No. 9633','Xudong Apartment Security Deposit Refund Contract Dispute Case','court_wh_wuchang','Contract Dispute','Housing lease contract dispute','2023-07-03','Tenant Shen, Landlord Tang','Xudong Apartment Security Deposit Refund Dispute: The lessor withheld the security deposit on the grounds of deep cleaning, with the disputed amount approximately RMB 26,267.','Tenant Shen moved into Xudong Apartment and later claimed that the landlord withheld the deposit on the grounds of deep cleaning; during the handover at Xudong Apartment, the tenant promptly sent written notice after discovering the issue, whereupon the parties disputed the timing of the notice and the scope of the costs.','With respect to Xudong Apartment, the court reviewed the transfer records and handover photographs. These materials establish the course of the transaction. Considering the sequence in which the parties performed, it may be concluded that ordinary signs of use cannot automatically be deemed damage, and unsupported oral assertions shall not serve as the primary basis.','Xudong Apartment Case Confirmed: Traces resulting from normal use cannot automatically be deemed damage; the issues involving door width, repairs, and service fees should all be assessed based on the specific written evidence.','Regarding the dispute concerning the Xudong apartment, the court ordered the return of the portion of the deposit corresponding to unproven losses; the amount supported by documentation was determined to be 8625 yuan, and the remaining claims were addressed separately.','Support','Wuhan, Rental, Deposit Refund, Accessibility');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_39cface4','(2024) Hubei 01 Civil First Instance No. 14910','Contract Dispute Case Concerning Repair Liability for Xudong Jiayuan','court_wh_intermediate','Contract Dispute','Housing lease contract dispute','2024-04-24','Tenant Lin, Landlord Luo','Repair Liability Dispute at Xudong Jiayuan: After the bathroom began leaking, the parties disagreed over the repair period; the disputed amount was approximately 7501 yuan.','After the rental relationship for Xudong Jiayuan was established, an issue arose in which “the bathroom began leaking, after which the parties disagreed over the repair period.” The intermediary was unable to provide complete records of the service process, after which the lessee and lessor each presented evidence regarding the written attachments and actual losses.','In hearing the dispute over repair liability at Xudong Jiayuan, the judicial panel first verified the repair request orders and on-site inspection reports, then compared them with the contract appendices and notice records. Based on the evidence currently available, the landlord should bear corresponding liability for failing to make timely repairs after becoming aware of the issue, with liability apportioned according to the actual impact.','The key point of the judgment is that a landlord bears corresponding liability if, after becoming aware of an issue, they fail to make repairs promptly; in the Xudong Jiayuan lease, the deposit, accessibility facilities, and repair deadline cannot be left to oral statements alone.','The repair liability matter for Xudong Jiayuan was ultimately resolved on the basis that the responsible party would “bear the repair costs and compensate for reasonable losses.” Upon calculation, the supported amount was 4741 yuan; the portion exceeding the scope of the evidence was not supported.','Rejected','Wuhan, rental, repair responsibility, door width');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_1d09028c','(2024) E0102 Civil First-Instance No. 17104','Xudong Lixiang Door-Width Disclosure Contract Dispute Case','court_wh_jiangan','Contract Dispute','Housing lease contract dispute','2024-03-22','Tenant Zhou, Landlord Xu','Xudong Lixiang Door-Width Disclosure Dispute: The intermediary verbally promised a certain entrance-door width, but the measurement at handover did not match; the disputed amount was approximately 4519 yuan.','Regarding the property at Xu Dong Li Xiang, both parties confirmed that the intermediary orally promised a certain entrance-door width, but the measurement at handover did not match; because the disputed item was not recorded on the property handover checklist, they were unable to agree on the allocation of the deposit, repair, or service costs.','The chat records, door-width measurement photos, and time records in the Xudong Lixiang case file corroborate one another. On this basis, the court held that key living conditions forming the basis of the contract must be truthfully disclosed and that promises not included in the contract must be scrutinized strictly.','The court held in the Xu Dong Lixiang case that when key living conditions form the basis for entering into the contract, they must be truthfully disclosed; key costs and living conditions should be formally documented through contract appendices, handover forms, or notice records.','The court ruled regarding Xudong Lixiang: the service fees shall be refunded and liability for breach adjusted; the established losses shall be assessed at 1464 yuan for purposes of liability, and the parties shall otherwise continue performing the contract in accordance with its terms.','Rejected','Wuhan, rental, door width details, accessibility');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_6f076425','(2024) E 0111 Civil First-Instance No. 10061','Xudong Community Elevator Shutdown Contract Dispute Case','court_wh_hongshan','Contract Dispute','Housing lease contract dispute','2024-02-09','Tenant Gu, landlord Han','Xudong Community elevator shutdown dispute: The prolonged shutdown of elevators in a high-rise residence affected normal use, with the disputed amount approximately 25906 yuan.','This case arose from an elevator shutdown issue after the handover of Xudong Community. The tenant submitted materials stating that the prolonged shutdown of the elevator in the high-rise residential building affected normal use, while the landlord explained its handling by saying that “the agency was unable to provide complete records of the service process.”','Regarding the elevator outage in Xudong Community, the court treated property management notices and maintenance records as the key evidence, considered the handover condition and subsequent remedial measures, and held that rent may be reduced at its discretion when the prolonged outage substantially affects habitability.','Confirmation in the Xudong Community case: When a continuous suspension of service reaches a level that affects residential use, a rent reduction may be considered; issues involving door width, repairs, and service fees should all be determined based on specific written evidence.','Regarding the dispute concerning the Xudong community, the court ordered a partial rent reduction for the affected period; the amount supported by documentation was determined to be 11764 yuan, and the remaining claims were addressed separately.','Rejected','Wuhan, rental, elevator outage, service fee');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_fd40cfc4','(2024) E 0106 Civil First-Instance No. 6901','Xudong Xinyuan Passageway Encroachment Contract Dispute Case','court_wh_wuchang','Contract Dispute','Housing lease contract dispute','2024-11-06','Tenant Chen and landlord Wu','Xudong Xinyuan passageway encroachment dispute: The public ramp was repeatedly occupied by electric bicycles and miscellaneous items, with the disputed amount being approximately 28004 yuan.','After moving into Xudong Xinyuan, tenant Chen claimed that the public ramp was repeatedly obstructed by electric bicycles and miscellaneous items. During the handover at Xudong Xinyuan, the agent was unable to provide complete records of the service process, and the parties consequently disputed the timing of the notice and the scope of the costs.','With respect to Xudong Xinyuan, the court reviewed the on-site video and property-management complaint records. These materials establish the course of the transaction. Considering the sequence in which the parties performed, it may be concluded that the management party should take reasonable cleaning measures after receiving a report, and unsupported oral assertions shall not serve as the primary basis.','The key holding is that after receiving a report, the management party should take reasonable cleanup measures; in the Xudong Xinyuan lease, the deposit, accessibility facilities, and repair deadlines cannot rely solely on oral statements.','The Xudong Xinyuan passageway encroachment matter was ultimately handled by “clearing it within a specified time limit and improving inspections.” After calculation, the supported amount was 26500 yuan; any portion beyond the scope of the evidence was not supported.','Partial support','Wuhan, rental, passageway obstruction, deposit');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_fe23ba0a','(2024) E01 Civil First Instance Case No. 7037','Xudong Huating Intermediary Service Fee Contract Dispute Case','court_wh_intermediate','Contract Dispute','Housing lease contract dispute','2024-05-06','Tenant Tang, Landlord Jiang','Xudong Huating intermediary service fee dispute: After the contract was not concluded, the intermediary charged the entire service fee; the disputed amount was approximately 32,474 yuan.','After the tenancy at Xudong Huating was established, an issue arose in which the intermediary charged the entire service fee after the contract was not concluded. The disputed items were not recorded on the property handover form, and the tenant and landlord subsequently each submitted evidence concerning the written attachments and actual losses.','In hearing the dispute over an agency service fee at Xudong Huating, the judicial panel first verified the service agreement and property viewing records, then compared them with the contract appendices and notice records. Based on the evidence currently available, if the services were not fully performed, the fee should be determined in light of the actual amount of work completed, with liability apportioned according to the actual impact.','In the Xudong Huating case, the court clarified that when services are not fully performed, fees should be determined based on the actual amount of work completed, and that key fees and residential conditions should be documented through contract appendices, handover forms, or notification records.','The court ruled regarding Xudong Huating: refund service fees for services not actually provided; the verified losses are assessed at 22729 yuan and assigned as liability, while the parties shall continue performing the remainder of the contract.','Rejected','Wuhan, rental, agency service fee, service fee');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_3ec87a23','(2024) E0102 Civil First-Instance No. 10336','Xudong Neighborhood Early Lease Termination Contract Dispute Case','court_wh_jiangan','Contract Dispute','Housing lease contract dispute','2024-08-04','Tenant Luo, Landlord Ye','Xudong Neighborhood early lease termination dispute: The tenant sought early termination due to changes in living conditions, with the disputed amount approximately 9466 yuan.','Regarding the Xudong Jiequ property, the parties confirm that the tenant requested early termination due to changes in living conditions; because the intermediary was unable to provide complete records of the service process, they were unable to reach agreement on how the deposit, repair costs, or service fees should be allocated.','The contract attachments, correspondence emails, and time records in the Xudong Neighborhood case file corroborated one another. On that basis, the court held that a penalty may be adjusted in accordance with the law when it is excessively high and the losses are limited, and it strictly scrutinized commitments not included in the contract.','Confirmation in the Xudong Neighborhood case: A penalty may be adjusted in accordance with the law when it is excessively high and the losses are limited; issues involving door width, repairs, and service fees should all be determined based on specific written evidence.','Regarding the dispute concerning the Xudong neighborhood, the court ordered appropriate liability based on the actual losses; the amount supported by documentation was determined to be 774 yuan, and the remaining claims were addressed separately.','Partial support','Wuhan, Early Lease Termination, Deposit');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_6b30650f','(2025) E 0111 Civil First-Instance No. 17557','Xudong Neighbor Identity Materials Contract Dispute Case','court_wh_hongshan','Contract Dispute','Housing lease contract dispute','2025-08-09','Tenant Xu, Landlord Shen','Xudong Neighbor identity-materials dispute: Before signing the contract, the intermediary requested excessive photographs of identity documents, with the disputed amount approximately 13136 yuan.','This case arose from an identity-document issue after the handover of Xudong Neighborhood. The tenant submitted materials stating that the agency had requested too many photos of identity documents before signing the lease, while the landlord explained its handling by saying that “the disputed items were not recorded on the property handover form.”','Regarding the identity-document issue in Xudong Neighborhood, the court treated the information-collection page and chat records as the key evidence, considered the handover condition and subsequent remedial measures, and held that rental verification should follow the principles of clearly defined purpose and minimum necessity.','The key holding is that lease verification should follow the principles of purpose specification and data minimization; in the Xudong Neighborhood lease, the deposit, accessibility facilities, and repair deadlines cannot rely solely on oral statements.','The Xudong Neighbor identity-materials matter was ultimately handled by “deleting irrelevant materials and ceasing further processing.” After calculation, the supported amount was 3898 yuan, while the portion exceeding the scope of the evidence was not supported.','Partial support','Wuhan, rental, identity documents, service fee');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_0f08819c','(2025) E 0106 Civil First Instance No. 12312','Contract Dispute Case Concerning the Written Attachments for Xudong Courtyard','court_wh_wuchang','Contract Dispute','Housing lease contract dispute','2025-08-27','Tenant Han, landlord Lin','Dispute over the Written Attachments for Xudong Courtyard: The parties disputed oral promises regarding ramp repairs and cleaning fees, involving a disputed amount of approximately 24,751 yuan.','After moving into Xudong Xiaoyuan, tenant Han claimed that the parties disputed their oral agreement regarding ramp repairs and cleaning fees. During the handover of Xudong Xiaoyuan, the tenant promptly sent written notice after discovering the issue, and the parties consequently disagreed over the timing of the notice and the scope of the fees.','With respect to Xudong Courtyard, the court reviewed the contract draft and audio-recording summary. These materials establish the course of the transaction. Considering the sequence in which the parties performed, it may be concluded that key matters capable of being included in an attachment should be based primarily on a written agreement, and unsupported oral assertions shall not serve as the primary basis.','In the Xudong Xiaoyuan case, the court clarified that key matters capable of being included in an appendix should primarily be governed by written agreements, and that key fees and residential conditions should be documented through contract appendices, handover forms, or notification records.','The court ruled regarding Xudong Xiaoyuan: determine liability in accordance with the valid written terms; the verified losses are assessed at 21522 yuan and assigned as liability, while the parties shall continue performing the remainder of the contract.','Rejected','Wuhan, lease, written attachment, accessibility');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_1d000dfd','(2024) Hubei 01 Civil First Instance No. 10624','Xudong Residential Community Noise-Related Rent Reduction Contract Dispute Case','court_wh_intermediate','Contract Dispute','Housing lease contract dispute','2024-01-16','Tenant Wu, Landlord Zhou','Xudong Residential Community Noise-Related Rent Reduction Dispute: Prolonged construction noise exceeded reasonable tolerance for normal living, with the disputed amount approximately RMB 18,968.','After the lease relationship was established at Xudong Residential Community, prolonged construction noise exceeded reasonable tolerance for normal living. The intermediary failed to provide complete records of the service process, after which the tenant and lessor each submitted evidence regarding the written attachments and actual losses.','In hearing the dispute over a rent reduction for noise at the Xudong Residential Community, the judicial panel first verified the construction notices and continuous audio recordings, then compared them with the contract appendices and notice records. Based on the evidence currently available, the landlord should bear liability if, despite knowing of the significant impact, it failed to disclose it, with liability apportioned according to the actual impact.','Xudong Residential Community Case Confirmed: When a lessor knows of a significant adverse impact but fails to disclose it, the lessor should bear liability; the issues involving door width, repairs, and service fees should all be assessed based on the specific written evidence.','Regarding the dispute concerning the Xudong residential area, the court ordered a discretionary reduction or waiver of rent for the affected period; the amount supported by documentation was determined to be 10002 yuan, and the remaining claims were addressed separately.','Rejected','Wuhan, lease, noise-related rent reduction, door width');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_a1eb304b','(2024) E 0102 Civil First-Instance No. 5019','Contract Dispute Case Concerning the Return of Xudong''s Dormitory Deposit','court_wh_jiangan','Contract Dispute','Housing lease contract dispute','2024-11-24','Tenant Jiang, Landlord Gu','Dispute over the Return of Xudong''s Dormitory Deposit: The lessor withheld the deposit on the grounds of deep cleaning, involving a disputed amount of approximately 25,242 yuan.','Regarding the Xudong Dormitory property, the parties confirm that the landlord withheld the deposit on the grounds of deep cleaning; because the disputed items were not recorded on the property handover checklist, they were unable to reach agreement on how the deposit, repair costs, or service fees should be allocated.','The transfer records and handover photographs in the Xudong dormitory case file corroborate each other with the time records. On this basis, the court held that traces of normal use could not automatically be deemed damage and strictly scrutinized the parties'' promises that were not written into the contract.','The key point of the judgment is that signs of normal use cannot automatically be deemed damage; in the Xudong dormitory rental, the deposit, accessibility facilities, and repair deadline cannot be based solely on oral statements.','The matter of returning Xudong''s dormitory deposit was ultimately resolved by “returning the portion of the deposit for which no loss was proven.” After calculation, the supported amount was 23,528 yuan; any portion exceeding the scope of the evidence was not supported.','Rejected','Wuhan, Rental, Deposit Refund, Repairs');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_e4b65fb5','(2025) Hubei 0111 Civil First-Instance No. 8271','Xudong Yating Maintenance Responsibility Contract Dispute Case','court_wh_hongshan','Contract Dispute','Housing lease contract dispute','2025-12-13','Tenant Ye, Landlord Chen','Xudong Yating Maintenance Responsibility Dispute: After water seepage occurred in the bathroom, the parties disagreed over the repair deadline; the disputed amount was approximately 33481 yuan.','This case arose from a dispute over repair responsibilities after the handover of Xudong Yating. The tenant submitted materials stating that, after water seepage in the bathroom, the parties disagreed over the repair deadline, while the landlord explained its handling by stating that “the tenant promptly sent written notice after discovering the problem.”','Regarding the repair-liability issue in Xudong Yating, the court treated repair orders and on-site inspection reports as the key evidence, considered the handover condition and subsequent remedial measures, and held that a landlord who fails to make timely repairs after becoming aware of the issue should bear the corresponding liability.','The court held in the Xu Dong Yating case that a landlord who fails to make timely repairs after becoming aware of the issue should bear the corresponding responsibility; key costs and living conditions should be formally documented through contract appendices, handover forms, or notice records.','The court ruled regarding Xudong Yating: repair costs shall be borne and reasonable losses compensated; the established losses shall be assessed at 18952 yuan for purposes of liability, and the parties shall otherwise continue performing the contract in accordance with its terms.','Mediation','Wuhan, rental, repair responsibility, service fee');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_4ff81c1f','(2025) E 0106 Civil First Instance No. 16417','Xudong Chunxiao Doorway Width Disclosure Contract Dispute Case','court_wh_wuchang','Contract Dispute','Housing lease contract dispute','2025-11-27','Tenant Shen, Landlord Tang','Xudong Chunxiao doorway width disclosure dispute: The intermediary verbally promised a particular entrance doorway width, but the measurement at handover did not match, with the disputed amount being approximately 1000 yuan.','Tenant Shen moved into Xudong Chunxiao and later claimed that the agent had orally promised a certain entrance-door width, but the measurement at handover did not match; during the handover at Xudong Chunxiao, the landlord submitted repair quotations and proof of payment, whereupon the parties disputed the timing of the notice and the scope of the costs.','With respect to Xudong Chunxiao, the court reviewed the chat records and photographs measuring the doorway width. These materials establish the course of the transaction. Considering the sequence in which the parties performed, it may be concluded that key living conditions, when they form the basis for entering into the contract, should be truthfully disclosed, and unsupported oral assertions shall not serve as the primary basis.','The Xudong Chunxiao case confirmed that when key residential conditions form the basis for entering into a contract, they must be truthfully disclosed; the matters involving doorway width, repairs, and service fees should all be determined based on specific written evidence.','Regarding the dispute concerning Xudong Chunxiao, the court ordered a refund of the service fee and adjusted the liability for breach of contract; the amount supported by documentation was determined to be 393 yuan, and the remaining claims were addressed separately.','Mediation','Wuhan, rental, door width details, service fee');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_ddfc4df9','(2023) E01 Civil First-Instance No. 5239','Xudong Heyuan elevator shutdown contract dispute case','court_wh_intermediate','Contract Dispute','Housing lease contract dispute','2023-10-05','Tenant Lin, Landlord Luo','Xudong Heyuan elevator shutdown dispute: The prolonged shutdown of elevators in a high-rise residential building affected normal use; the disputed amount was approximately 21,680 yuan.','After the rental relationship for Xudong Heyuan was established, an issue arose in which “the elevator in the high-rise residential building had been out of service for an extended period, affecting normal use.” The lessor submitted repair quotations and proof of payment, after which the lessee and lessor each presented evidence regarding the written attachments and actual losses.','In hearing the dispute over the elevator shutdown at Xudong Heyuan, the judicial panel first verified the property management notices and maintenance records, then compared them with the contract appendices and notice records. Based on the evidence currently available, rent may be reduced as appropriate when the prolonged shutdown reaches a level that affects habitability, with liability apportioned according to the actual impact.','The key point of the ruling is that rent may be reduced at the court’s discretion when a prolonged service suspension reaches a level that affects habitability; in the Xudong Heye lease, the deposit, accessibility facilities, and repair deadlines cannot rely solely on oral statements.','The Xudong Heyuan elevator shutdown matter was ultimately resolved by implementing “a partial rent reduction based on the duration of the impact.” Upon calculation, the supported amount was 6,524 yuan; the portion exceeding the scope of the evidence was not supported.','Partial support','Wuhan, rental, elevator outage, door width');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_211340e2','(2025) E0102 Civil First Instance Case No. 16243','Xudong Qingting Passageway Encroachment Contract Dispute Case','court_wh_jiangan','Contract Dispute','Housing lease contract dispute','2025-05-27','Tenant Zhou, Landlord Xu','Xudong Qingting passageway encroachment dispute: The public ramp was repeatedly occupied by electric bicycles and miscellaneous items, with the disputed amount being approximately 13261 yuan.','Regarding the Xudong Qingting property, the parties confirm that the common ramp was repeatedly obstructed by electric bicycles and miscellaneous items; because the landlord submitted repair quotations and proof of payment, they were unable to reach agreement on how the deposit, repair costs, or service fees should be allocated.','The on-site videos and property management complaint records in the Xudong Qingting case file corroborate each other through the time records. On this basis, the court held that the management party should have taken reasonable clearing measures after receiving the report and strictly scrutinized the parties’ promises that were not written into the contract.','In the Xudong Qingting case, the court clarified that the management party should take reasonable cleanup measures after receiving a report, and that key fees and residential conditions should be documented through contract appendices, handover forms, or notification records.','The court ruled regarding Xudong Qingting: clean-up shall be completed within a specified time and inspections improved; the established losses shall be assessed at 4620 yuan for purposes of liability, and the parties shall otherwise continue performing the contract in accordance with its terms.','Support','Wuhan, rental, passageway obstruction, service fee');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_f56fd53e','(2023) E 0111 Civil First-Instance No. 17209','Jiyuqiao Apartment Agency Service Fee Contract Dispute Case','court_wh_hongshan','Contract Dispute','Housing lease contract dispute','2023-06-06','Tenant Gu, landlord Han','Jiyuqiao Apartment Agency Service Fee Dispute: After the contract was not signed, the agency charged the full service fee, with the disputed amount approximately 12408 yuan.','This case arose from the agency-service-fee issue after the handover of Jiyuqiao Apartments. The tenant submitted materials alleging that the agent charged the full service fee after the contract signing fell through, while the landlord explained its handling by stating that “the disputed item was not recorded on the property handover form.”','Regarding the brokerage service fee issue at Jiyuqiao Apartments, the court relied primarily on the service agreement and property-viewing records, while considering the condition at handover and subsequent remedial measures; when the service has not been fully performed, the fee should be determined based on the actual amount of work completed.','Jiyuqiao Apartment Case Confirmation: When services have not been fully performed, the fee should be determined in light of the actual workload; matters involving door width, repairs, and service fees must be determined based on specific written evidence.','Regarding the Jiyuqiao apartment dispute, the court ordered a refund of service fees that were not actually incurred. The amount supported by documentation was determined to be 2163 yuan, and the remaining claims will be handled separately.','Partial support','Wuhan, rental, agency service fee, accessibility');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_eabee34f','(2024) E 0106 Civil First-Instance No. 27032','Jiyuqiao Jiayuan Early Lease Termination Contract Dispute Case','court_wh_wuchang','Contract Dispute','Housing lease contract dispute','2024-02-24','Tenant Chen and landlord Wu','Jiyuqiao Jiayuan Early Lease Termination Dispute: The tenant sought early termination due to changes in living conditions, with the disputed amount approximately 6503 yuan.','After moving into Jiyuqiao Jiayuan, tenant Chen claimed that the tenant sought early termination because of changed living conditions. During the handover at Jiyuqiao Jiayuan, the landlord submitted repair quotations and proof of payment, leading the parties to disagree over the timing of notice and the scope of the costs.','Regarding Jiyuqiao Jiayuan, the court examined the contract attachments and correspondence emails. These materials establish the course of the transaction. In light of the sequence in which the parties performed, it may be found that a penalty for breach that is excessively high when the losses are limited may be adjusted in accordance with the law; oral statements not supported by other evidence are not treated as the primary basis.','The key point of the ruling is that when liquidated damages are excessively high and the losses are limited, they may be adjusted in accordance with the law; in the Jiyuqiao Jiayuan lease, the deposit, accessibility facilities, and repair deadlines cannot rely solely on oral statements.','The Jiyuqiao Jiayuan early lease termination matter was ultimately handled under the principle of “assuming appropriate liability based on actual losses.” Upon calculation, the amount upheld was 4,549 yuan; the portion beyond the scope of the evidence was not upheld.','Rejected','Wuhan, Early Lease Termination, Door Width');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_8334e808','(2024) E01 Civil First Instance Case No. 2649','Jiyuqiao Lixiang Identity-Materials Contract Dispute Case','court_wh_intermediate','Contract Dispute','Housing lease contract dispute','2024-09-16','Tenant Tang, Landlord Jiang','Jiyuqiao Lixiang identity-materials dispute: The intermediary requested too many photos of identity documents before signing; the amount in dispute was approximately 1089 yuan.','After the rental relationship was established in Jiyuqiao Lixiang, an issue arose concerning the intermediary’s having requested too many photos of identity documents before signing. The landlord submitted repair quotations and proof of payment, after which the tenant and landlord each submitted evidence concerning the written attachments and actual losses.','In hearing the dispute over identity materials at Jiyuqiao Lixiang, the collegial panel first verified the information-collection page and chat records, then compared the contract appendices with the notice records. Based on the evidence currently available, rental verification should follow the principles of clear purpose and minimum necessity, and liability should be allocated according to the actual impact.','In the Jiyuqiao Lixiang case, the court clarified that rental verification should follow the principles of specified purpose and minimum necessity, and that key fees and living conditions should be documented through contract appendices, handover forms, or notice records.','The court ruled regarding Jiyuqiao Lixiang: irrelevant materials shall be deleted and no further processing shall be undertaken; the established losses shall be assessed at 656 yuan for purposes of liability, and the parties shall otherwise continue performing the contract as agreed.','Rejected','Wuhan, rental, identity documents, door width');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_76137f95','(2023) E 0102 Civil First-Instance No. 23135','Jiyuqiao Community written addendum contract dispute case','court_wh_jiangan','Contract Dispute','Housing lease contract dispute','2023-11-12','Tenant Luo, Landlord Ye','Jiyuqiao Community written addendum dispute: The parties disputed oral promises concerning ramp repairs and cleaning fees, with approximately 15695 yuan in dispute.','Regarding the Jiyuqiao Community property, both parties acknowledge that a dispute arose over the parties’ oral promises concerning ramp repairs and cleaning fees; because the parties had previously tried to coordinate through the property management company but failed to reach an agreement, they were unable to agree on how the deposit, repair, or service costs should be allocated.','The contract draft, recording summary, and timeline records in the Jiyuqiao Community case file corroborated one another. On this basis, the court held that key matters capable of being included in an addendum should primarily be governed by written agreements and strictly scrutinized promises by either party that were not included in the contract.','The Jiyuqiao Community case confirmed that key matters capable of being included in an addendum should primarily be governed by written agreements; the issues concerning door width, repairs, and service fees should all be determined by reference to specific written evidence.','Regarding the Jiyuqiao community dispute, the court ordered liability to be determined in accordance with the valid written terms. The amount supported by documentation was determined to be 6202 yuan, and the remaining claims will be handled separately.','Mediation','Wuhan, lease, written attachment, service fee');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_cb31495c','(2024) E 0111 Civil First-Instance No. 11657','Jiyuqiao Xinyuan Noise-Related Rent Reduction Contract Dispute Case','court_wh_hongshan','Contract Dispute','Housing lease contract dispute','2024-06-27','Tenant Xu, Landlord Shen','Jiyuqiao Xinyuan noise-related rent reduction dispute: prolonged construction noise exceeded a reasonable level of tolerance for daily living, with approximately 16911 yuan in dispute.','This case arose from the noise-related rent-reduction issue after the handover of Jiyuqiao Xinyuan. The tenant submitted materials alleging that prolonged construction noise exceeded a reasonable level of tolerance for normal living, while the landlord explained its handling by stating that “the landlord submitted repair quotations and proof of payment.”','For the noise-related rent reduction issue at Jiyuqiao Xinyuan, the court relied primarily on construction notices and continuous audio recordings, considered the handover condition and subsequent remedial measures, and held that the landlord should bear responsibility if, despite knowing of the significant impact, the landlord failed to disclose it.','The key holding is that a landlord should be held liable when the landlord knows of matters with a significant impact but fails to disclose them; in a Jiyuqiao Xinyuan rental, the deposit, accessibility facilities, and repair deadlines cannot be based solely on oral statements.','The Jiyuqiao Xinyuan noise-related rent reduction matter was ultimately resolved by “discretionarily reducing or waiving rent for the affected period.” Upon calculation, the supported amount was 5351 yuan; the portion beyond the scope of the evidence was not supported.','Rejected','Wuhan, lease, noise-related rent reduction, service fee');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_8f9604df','(2024) E 0106 Civil First-Instance No. 4602','Jiyuqiao Huating Deposit Refund Contract Dispute Case','court_wh_wuchang','Contract Dispute','Housing lease contract dispute','2024-01-14','Tenant Han, landlord Lin','Jiyuqiao Huating security deposit refund dispute: The landlord withheld the deposit on the grounds of deep cleaning, involving a disputed amount of approximately 31,565 yuan.','After moving into Jiyuqiao Huating, tenant Han claimed that the landlord withheld the deposit on the grounds of deep cleaning. During the handover at Jiyuqiao Huating, the tenant promptly sent written notice after discovering the problem, and the parties consequently disagreed over the notification timing and the scope of the costs.','Regarding Jiyuqiao Huating, the court examined transfer records and handover photographs. These materials establish the course of the transaction. In light of the sequence in which the parties performed, it may be found that marks from normal use cannot automatically be deemed damage; oral statements not supported by other evidence are not treated as the primary basis.','The court held in the Jiyuqiao Huating case that normal signs of use cannot automatically be deemed damage, and that key costs and living conditions should be documented through contract appendices, handover forms, or notification records.','The court ruled regarding Jiyuqiao Huating: return the portion of the deposit corresponding to losses that have not been proven; the established losses shall be counted toward liability in the amount of 28134 yuan, and the parties shall continue performing the remainder of the contract.','Support','Wuhan, Rental, Deposit Refund, Repairs');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_416e2f0f','(2025) E01 Civil First-Instance No. 15788','Jiyuqiao neighborhood contract dispute case over repair responsibility','court_wh_intermediate','Contract Dispute','Housing lease contract dispute','2025-12-11','Tenant Wu, Landlord Zhou','Jiyuqiao neighborhood repair responsibility dispute: After water seepage occurred in the bathroom, the parties disagreed over the repair deadline, with approximately 31896 yuan in dispute.','After the rental relationship in the Jiyuqiao neighborhood was established, an issue arose in which “the parties disagreed over the repair deadline after water seepage occurred in the bathroom.” The landlord submitted repair quotations and proof of payment, and the tenant and landlord subsequently each submitted evidence regarding the written addendum and actual losses.','In hearing the dispute over repair liability at Jiyuqiao Neighborhood, the collegial panel first verified the repair request work orders and on-site inspection reports, then compared the contract appendices with the notice records. Based on the evidence currently available, the landlord should bear corresponding liability for failing to make timely repairs after becoming aware of the issue, and liability should be allocated according to the actual impact.','The Jiyuqiao neighborhood case confirmed that a landlord who, after becoming aware of an issue, fails to arrange repairs promptly should bear corresponding liability; the issues concerning door width, repairs, and service fees should all be determined by reference to specific written evidence.','Regarding the Jiyuqiao neighborhood dispute, the court ordered the responsible party to bear the repair costs and compensate for reasonable losses. The amount supported by documentation was determined to be 2896 yuan, and the remaining claims will be handled separately.','Rejected','Wuhan, rental, repair responsibility, service fee');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_32ec0b4e','(2024) E0102 Civil First-Instance No. 16089','Jiyuqiao Linli Doorway-Width Disclosure Contract Dispute Case','court_wh_jiangan','Contract Dispute','Housing lease contract dispute','2024-05-17','Tenant Jiang, Landlord Gu','Jiyuqiao Linli doorway-width disclosure dispute: The intermediary orally promised that the entrance door would be a certain width, but measurements at delivery did not match; the amount in dispute was approximately 3558 yuan.','Regarding the Jiyuqiao Neighborhood property, both parties acknowledge that the agent orally promised a certain entrance-door width, but the measurement at handover did not match; because the tenant promptly sent written notice after discovering the issue, the parties were unable to agree on how the deposit, repair, or service costs should be allocated.','The chat records in the Jiyuqiao Linli case file, together with the doorway-width measurement photos and time records, corroborate one another. On this basis, the court held that key living conditions forming the basis for entering into a contract must be truthfully disclosed, and that promises by either party not included in the contract should be examined strictly.','The key holding is that essential residential conditions should be truthfully disclosed when they form the basis of the contract; in a Jiyuqiao neighborhood rental, the deposit, accessibility facilities, and repair deadlines cannot be based solely on oral statements.','The Jiyuqiao Linli doorway-width disclosure matter was ultimately resolved by refunding the service fee and adjusting liability for breach of contract. After calculation, the supported amount was 1178 yuan; the portion exceeding the scope of the evidence was not supported.','Mediation','Wuhan, rental, door width details, service fee');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_e310e94a','(2025) Hubei 0111 Civil First-Instance No. 28157','Jiyuqiao Xiaoyuan Elevator Shutdown Contract Dispute Case','court_wh_hongshan','Contract Dispute','Housing lease contract dispute','2025-08-11','Tenant Ye, Landlord Chen','Jiyuqiao Xiaoyuan Elevator Shutdown Dispute: The prolonged shutdown of the elevator in a high-rise residential building affected normal use, with the disputed amount approximately 5941 yuan.','This case arose from the elevator shutdown issue after the handover of Jiyuqiao Courtyard. The tenant submitted materials alleging that the prolonged shutdown of the elevator in the high-rise residential building affected normal use, while the landlord explained its handling by stating that “the landlord submitted repair quotations and proof of payment.”','For the elevator shutdown at Jiyuqiao Xiaoyuan, the court relied primarily on property management notices and maintenance records, considered the handover condition and subsequent remedial measures, and may reduce the rent at its discretion when the continuous shutdown reaches a level that affects habitation.','The court held in the Jiyuqiao Xiaoyuan case that rent may be reduced at the court’s discretion when a continuous service outage reaches a level that affects habitability, and that key costs and living conditions should be documented through contract appendices, handover forms, or notification records.','The court ruled regarding Jiyuqiao Xiaoyuan: reduce part of the rent for the period affected; the established losses shall be counted toward liability in the amount of 3935 yuan, and the parties shall continue performing the remainder of the contract.','Mediation','Wuhan, rental, elevator outage, service fee');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_8c97a94b','(2025) E0106 Civil First-Instance No. 5793','Jiyuqiao Residential Complex Passage Occupation Contract Dispute Case','court_wh_wuchang','Contract Dispute','Housing lease contract dispute','2025-01-06','Tenant Shen, Landlord Tang','Jiyuqiao Residential Complex Passage Occupation Dispute: A public ramp was repeatedly occupied by electric bicycles and miscellaneous items, with the disputed amount approximately 7658 yuan.','After moving into Jiyuqiao Residential Area, Tenant Shen claimed that the public ramp was repeatedly obstructed by electric bicycles and miscellaneous items. During the handover at Jiyuqiao Residential Area, the tenant promptly sent written notice after discovering the problem, and the parties consequently disagreed over the timing of notice and the scope of the costs.','Regarding Jiyuqiao Residential Area, the court examined on-site video and property-management complaint records. These materials establish the course of the transaction. In light of the sequence in which the parties performed, it may be found that the management party should take reasonable cleanup measures after receiving a report; oral statements not supported by other evidence are not treated as the primary basis.','Jiyuqiao Residential Complex Case Confirmation: After receiving a report, management should take reasonable cleanup measures; matters involving door width, repairs, and service fees must be determined based on specific written evidence.','Regarding the Jiyuqiao residential-area dispute, the court ordered the responsible party to complete the cleanup within a specified time limit and improve inspections. The amount supported by documentation was determined to be 3376 yuan, and the remaining claims will be handled separately.','Support','Wuhan, rental, passageway obstruction, door width');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_069f5f1a','(2024) E 01 Civil First Instance No. 19563','Jiyuqiao Dormitory Intermediary Service Fee Contract Dispute Case','court_wh_intermediate','Contract Dispute','Housing lease contract dispute','2024-09-21','Tenant Lin, Landlord Luo','Jiyuqiao Dormitory Intermediary Service Fee Dispute: After the lease signing failed to materialize, the intermediary charged the full service fee, with the disputed amount approximately 15529 yuan.','After the rental relationship at Jiyuqiao Dormitory was established, an issue arose in which “the intermediary charged the full service fee after the lease signing failed to materialize.” The parties attempted to resolve the matter through property management coordination but failed to reach an agreement. The tenant and landlord subsequently each submitted evidence concerning the written attachments and actual losses.','In hearing the dispute over an intermediary service fee at Jiyuqiao Dormitory, the collegial panel first verified the service agreement and property-viewing records, then compared the contract appendices with the notice records. Based on the evidence currently available, when the services have not been fully performed, the fee should be determined in light of the actual workload, and liability should be allocated according to the actual impact.','The key point of the judgment is that when services have not been fully performed, fees should be determined based on the actual amount of work completed; in the Jiyuqiao dormitory rental, the deposit, accessibility facilities, and repair deadline cannot be based solely on oral statements.','The Jiyuqiao Dormitory Intermediary Service Fee Matter was ultimately handled by “refunding service fees that had not actually been incurred.” Upon calculation, the supported amount was 12302 yuan; the portion beyond the scope of the evidence was not supported.','Mediation','Wuhan, rental, agency service fee, door width');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_e477475c','(2025) E0102 Civil First Instance No. 27690','Jiyuqiao Yating Early Lease-Termination Contract Dispute Case','court_wh_jiangan','Contract Dispute','Housing lease contract dispute','2025-03-04','Tenant Zhou, Landlord Xu','Jiyuqiao Yating early lease-termination dispute: The tenant requested early termination because of changes in the living conditions; the amount in dispute was approximately 6720 yuan.','Regarding the Jiyuqiao Yating property, both parties confirmed that the tenant had requested early termination due to changes in living conditions. Because the intermediary was unable to provide complete records of the service process, no agreement was reached on how the deposit, repair costs, or service fees would be borne.','The contract attachments, correspondence emails, and time records in the Jiyuqiao Yating case file corroborate one another. On this basis, the court held that a disproportionately high penalty may be adjusted in accordance with the law when the losses are limited, and that promises by either party not included in the contract should be examined strictly.','In the Jiyuqiao Yating case, the court clarified that when liquidated damages are excessively high and losses are limited, they may be adjusted in accordance with the law, and that key fees and living conditions should be documented through contract appendices, handover forms, or notice records.','The court ruled regarding Jiyuqiao Yating: appropriate liability shall be borne according to the actual losses; the established losses shall be assessed at 6264 yuan for purposes of liability, and the parties shall otherwise continue performing the contract as agreed.','Rejected','Wuhan, Early Lease Termination, Repairs');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_81e192e5','(2023) E 0111 Civil First-Instance No. 16898','Jiyuqiao Chunxiao Identity Materials Contract Dispute Case','court_wh_hongshan','Contract Dispute','Housing lease contract dispute','2023-10-21','Tenant Gu, landlord Han','Jiyuqiao Chunxiao identity materials dispute: before the contract was signed, the intermediary requested excessive photos of identification documents, with approximately 18313 yuan in dispute.','This case arose from an identity-documentation issue after the handover of Jiyuqiao Chunxiao. The tenant submitted materials claiming that the agent had requested too many photos of identity documents before the contract was signed, while the landlord explained its handling of the matter by stating that “the landlord submitted repair quotations and proof of payment.”','For the identity-document issue at Jiyuqiao Chunxiao, the court relied primarily on the information-collection page and chat records, considered the handover condition and subsequent remedial measures, and held that rental verification should follow the principles of specified purpose and minimum necessity.','The Jiyuqiao Chunxiao case confirmed that lease verification should follow the principles of a clearly defined purpose and minimum necessity; matters involving door width, maintenance, and service fees should all be determined based on specific written evidence.','Regarding the Jiyuqiao Chunxiao dispute, the court ordered the deletion of irrelevant materials and an end to further processing. The amount supported by documentation was determined to be 12417 yuan, and the remaining claims will be handled separately.','Mediation','Wuhan, rental, identity documents, service fee');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_47b6268f','(2024) E 0106 Civil First Instance No. 22233','Jiyuqiao Heyuan written-attachment contract dispute case','court_wh_wuchang','Contract Dispute','Housing lease contract dispute','2024-09-21','Tenant Chen and landlord Wu','Jiyuqiao Heyuan written-attachment dispute: The parties disputed their oral commitments regarding ramp repairs and cleaning fees, involving a disputed amount of approximately 23,780 yuan.','After moving into Jiyuqiao Heyuan, tenant Chen claimed that the parties disputed their oral agreement regarding ramp repairs and cleaning fees. During the handover at Jiyuqiao Heyuan, the agent was unable to provide complete records of the service process, leading the parties to disagree over the timing of notice and the scope of the costs.','Regarding Jiyuqiao Heyuan, the court examined the contract draft and a recording summary. These materials establish the course of the transaction. In light of the sequence in which the parties performed, it may be found that key matters capable of being included in an attachment should be governed primarily by the written agreement; oral statements not supported by other evidence are not treated as the primary basis.','The key holding is that key matters that can be included in an appendix should primarily be governed by written agreements; in the Jiyuqiao Heyuan lease, the deposit, accessibility facilities, and repair deadline cannot be based solely on oral statements.','The Jiyuqiao Heyuan written-attachment matter was ultimately handled under the principle of “determining liability based on valid written terms.” Upon calculation, the amount upheld was 8,746 yuan; the portion beyond the scope of the evidence was not upheld.','Mediation','Wuhan, lease, written attachment, repairs');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_a00eba6b','(2025) E01 Civil First Instance No. 26818','Jiyuqiao Qingting Noise-Related Rent Reduction Contract Dispute Case','court_wh_intermediate','Contract Dispute','Housing lease contract dispute','2025-08-14','Tenant Tang, Landlord Jiang','Jiyuqiao Qingting rent reduction dispute over construction noise: Long-term construction noise exceeded the reasonable tolerance for normal living, with approximately 11335 yuan in dispute.','After the rental relationship at Jiyuqiao Qingting was established, an issue arose in which “long-term construction noise exceeded the reasonable tolerance for normal living.” After discovering the issue, the tenant promptly sent written notice, and the tenant and landlord subsequently each submitted evidence regarding the written addendum and actual losses.','In hearing the rent-reduction dispute over noise at Jiyuqiao Qingting, the collegial panel first verified the construction notices and continuous audio recordings, then compared the contract appendices with the notice records. Based on the evidence currently available, the landlord should bear liability when, despite knowing of a significant impact, the landlord failed to disclose it, and liability should be allocated according to the actual impact.','The court held in the Jiyuqiao Qingting case that a landlord should bear liability when, despite knowing of a material impact, the landlord fails to disclose it, and that key costs and living conditions should be documented through contract appendices, handover forms, or notification records.','The court ruled regarding Jiyuqiao Qingting: rent for the affected period shall be reduced or waived as appropriate; the established losses shall be assessed at 3697 yuan for purposes of liability, and the parties shall otherwise continue performing the contract as agreed.','Mediation','Wuhan, lease, noise-related rent reduction, service fee');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_3c208338','(2025) E0102 Civil First Instance No. 20019','Shuiguohu Apartment Deposit Return Contract Dispute Case','court_wh_jiangan','Contract Dispute','Housing lease contract dispute','2025-05-19','Tenant Luo, Landlord Ye','Shuiguohu Apartment Deposit Return Dispute: The landlord withheld the deposit on the grounds of deep cleaning, with approximately 11336 yuan in dispute.','Regarding the property at Shuiguohu Apartment, both parties confirmed that the landlord withheld the deposit on the grounds of deep cleaning; because the intermediary was unable to provide complete records of the service process, they were unable to agree on the allocation of the deposit, repair, or service costs.','The transfer records, handover photographs, and date records in the Shuiguohu Apartment case file corroborate one another. On this basis, the court held that signs of normal use cannot automatically be deemed damage and strictly scrutinized promises not included in the contract.','Shuiguohu Apartment Case Confirmation: Signs of normal use cannot automatically be deemed damage; the issues involving door width, repairs, and service fees must all be determined based on specific written evidence.','Regarding the Shuiguohu Apartment dispute, the court ordered the return of the portion of the deposit corresponding to unproven losses, determining the amount supported by documentation as 4147 yuan; the remaining claims shall be handled separately.','Mediation','Wuhan, Rental, Deposit Refund, Accessibility');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_81ea7a2d','(2024) E 0111 Civil First-Instance No. 17314','Shuiguohu Jiayuan Repair Responsibility Contract Dispute Case','court_wh_hongshan','Contract Dispute','Housing lease contract dispute','2024-04-15','Tenant Xu, Landlord Shen','Shuiguohu Jiayuan repair responsibility dispute: After water seepage occurred in the bathroom, the parties disagreed over the repair period; the disputed amount was approximately 3,121 yuan.','This case arose from a repair responsibility issue after the handover of Shuiguohu Jiayuan. The tenant submitted materials alleging that, after water seepage in the bathroom, the parties disagreed over the repair deadline, while the landlord explained its handling by stating that “the parties had previously coordinated through the property management company but failed to reach an agreement.”','For the repair responsibility issue at Shuiguohu Jiayuan, the court treated repair requests and the on-site inspection report as the primary evidence, considered the condition at handover and subsequent remediation, and held that the landlord should bear the corresponding responsibility if, after learning of the issue, the landlord failed to make timely repairs.','The key point of the judgment is that a landlord bears corresponding liability if, after becoming aware of an issue, they fail to make repairs promptly; in the Shuiguohu Jiayuan lease, the deposit, accessibility facilities, and repair deadline cannot be left to oral statements alone.','The Shuiguohu Jiayuan repair responsibility matter was ultimately resolved by "assuming the repair costs and compensating reasonable losses." Upon calculation, the amount awarded was 2,966 yuan; the portion exceeding the scope of the evidence was not awarded.','Mediation','Wuhan, rental, repair responsibility, accessibility');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_ecec0804','(2025) E0106 Civil First-Instance No. 3044','Shuiguohu Lixiang door-width representation contract dispute case','court_wh_wuchang','Contract Dispute','Housing lease contract dispute','2025-09-04','Tenant Han, landlord Lin','Shuiguohu Lixiang door-width representation dispute: The intermediary verbally promised a specific entrance-door width, but the measured width at delivery did not match; the disputed amount was approximately 2372 yuan.','After moving into Shuiguohu Lixiang, tenant Han claimed that the agent had orally promised a certain entrance-door width, but the measurement at handover did not match. During the handover of Shuiguohu Lixiang, the agent was unable to provide complete records of the service process, and the parties consequently disagreed over the timing of the notice and the scope of the fees.','In relation to Shuiguohu Lixiang, the court examined chat records and photographs measuring the doorway width. These materials establish the course of the transaction. In light of the sequence in which both parties performed, it may be found that key living conditions, when forming the basis for entering into the contract, should be truthfully disclosed; oral statements unsupported by other evidence shall not serve as the primary basis.','In the Shuiguohu Lixiang case, the court made clear that when key living conditions constitute the basis for entering into the contract, they should be truthfully disclosed, and that key fees and living conditions should be documented through contract appendices, handover forms, or notice records.','The court ordered the following regarding Shuiguo Lake Lixiang: service fees shall be refunded and liability for breach of contract adjusted, with the established loss of 599 yuan included in the liability; the parties shall continue performing the remainder of the contract.','Support','Wuhan, rental, door width explanation, deposit');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_8994e038','(2025) E01 Civil First Instance No. 2246','Shuiguohu Community Elevator Shutdown Contract Dispute Case','court_wh_intermediate','Contract Dispute','Housing lease contract dispute','2025-11-10','Tenant Wu, Landlord Zhou','Shuiguohu Community Elevator Shutdown Dispute: The prolonged shutdown of the elevator in a high-rise residential building affected normal use, with the disputed amount approximately RMB 13342.','After the lease relationship was established in Shuiguohu Community, the issue arose that “the prolonged shutdown of the elevator in a high-rise residential building affected normal use.” After discovering the issue, the tenant promptly sent written notice, and the tenant and landlord subsequently each submitted evidence regarding the written attachments and actual losses.','In hearing the dispute over the elevator shutdown at Shuiguohu Community, the adjudicating panel first checked the property management announcements and maintenance records, then compared the contract appendices with the notification records. Based on the existing evidence, rent may be reduced as appropriate when the continuous shutdown reaches a level that affects habitability, and liability should be apportioned according to the actual impact.','The Shuiguohu Community case confirmed that rent may be reduced at the court’s discretion when a prolonged shutdown reaches a level that affects living conditions; the issues of doorway width, repairs, and service fees should all be determined based on specific written evidence.','Regarding the Shuiguohu Community dispute, the court ordered a partial rent reduction for the period of impact, determining the amount supported by documentation as 8561 yuan; the remaining claims shall be handled separately.','Support','Wuhan, Elevator Outage, Deposit');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_056e0e2a','(2024) E 0102 Civil First-Instance No. 5808','Shuiguohu Xinyuan passage-occupation contract dispute case','court_wh_jiangan','Contract Dispute','Housing lease contract dispute','2024-07-17','Tenant Jiang, Landlord Gu','Shuiguohu Xinyuan passage-occupation dispute: The public ramp was repeatedly occupied by electric bicycles and miscellaneous items, with the disputed amount approximately 26733 yuan.','Regarding the property at Shuiguohu Xinyuan, both parties acknowledged that the common ramp had repeatedly been obstructed by electric bicycles and miscellaneous items; because the tenant promptly sent written notice after discovering the problem, they were unable to agree on the allocation of the deposit, repair, or service fees.','The on-site videos and property-management complaint records in the Shuiguohu Xinyuan case file corroborate each other with the timeline records. On this basis, the court held that the management party should take reasonable cleaning measures after receiving a report, and that the parties'' promises not included in the contract should be examined strictly.','The key holding is that after receiving a report, the management party should take reasonable cleaning measures; in the Shuiguohu Xinyuan lease, the deposit, accessibility facilities, and repair deadline cannot be based solely on oral statements.','The Shuiguohu Xinyuan passage-occupation matter was ultimately implemented as “clear within a specified period and improve inspections.” Upon calculation, the supported amount was 24575 yuan; the portion exceeding the scope of the evidence was not supported.','Partial support','Wuhan, rental, passageway obstruction, repairs');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_29af849f','(2025) E 0111 Civil First-Instance No. 13723','Shuiguohu Huating Real Estate Brokerage Service Fee Contract Dispute Case','court_wh_hongshan','Contract Dispute','Housing lease contract dispute','2025-03-12','Tenant Ye, Landlord Chen','Shuiguohu Huating brokerage service fee dispute: After the contract was not concluded, the broker charged the full service fee; the disputed amount was approximately 16,024 yuan.','This case arose from a dispute over an intermediary service fee after the handover of Shuiguohu Huating. The tenant submitted materials stating that the agent collected the full service fee after the contract was not concluded, while the landlord explained its handling by stating that “the tenant promptly sent written notice after discovering the problem.”','For the intermediary service fee issue at Shuiguohu Huating, the court treated the service agreement and viewing records as the primary evidence, considered the condition at handover and subsequent remediation, and held that where the services were not fully performed, the fee should be determined based on the actual amount of work completed.','In the Shuiguohu Huating case, the court made clear that when services have not been fully performed, the fees should be determined based on the actual workload, and that key fees and living conditions should be documented through contract appendices, handover forms, or notice records.','The court ordered the following regarding Shuiguo Lake Huating: service fees for services not actually provided shall be refunded, with the established loss of 15298 yuan included in the liability; the parties shall continue performing the remainder of the contract.','Rejected','Wuhan, rental, agency service fee, repairs');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_9b5571b6','(2025) E0106 Civil First-Instance No. 26635','Shuiguohu Neighborhood Early Lease Termination Contract Dispute Case','court_wh_wuchang','Contract Dispute','Housing lease contract dispute','2025-01-28','Tenant Shen, Landlord Tang','Shuiguohu Neighborhood Early Lease Termination Dispute: The tenant requested early termination because living conditions had changed, with the disputed amount approximately RMB 21023.','Tenant Shen moved into Shuiguohu District and later claimed that the tenant requested early termination because of changes in the living conditions; during the handover at Shuiguohu District, the landlord submitted repair quotations and proof of payment, whereupon the parties disputed the timing of the notice and the scope of the costs.','In relation to Shuiguohu Jiequ, the court examined the contract appendices and correspondence emails. These materials establish the course of the transaction. In light of the sequence in which both parties performed, it may be found that liquidated damages may be adjusted in accordance with the law when they are excessively high and the losses are limited; oral statements unsupported by other evidence shall not serve as the primary basis.','Confirmation in the Shuiguohu neighborhood case: Liquidated damages that are excessively high relative to limited losses may be adjusted in accordance with the law; issues involving door width, repairs, and service fees must all be determined based on specific written evidence.','Regarding the Shuiguohu neighborhood dispute, the court ordered liability to be assumed appropriately based on the actual losses, determining the amount supported by documentation to be 502 yuan; the remaining claims were addressed separately.','Support','Wuhan, Early Lease Termination, Accessibility');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_89a110f8','(2025) E01 Civil First Instance No. 23731','Shuiguohu Linli identity-materials contract dispute case','court_wh_intermediate','Contract Dispute','Housing lease contract dispute','2025-01-02','Tenant Lin, Landlord Luo','Shuiguohu Linli identity-materials dispute: The intermediary requested too many photos of identity documents before signing, with the disputed amount approximately 21990 yuan.','After the tenancy relationship in Shuiguohu Linli was established, an issue arose in which “the intermediary requested too many photos of identity documents before signing.” The parties attempted to resolve the matter through property-management coordination but failed to reach an agreement, after which the tenant and landlord each submitted evidence regarding the written attachments and actual losses.','In hearing the dispute over identity documentation at Shuiguohu Linli, the adjudicating panel first checked the information-collection page and chat records, then compared the contract appendices with the notification records. Based on the existing evidence, rental verification should follow the principles of defined purpose and minimum necessity, and liability should be apportioned according to the actual impact.','The key holding is that lease verification should follow the principles of purpose specification and data minimization; in the Shuiguohu Neighborhood lease, the deposit, accessibility facilities, and repair deadlines cannot rely solely on oral statements.','The Shuiguohu Linli identity-materials matter was ultimately resolved by “deleting irrelevant materials and ceasing further processing.” After calculation, the supported amount was 9323 yuan; any portion exceeding the scope of the evidence was not supported.','Support','Wuhan, rental, identity documents, repairs');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_ee7041c2','(2023) E 0102 Civil First-Instance No. 12403','Shuiguohu Xiaoyuan written addendum contract dispute case','court_wh_jiangan','Contract Dispute','Housing lease contract dispute','2023-03-08','Tenant Zhou, Landlord Xu','Shuiguohu Xiaoyuan written addendum dispute: The parties disputed oral promises concerning ramp repairs and cleaning fees, with the disputed amount approximately 33121 yuan.','Regarding the property at Shuiguohu Xiaoyuan, both parties acknowledged that a dispute had arisen over their oral commitments concerning ramp repairs and cleaning fees; because they had attempted to resolve the matter through the property management service but failed to reach an agreement, they were unable to agree on the allocation of the deposit, repair, or service fees.','The draft contract and recording summary in the Shuiguohu Xiaoyuan case file corroborate each other with the timeline records. On this basis, the court held that key matters capable of being included in the addendum should primarily be governed by written agreements, and that the parties'' promises not included in the contract should be examined strictly.','In the Shuiguohu Xiaoyuan case, the court made clear that key matters capable of being included in an appendix should primarily be governed by written agreement, and that key fees and living conditions should be documented through contract appendices, handover forms, or notice records.','The court ordered the following regarding Shuiguo Lake Xiaoyuan: liability shall be determined according to the valid written terms, with the established loss of 17751 yuan included in the liability; the parties shall continue performing the remainder of the contract.','Support','Wuhan, lease, written attachment, door width');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_d5794d01','(2024) Hubei 0111 Civil First Instance No. 8358','Shuiguohu Residential Community Noise-Related Rent Reduction Contract Dispute Case','court_wh_hongshan','Contract Dispute','Housing lease contract dispute','2024-06-01','Tenant Gu, landlord Han','Shuiguohu Residential Community Noise-Related Rent Reduction Dispute: Prolonged construction noise exceeded a reasonable tolerance level for everyday living, with approximately 15132 yuan in dispute.','This case arose from a dispute over a rent reduction due to noise after the handover of Shuiguohu Zhuqu. The tenant submitted materials stating that prolonged construction noise exceeded a reasonable level of tolerance for normal living, while the landlord explained its handling by stating that “the agent was unable to provide complete records of the service process.”','For the noise-related rent reduction issue at Shuiguohu Residential Community, the court treated the construction notices and continuous audio recordings as the primary evidence, considered the condition at handover and subsequent remediation, and held that the landlord should be liable if the landlord knew of the significant impact but failed to disclose it.','Shuiguohu Residential Community Case Confirmation: When a landlord knows of a significant impact but fails to disclose it, the landlord should be held liable; the issues involving door width, repairs, and service fees must all be determined based on specific written evidence.','Regarding the Shuiguohu Residential Area dispute, the court ordered an appropriate reduction or waiver of rent for the affected period, determining the amount supported by documentation as 2052 yuan; the remaining claims shall be handled separately.','Support','Wuhan, lease, noise-related rent reduction, door width');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_6a4925e6','(2024) E 0106 Civil First Instance No. 19988','Shuiguohu Dormitory Deposit Refund Contract Dispute Case','court_wh_wuchang','Contract Dispute','Housing lease contract dispute','2024-09-18','Tenant Chen and landlord Wu','Shuiguohu dormitory deposit refund dispute: The landlord withheld the deposit on the grounds of deep cleaning, with the disputed amount approximately 17623 yuan.','After moving into Shuiguohu Dormitory, tenant Chen claimed that the landlord withheld the deposit on the grounds of deep cleaning. During the handover at Shuiguohu Dormitory, the agent was unable to provide complete records of the service process, and the parties consequently disputed the timing of the notice and the scope of the costs.','In relation to Shuiguohu Sushe, the court examined transfer records and handover photographs. These materials establish the course of the transaction. In light of the sequence in which both parties performed, it may be found that signs of ordinary use cannot automatically be deemed damage; oral statements unsupported by other evidence shall not serve as the primary basis.','The key point of the judgment is that signs of normal use cannot automatically be deemed damage; in the Shuiguohu dormitory rental, the deposit, accessibility facilities, and repair deadline cannot be based solely on oral statements.','The Shuiguohu Dormitory deposit refund matter was ultimately resolved by "refunding the portion of the deposit for which no loss was proven." Upon calculation, the amount awarded was 13,692 yuan; the portion exceeding the scope of the evidence was not awarded.','Rejected','Wuhan, lease, deposit return, security deposit');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_287fbef3','(2024) E01 Civil First Instance Case No. 9079','Shuiguohu Yating repair-responsibility contract dispute case','court_wh_intermediate','Contract Dispute','Housing lease contract dispute','2024-03-25','Tenant Tang, Landlord Jiang','Shuiguohu Yating repair-responsibility dispute: After water seepage occurred in the bathroom, the parties disagreed over the repair period; the disputed amount was approximately 18645 yuan.','After the tenancy relationship in Shuiguohu Yating was established, an issue arose in which “the parties disagreed over the repair period after water seepage occurred in the bathroom.” The landlord submitted repair quotations and proof of payment, after which the tenant and landlord each submitted evidence regarding the written attachments and actual losses.','In hearing the dispute over repair liability at Shuiguohu Yating, the adjudicating panel first checked the repair request orders and on-site inspection reports, then compared the contract appendices with the notification records. Based on the existing evidence, a landlord who fails to make timely repairs after becoming aware of the issue should bear the corresponding liability, and liability should be apportioned according to the actual impact.','In the Shuiguohu Yating case, the court made clear that a lessor who fails to make timely repairs after becoming aware of the need bears corresponding liability, and that key fees and living conditions should be documented through contract appendices, handover forms, or notice records.','The court ordered the following regarding Shuiguo Lake Yating: repair costs shall be borne and reasonable losses compensated, with the established loss of 12017 yuan included in the liability; the parties shall continue performing the remainder of the contract.','Support','Wuhan, rental, repair responsibility, deposit');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_79f8bb8a','(2024) E 0102 Civil First-Instance No. 4016','Shuiguohu Chunxiao Door-Width Specification Contract Dispute Case','court_wh_jiangan','Contract Dispute','Housing lease contract dispute','2024-05-27','Tenant Luo, Landlord Ye','Shuiguohu Chunxiao Door-Width Specification Dispute: The intermediary verbally promised the entrance door width, but the measurement at handover did not match; the disputed amount was approximately 23,530 yuan.','Regarding the property at Shuiguohu Chunxiao, both parties acknowledged that the intermediary had orally promised a certain entrance-door width, but the measurement at handover did not match; because the disputed item was not recorded on the property handover form, they were unable to agree on the allocation of the deposit, repair, or service fees.','The chat records and photographs measuring the doorway width in the Shuiguohu Chunxiao case file corroborate each other with the timeline records. On this basis, the court held that key living conditions should be truthfully disclosed when they constitute the basis for entering into the contract, and that the parties'' promises not included in the contract should be examined strictly.','The Shuiguohu Chunxiao case confirmed that key living conditions should be truthfully disclosed when they constitute the basis for entering into the contract; the doorway width, repairs, and service fees involved should all be determined by reference to specific written evidence.','Regarding the Shuiguohu Chunxiao dispute, the court ordered a refund of service fees and an adjustment of liability for breach of contract, determining the amount supported by documentation as 13172 yuan; the remaining claims shall be handled separately.','Rejected','Wuhan, rental, door width explanation, deposit');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_269a9bc8','(2023) E 0111 Civil First-Instance No. 18565','Shuiguohu Heye Elevator Shutdown Contract Dispute Case','court_wh_hongshan','Contract Dispute','Housing lease contract dispute','2023-01-01','Tenant Xu, Landlord Shen','Shuiguohu Heye elevator shutdown dispute: The prolonged shutdown of the elevator in a high-rise residential building affected normal use; the disputed amount was approximately 27,626 yuan.','This case arose from the elevator being out of service after the handover of Shuiguohu Heyuan. The tenant submitted materials alleging that the prolonged outage of the elevator in the high-rise residence affected normal use, while the landlord explained its handling by stating that “the parties had previously coordinated through the property management company but failed to reach an agreement.”','For the elevator outage issue at Shuiguohu Heyuan, the court treated property-management notices and maintenance records as the primary evidence, considered the condition at handover and subsequent remediation, and held that rent may be reduced at its discretion when the prolonged outage affected the ability to reside in the premises.','The key point of the ruling is that rent may be reduced at the court’s discretion when a prolonged service suspension reaches a level that affects habitability; in the Shuiguohu Heye lease, the deposit, accessibility facilities, and repair deadlines cannot rely solely on oral statements.','The Shuiguohu Heye elevator shutdown matter was ultimately resolved by "reducing part of the rent in proportion to the period affected." Upon calculation, the amount awarded was 12,573 yuan; the portion exceeding the scope of the evidence was not awarded.','Mediation','Wuhan, Elevator Outage, Deposit');
