INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_4ff60803','(2025) E 0111 Civil First-Instance No. 19177','Qinghe Xinyuan Noise-Related Rent Reduction Contract Dispute Case','court_wh_hongshan','Contract Dispute','Housing lease contract dispute','2025-09-16','Tenant Xu, Landlord Shen','Qinghe Xinyuan noise-related rent reduction dispute: Prolonged construction noise exceeded the reasonable tolerance level for normal living, with the disputed amount approximately 29920 yuan.','This case arose from a rent-reduction issue due to noise after the handover of Qinghe Xinyuan. The tenant submitted materials claiming that prolonged construction noise exceeded reasonable tolerance for normal living, while the landlord explained its handling of the matter by stating that “the parties had previously coordinated through the property management company but failed to reach an agreement.”','For the noise-related rent reduction issue at Qinghe Xinyuan, the court relied primarily on construction notices and continuous audio recordings, considered the handover condition and subsequent remedial measures, and held that the landlord should bear responsibility if, despite knowing of the significant impact, the landlord failed to disclose it.','The key holding is that a landlord should be held liable when the landlord knows of matters with a significant impact but fails to disclose them; in a Qinghe Xinyuan rental, the deposit, accessibility facilities, and repair deadlines cannot be based solely on oral statements.','The Qinghe Xinyuan noise-related rent reduction matter was ultimately resolved by “discretionarily reducing or waiving rent for the affected period.” Upon calculation, the supported amount was 21628 yuan; the portion exceeding the scope of the evidence was not supported.','Partial support','Wuhan, lease, noise-related rent reduction, security deposit');
